// Original researched event sheets. Date references and reading links are included per event.
export const eventDetails={"2026-11-01:world-vegan-day":{"id":"2026-11-01:world-vegan-day","date":"2026-11-01","verification":"organiser","summary":"Plant-based food gets its moment on 1 November. 🌱 World Vegan Day celebrates the vegan community and invites anyone curious to explore the choices, recipes and ideas behind living without animal products.","sections":[{"heading":"How it began","body":"The Vegan Society created World Vegan Day in 1994 for its fiftieth anniversary. The society began in 1944, when its founders coined the word vegan. The November date now sits within World Vegan Month, giving communities time for events, conversations and practical food inspiration."},{"heading":"More than a menu","body":"Veganism includes questions about the use of animals beyond food, while a first step for a curious cook can be much smaller: one familiar dish made differently. Beans, mushrooms, lentils and vegetables offer plenty of ways to experiment. You do not need a cupboard of expensive specialist products to join the conversation."}],"activity":{"text":"Pick a comfort-food recipe from the Vegan Society collection and cook it for someone who thinks vegan food is boring.","label":"Find a vegan recipe","url":"https://www.vegansociety.com/lifestyle/recipes"},"sources":[{"label":"The Vegan Society: World Vegan Day","url":"https://www.vegansociety.com/news/news/world-vegan-day","dateEvidence":true},{"label":"Vegan Society recipe collection","url":"https://www.vegansociety.com/lifestyle/recipes","dateEvidence":false}]},"2026-11-02:national-deviled-egg-day":{"id":"2026-11-02:national-deviled-egg-day","date":"2026-11-02","verification":"independent-calendar","summary":"The humble boiled egg puts on party clothes. 🥚 This informal US food day on 2 November celebrates filled egg halves, from a classic mustard-and-mayo mixture to something with a little more bite.","sections":[{"heading":"What makes an egg devilled?","body":"Hard-boiled eggs are halved, their yolks removed and mixed with flavourings, and the filling returned to the whites. Mustard, mayonnaise and a dusting of paprika are familiar choices. Other names include stuffed eggs, dressed eggs and eggs mimosa; the idea is adaptable even when the name sounds dramatic."},{"heading":"A tiny buffet experiment","body":"The day is listed by independent food calendars; its creator is not well documented. Make it your own by comparing two toppings rather than cooking an enormous party spread. Chives, a little pickle or smoked paprika can turn the same basic filling into a different snack. A small batch is enough for a proper taste test."}],"activity":{"text":"Make the classic recipe, then give half your eggs a different topping and hold a very serious two-person judging panel.","label":"Make devilled eggs","url":"https://www.bbcgoodfood.com/recipes/classic-devilled-eggs"},"sources":[{"label":"National Day Calendar: Deviled Egg Day","url":"https://nationaldaycalendar.com/celebrations/national-deviled-egg-day-november-2/","dateEvidence":true},{"label":"Good Food: classic devilled eggs","url":"https://www.bbcgoodfood.com/recipes/classic-devilled-eggs","dateEvidence":false}]},"2026-11-03:world-jellyfish-day":{"id":"2026-11-03:world-jellyfish-day","date":"2026-11-03","verification":"organiser","summary":"A day for the sea’s floating oddities. 🪼 Aquariums mark 3 November by introducing jellyfish, animals whose drifting shapes can look delicate, futuristic and slightly impossible all at the same time.","sections":[{"heading":"Not actually fish","body":"Jellyfish are invertebrates, so the familiar name does not make them fish. Their translucent bodies and pulsing movement make them popular aquarium subjects. Different species can look surprisingly unlike one another: a room of moon jellies is only one small glimpse of the wider variety of these animals."},{"heading":"A window into another world","body":"Aquariums including Vancouver Aquarium and SEA LIFE have marked World Jellyfish Day with educational activities and exhibits. This is a wildlife-awareness occasion rather than a public holiday. Watching an aquarium display can be a good chance to slow down and notice the animals’ movement instead of treating the tank as a background for a quick photograph."}],"activity":{"text":"Explore the aquarium’s jellyfish exhibit guide, then see whether you can recognise a species the next time you visit an aquarium.","label":"Meet some jellyfish","url":"https://www.vanaqua.org/explore/exhibits/wondrous-jellies/"},"sources":[{"label":"Vancouver Aquarium: Wondrous Jellies","url":"https://www.vanaqua.org/explore/exhibits/wondrous-jellies/","dateEvidence":true},{"label":"SEA LIFE London: World Jellyfish Day","url":"https://www.visitsealife.com/london/information/news/world-jellyfish-day-barrel-jellyfish/","dateEvidence":true}]},"2026-11-04:eating-healthy-day":{"id":"2026-11-04:eating-healthy-day","date":"2026-11-04","verification":"organiser","summary":"Eat Smart Day makes room for food that is enjoyable, practical and varied. 🥦 Observed on the first Wednesday of November, it is a prompt for small changes rather than a one-day food overhaul.","sections":[{"heading":"A name that changed","body":"The American Heart Association’s earlier National Eating Healthy Day ran under that name from 2009 to 2016. Eat Smart Day and Eat Smart Month followed in 2017 as part of its Healthy for Good initiative. The first Wednesday falls on 4 November in 2026."},{"heading":"Keep it doable","body":"The campaign emphasises food choices people can sustain, including cooking skills and everyday ingredients. Trying one unfamiliar vegetable, finding a meal you can make on a busy evening, or learning a flavourful way to use beans is more useful than declaring your whole kitchen off limits. This awareness day is general education, not personalised dietary advice."}],"activity":{"text":"Choose one recipe or cooking skill from the AHA’s Eat Smart resources and try it with ingredients you will actually use again.","label":"Explore Eat Smart ideas","url":"https://www.heart.org/en/healthy-living/healthy-eating/eat-smart/"},"sources":[{"label":"Checkiday: Eat Smart Day date and former name","url":"https://www.checkiday.com/61bce29b58fd5d81c3c835ede354ca7e/eat-smart-day","dateEvidence":true},{"label":"American Heart Association: Eat Smart","url":"https://www.heart.org/en/healthy-living/healthy-eating/eat-smart/","dateEvidence":false}],"researchNote":"The current campaign name is Eat Smart Day. National Eating Healthy Day was the name used from 2009–2016. Date remains the first Wednesday in November.","title":"Eat Smart Day"},"2026-11-06:national-nachos-day":{"id":"2026-11-06:national-nachos-day","date":"2026-11-06","verification":"independent-calendar","summary":"Crunch, melted cheese and a conveniently shareable excuse for dinner. 🧀 National Nachos Day is an informal US food celebration on 6 November, with room for both the simple original idea and heavily loaded versions.","sections":[{"heading":"The name behind the snack","body":"Nachos are associated with Ignacio “Nacho” Anaya and Piedras Negras, Mexico, in the 1940s. The familiar origin story describes tortilla pieces topped with cheese and jalapeños for hungry visitors. The dish travelled widely and developed into the many restaurant, stadium and homemade versions served today."},{"heading":"Build a better bite","body":"A mountain of toppings looks impressive, but a smaller, evenly spread layer is often easier to share. You can put salsa, beans, herbs or guacamole beside the tray so people can choose their own additions. The November celebration’s founder is uncertain; the food itself has a much clearer connection to Mexican cooking and border-town history."}],"activity":{"text":"Try Good Food’s speedy nachos and let everyone nominate one topping. Give the winning combination an unnecessarily grand name.","label":"Make speedy nachos","url":"https://www.bbcgoodfood.com/recipes/speedy-nachos"},"sources":[{"label":"National Day Calendar: National Nachos Day","url":"https://nationaldaycalendar.com/celebrations/national-nachos-day-november-6","dateEvidence":true},{"label":"Good Food: nachos recipe","url":"https://www.bbcgoodfood.com/recipes/speedy-nachos","dateEvidence":false}]},"2026-11-07:national-hug-a-bear-day":{"id":"2026-11-07:national-hug-a-bear-day","date":"2026-11-07","verification":"independent-calendar","summary":"This one is for the teddy bear, not a real bear. 🧸 The playful 7 November observance is a small excuse to appreciate a familiar soft toy and the memories attached to it.","sections":[{"heading":"A comfort-object celebration","body":"Hug a Bear Day appears in independent calendars as an annual informal observance on 7 November. It is not a wildlife-handling event or a public holiday. Its broad appeal is easy to understand: a well-loved toy can carry the story of a childhood bedroom, a gift or a person who bought it."},{"heading":"Let your teddy tell a story","body":"If you have an old bear tucked away, bring it out and ask what you remember about it. Who gave it to you? Did it have a name? A missing eye, flattened fur or a repair might be the most interesting part. Photographing it or telling its story can be a nicer way to mark the day than buying a new one."}],"activity":{"text":"Find a bear or another old soft toy and send someone the story behind it, complete with its original name if you remember.","label":"See Hug a Bear Day","url":"https://www.checkiday.com/11/7/2026"},"sources":[{"label":"Checkiday: 7 November 2026, Hug a Bear Day","url":"https://www.checkiday.com/11/7/2026","dateEvidence":true}]},"2026-11-08:national-cappuccino-day":{"id":"2026-11-08:national-cappuccino-day","date":"2026-11-08","verification":"independent-calendar","summary":"A small cup with a very good foam hat. ☕ This informal US observance on 8 November celebrates cappuccino, the Italian-style combination of espresso, warm milk and milk foam.","sections":[{"heading":"What is in the cup?","body":"A cappuccino begins with espresso and adds heated milk and a generous layer of foam. The name is associated with the colour of the robes worn by Capuchin friars. It is a distinct drink, even though café menus offer plenty of neighbouring combinations of coffee and milk."},{"heading":"Make the pause part of it","body":"National Day Calendar lists 8 November and notes that the observance’s exact beginnings are still being researched. You can celebrate without turning your kitchen into a café: order a cup somewhere new, notice its texture, or try frothing milk at home. Comparing a café drink with your homemade attempt can be more entertaining than chasing a flawless latte-art heart."}],"activity":{"text":"Try the cappuccino guide, then give your foam creation a name even if it looks more like a cloud than a heart.","label":"Make a cappuccino","url":"https://www.bbcgoodfood.com/recipes/cappuccino"},"sources":[{"label":"National Day Calendar: Cappuccino Day","url":"https://nationaldaycalendar.com/celebrations/national-cappuccino-day-october-8","dateEvidence":true},{"label":"Good Food: cappuccino","url":"https://www.bbcgoodfood.com/recipes/cappuccino","dateEvidence":false}]},"2026-11-09:world-freedom-day":{"id":"2026-11-09:world-freedom-day","date":"2026-11-09","verification":"independent-calendar","summary":"World Freedom Day is a US commemoration associated with the fall of the Berlin Wall on 9 November 1989. It invites reflection on freedom, divided communities and the people who challenged political repression.","sections":[{"heading":"Why 9 November?","body":"The opening of the Berlin Wall became a defining image of the end of the Cold War in Europe. A US presidential proclamation in 2001 designated 9 November as World Freedom Day, explicitly linking the observance to that anniversary. Independent calendars continue to list the date annually."},{"heading":"History through people’s lives","body":"A concrete border also meant interrupted journeys, separated relatives and difficult choices about leaving home. Learning about the wall through personal accounts can make the history more concrete than a photograph of celebrating crowds alone. The day’s name should not be mistaken for a United Nations observance or a worldwide public holiday; its commemorative framing is specifically rooted in the United States."}],"activity":{"text":"Read the original proclamation, then discuss which everyday freedom you would notice losing first and why.","label":"Read the historical proclamation","url":"https://georgewbush-whitehouse.archives.gov/news/releases/2001/11/20011109-23.html"},"sources":[{"label":"US National Archives: 2001 proclamation","url":"https://georgewbush-whitehouse.archives.gov/news/releases/2001/11/20011109-23.html","dateEvidence":true},{"label":"National Day Calendar: World Freedom Day","url":"https://nationaldaycalendar.com/celebrations/world-freedom-day-november-9/","dateEvidence":true}],"researchNote":"US commemorative observance, not a UN day or global public holiday. The archival proclamation confirms its origin; the recurring 2026 calendar date is independently listed."},"2026-11-11:armistice-day":{"id":"2026-11-11:armistice-day","date":"2026-11-11","verification":"organiser","summary":"At 11am on 11 November, the UK pauses to remember service and sacrifice. Armistice Day marks the agreement that halted fighting on the Western Front in 1918, before the peace settlements that followed.","sections":[{"heading":"The eleventh hour","body":"The armistice came into effect at 11am on 11 November 1918. The Royal British Legion continues to invite a two-minute silence at that time each year. War memorials, workplaces, schools and individuals can all take part; a formal ceremony is not required for a thoughtful act of remembrance."},{"heading":"Different dates, shared remembrance","body":"Armistice Day is always 11 November. Remembrance Sunday is a separate date, falling on the second Sunday of November, and carries the national Cenotaph service in London. Remembering the distinction helps when planning a local event. Remembrance can include people from different communities and generations, and can be approached quietly and respectfully without assuming everyone has the same experience of war."}],"activity":{"text":"Read the Legion’s account of the date, then pause for two minutes at 11am or find a local act of remembrance.","label":"Explore Armistice Day","url":"https://www.britishlegion.org.uk/get-involved/remembrance/armistice-day"},"sources":[{"label":"Royal British Legion: Armistice Day","url":"https://www.britishlegion.org.uk/get-involved/remembrance/armistice-day","dateEvidence":true}]},"2026-11-12:world-pneumonia-day":{"id":"2026-11-12:world-pneumonia-day","date":"2026-11-12","verification":"organiser","summary":"World Pneumonia Day on 12 November highlights a serious global health challenge and the importance of fair access to prevention, diagnosis and treatment. The Every Breath Counts Coalition coordinates awareness and advocacy around the date.","sections":[{"heading":"Why this day exists","body":"The first World Pneumonia Day took place in 2009, bringing together clinicians, researchers, advocates and other organisations concerned about preventable deaths. The campaign now addresses pneumonia across the life course, including its effects on young children and older adults. Its 2026 theme is A New Era of Pneumonia Control."},{"heading":"Awareness with a purpose","body":"Campaign work looks beyond a single illness to the systems people depend on: clean air, vaccination programmes, timely assessment and access to medicines and medical oxygen. The day is an opportunity to learn how those services are delivered and where gaps remain. Public campaign information can explain the wider issue; it is not a substitute for advice about an individual’s symptoms or care."}],"activity":{"text":"Explore the coalition’s 2026 campaign and choose one resource that helps explain why access to medical oxygen matters.","label":"Explore the 2026 campaign","url":"https://stoppneumonia.org/latest/world-pneumonia-day/"},"sources":[{"label":"Every Breath Counts: World Pneumonia Day","url":"https://stoppneumonia.org/latest/world-pneumonia-day/","dateEvidence":true}]},"2026-11-13:national-hug-a-musician-day":{"id":"2026-11-13:national-hug-a-musician-day","date":"2026-11-13","verification":"independent-calendar","summary":"A little applause for the people behind your favourite soundtrack. 🎶 This informal observance on 13 November is about appreciating musicians; a kind message is an excellent alternative to an unexpected hug.","sections":[{"heading":"The work behind the music","body":"A performance is the visible part of a much longer process: practice, preparation, rehearsal and often the work of several people. The day appears in independent calendars and has been marked by community organisations, including a public library calendar for November 2026. Its exact founder is not clearly documented."},{"heading":"Make the appreciation specific","body":"Think of someone whose music has accompanied a particular moment, or a local performer you have enjoyed. Tell them what you liked about their playing, writing or singing. You can also share a track using an official link, recommend a local performance or simply listen to an album without doing five other things. Appreciation does not need to involve physical contact or an expensive gesture."}],"activity":{"text":"Send a musician a specific compliment, or make a three-track playlist and explain to a friend what you love about each performance.","label":"See the community observance","url":"https://www.legionmemoriallibrary.org/event/hug-a-musician-day/"},"sources":[{"label":"Legion Memorial Library: 13 November 2026","url":"https://www.legionmemoriallibrary.org/event/hug-a-musician-day/","dateEvidence":true},{"label":"National Today: Hug a Musician Day","url":"https://nationaltoday.com/national-hug-musician-day/","dateEvidence":true}]},"2026-11-14:national-family-pj-day":{"id":"2026-11-14:national-family-pj-day","date":"2026-11-14","verification":"organiser","summary":"Permission for a very informal dress code. 💤 National Family PJ Day is a US promotional observance on 14 November, encouraging time together in whatever pyjamas are already in the drawer.","sections":[{"heading":"A recent, branded beginning","body":"Sleepwear brand Soma created National Family PJ Day in 2019, and National Day Calendar registered 14 November as its annual date. That makes this a commercial-origin celebration rather than a traditional holiday or an official day off. Matching outfits are optional, and buying a new set is not required."},{"heading":"Make it a low-effort occasion","body":"A board game, favourite film, shared breakfast or simply a quiet morning can give the day its shape. Family can include the people you live with or choose to spend time with; there is no requirement for a particular household. A deliberately mismatched pyjama photograph may be more memorable than a polished one, especially if somebody insists their oldest T-shirt is formal sleepwear."}],"activity":{"text":"Arrange a pyjama breakfast or a short game with someone you like. Let everyone nominate the least glamorous outfit for an imaginary award.","label":"See the day’s background","url":"https://nationaldaycalendar.com/celebrations/national-family-pj-day-november-14"},"sources":[{"label":"National Day Calendar: registered Family PJ Day","url":"https://nationaldaycalendar.com/celebrations/national-family-pj-day-november-14","dateEvidence":true}]},"2026-11-16:international-day-for-tolerance":{"id":"2026-11-16:international-day-for-tolerance","date":"2026-11-16","verification":"organiser","summary":"Observed on 16 November, this United Nations day is about respect for human diversity and fundamental rights. It asks people and institutions to work against prejudice, exclusion and the conditions that allow intolerance to grow.","sections":[{"heading":"A declaration and an annual day","body":"UNESCO’s member states adopted the Declaration of Principles on Tolerance on 16 November 1995. The UN General Assembly proclaimed the annual day in 1996. Its meaning goes beyond simply putting up with difference: it concerns equal rights, dignity and appreciation of the many cultures and ways of being human."},{"heading":"A practical kind of respect","body":"Education, open dialogue and fair treatment are central to UNESCO’s approach. Listening carefully does not require abandoning critical thinking or accepting harmful behaviour. A useful starting point is to notice whose perspective is missing from a conversation, book collection or local activity, then seek out work produced by that community rather than relying only on accounts about it."}],"activity":{"text":"Read the declaration’s background and choose an article or conversation led by a community whose experience you know little about.","label":"Explore UNESCO’s resources","url":"https://www.unesco.org/en/days/tolerance"},"sources":[{"label":"UNESCO: International Day for Tolerance","url":"https://www.unesco.org/en/days/tolerance","dateEvidence":true}]},"2026-11-17:national-take-a-hike-day":{"id":"2026-11-17:national-take-a-hike-day","date":"2026-11-17","verification":"organiser","summary":"A trail does not need a mountain at the end. 🥾 The American Hiking Society marks 17 November as National Take a Hike Day, encouraging people to enjoy a manageable stretch of time outdoors.","sections":[{"heading":"Keep the scale human","body":"The organiser explicitly points out that hiking can be simple, including a short outing near home. The US date falls in a season with shorter days and changeable weather, so a route that fits your time, mobility and local conditions makes more sense than an ambitious distance chosen just for the occasion."},{"heading":"Notice the journey","body":"Pick one thing to pay attention to: leaf shapes, birds, the sound of a stream or an unfamiliar turn in a familiar park. Going with a friend can make the walk a small social occasion, while a solo outing can offer a quieter change of scenery. The society’s planning and essentials guides are useful if you are moving from a casual stroll to a less familiar trail."}],"activity":{"text":"Choose a short local route and use the society’s planning resources to check what you need before heading out.","label":"Plan a manageable hike","url":"https://americanhiking.org/national-take-hike-day/"},"sources":[{"label":"American Hiking Society: National Take a Hike Day","url":"https://americanhiking.org/national-take-hike-day/","dateEvidence":true}]},"2026-11-18:national-princess-day":{"id":"2026-11-18:national-princess-day","date":"2026-11-18","verification":"organiser","summary":"A little theatrical royalty for an ordinary Wednesday. 👑 National Princess Day on 18 November began as a celebration linked to The Swan Princess film, with kindness and confidence among its suggested ways to join in.","sections":[{"heading":"Why this particular date?","body":"The Swan Princess first reached US cinemas on 18 November 1994. The brand created National Princess Day, and National Day Calendar registered the annual observance beginning in 2017. Its origins are therefore a film anniversary and promotional celebration, rather than a historic royal occasion or a public holiday."},{"heading":"Your version of a royal day","body":"The creators suggest dressing up, making someone feel appreciated and showing kindness. You can borrow the spirit without buying anything: wear the impractical favourite item in your wardrobe, give a friend the best seat, or make an elaborate handwritten invitation for tea. Fairy-tale fun is available to anyone who enjoys it, regardless of age or who usually gets assigned the crown."}],"activity":{"text":"Declare a low-budget royal afternoon: dress up with things you own and give somebody else a small kindness worthy of a title.","label":"Explore the original celebration","url":"https://www.swanprincessseries.com/en-gb/blogs/news/national-princess-day-on-november-18th-1"},"sources":[{"label":"The Swan Princess: origin and annual date","url":"https://www.swanprincessseries.com/en-gb/blogs/news/national-princess-day-on-november-18th-1","dateEvidence":true}]},"2026-11-19:national-play-monopoly-day":{"id":"2026-11-19:national-play-monopoly-day","date":"2026-11-19","verification":"independent-calendar","summary":"Tiny properties, large opinions about the rules. 🎲 The informal 19 November observance is an excuse to bring Monopoly to the table, negotiate over pretend money and find out who has been inventing house rules.","sections":[{"heading":"The game behind the day","body":"Monopoly is a property-trading game in which players buy, sell and trade spaces, collect rent and build houses and hotels. The November date appears in independent calendars; it should not be confused with other Monopoly promotions or tournaments held at different times of the year."},{"heading":"Agree the rules before the rent","body":"Choose a version, check its instructions and settle any house rules before the first roll. Hasbro publishes instruction sheets for its editions, including the classic game. That gives you a neutral reference when somebody remembers a completely different rule from childhood. If a full game does not fit your evening, agree a shorter session and an end point together before starting."}],"activity":{"text":"Get the instructions for your edition, pick a token and hold a quick vote on any house rules before anyone receives a banknote.","label":"Check Hasbro’s rules","url":"https://instructions.hasbro.com/en-gb/instruction/monopoly-game"},"sources":[{"label":"National Day Calendar: Play Monopoly Day","url":"https://nationaldaycalendar.com/celebrations/national-play-monopoly-day-november-19/","dateEvidence":true},{"label":"Hasbro: Monopoly game instructions","url":"https://instructions.hasbro.com/en-gb/instruction/monopoly-game","dateEvidence":false}]},"2026-11-21:world-television-day":{"id":"2026-11-21:world-television-day","date":"2026-11-21","verification":"organiser","summary":"World Television Day on 21 November recognises television’s role in informing, educating and connecting audiences. It is a United Nations observance about communication and public understanding, rather than simply a celebration of the screen itself.","sections":[{"heading":"Where the date came from","body":"The UN held its first World Television Forum on 21 and 22 November 1996. The General Assembly then proclaimed 21 November as the annual day. The decision recognised how televised coverage could bring conflicts, threats to peace and wider social and economic questions to public attention."},{"heading":"Watch with a question in mind","body":"Television now shares its audience with many other screens, but questions of trust, representation and access remain. Choose a programme from somewhere unfamiliar and notice whose voices are heard, which questions are asked and what evidence is shown. Broadcasters including the European Broadcasting Union continue to use the date to discuss the medium’s place in people’s lives."}],"activity":{"text":"Choose a documentary or news programme from another country and compare one story with how it is covered where you live.","label":"Explore World TV Day","url":"https://www.ebu.ch/events/world-tv-day"},"sources":[{"label":"United Nations: World Television Day","url":"https://www.un.org/en/observances/world-television-day","dateEvidence":true},{"label":"European Broadcasting Union: World TV Day","url":"https://www.ebu.ch/events/world-tv-day","dateEvidence":true}]},"2026-11-22:go-for-a-ride-day":{"id":"2026-11-22:go-for-a-ride-day","date":"2026-11-22","verification":"independent-calendar","summary":"Today the journey gets to be the plan. 🚲 Go For a Ride Day is an informal 22 November invitation to enjoy a ride, whether that means a bicycle, a train window or a scenic bus route.","sections":[{"heading":"No single vehicle required","body":"Independent calendars describe the day broadly rather than tying it to one form of transport. A short cycle, a gentle outing on public transport or a ride as somebody else’s passenger can all fit. The date’s creator is not clearly established, so this is best understood as a playful prompt rather than a formal transport campaign."},{"heading":"Make an ordinary route different","body":"Choose a journey you normally rush and give yourself time to look around, or travel one stop further than usual and explore the area before returning. A route with a view can turn a small trip into an occasion. Plan a way back, check local conditions and choose a form of travel that suits your comfort and access needs."}],"activity":{"text":"Pick a scenic local route, bring a drink and make a three-photo travel diary without leaving your own area.","label":"Get ride-day inspiration","url":"https://www.timeanddate.com/holidays/fun/go-for-a-ride-day"},"sources":[{"label":"Time and Date: Go For a Ride Day","url":"https://www.timeanddate.com/holidays/fun/go-for-a-ride-day","dateEvidence":true}]},"2026-11-23:fibonacci-day":{"id":"2026-11-23:fibonacci-day","date":"2026-11-23","verification":"independent-calendar","summary":"The date is the joke: 11/23 becomes 1, 1, 2, 3. 🌀 Fibonacci Day is an informal mathematics celebration on 23 November, inspired by the opening numbers of the familiar sequence.","sections":[{"heading":"The rule is surprisingly simple","body":"After the starting pair, each number is the sum of the two before it: 1, 1, 2, 3, 5, 8, 13 and onward. The sequence is associated with Leonardo of Pisa, known as Fibonacci, and offers a friendly route into patterns, ratios and mathematical puzzles."},{"heading":"A pattern hunt with a little care","body":"Fibonacci-inspired spirals are popular in art and design, and number patterns can appear in natural arrangements such as seed heads. It is worth checking a pattern rather than assuming every spiral follows this sequence. For a hands-on experiment, draw adjoining squares whose sides follow the numbers, then sketch an arc across each one and see how the picture develops."}],"activity":{"text":"Write the sequence as far as you can, then draw a spiral made from squares of sizes 1, 1, 2, 3, 5 and 8.","label":"Explore Fibonacci Day","url":"https://www.timeanddate.com/holidays/fun/fibonacci-day"},"sources":[{"label":"Time and Date: Fibonacci Day","url":"https://www.timeanddate.com/holidays/fun/fibonacci-day","dateEvidence":true},{"label":"University of Pisa: Fibonacci Days 2026","url":"https://www.msc.sma.unipi.it/2026/11/giornate-di-fibonacci-2026/","dateEvidence":true}]},"2026-11-24:national-sardines-day":{"id":"2026-11-24:national-sardines-day","date":"2026-11-24","verification":"independent-calendar","summary":"An entire food day in a very small tin. 🐟 This informal US observance on 24 November celebrates sardines, enjoyed fresh or preserved and at home in many different food traditions.","sections":[{"heading":"A store-cupboard star","body":"Sardines can be eaten on their own, served on crackers or worked into a more substantial meal. Tinned versions make it easy to experiment without preparing a whole fresh fish. National Day Calendar lists the November date but says the origin of the observance itself is still uncertain."},{"heading":"Keep the first attempt simple","body":"If sardines are new to you, try them with a familiar base rather than disguising them completely. Toast, tomato, a squeeze of lemon or fresh herbs can make a useful starting point. You might compare sardines packed in oil with a different style another time, noticing texture and flavour rather than deciding from one mouthful that every tin must taste the same."}],"activity":{"text":"Make the sardines-on-toast recipe and give your humble lunch a café-style name. Bonus points for eating it while it is still crisp.","label":"Make sardines on toast","url":"https://www.bbcgoodfood.com/recipes/sardines-on-toast"},"sources":[{"label":"National Day Calendar: Sardines Day","url":"https://nationaldaycalendar.com/celebrations/national-sardines-day-november-24/","dateEvidence":true},{"label":"Good Food: sardines on toast","url":"https://www.bbcgoodfood.com/recipes/sardines-on-toast","dateEvidence":false}]},"2026-11-26:thanksgiving":{"id":"2026-11-26:thanksgiving","date":"2026-11-26","verification":"organiser","summary":"US Thanksgiving falls on Thursday 26 November in 2026. It is a federal holiday often spent sharing food and time with others, and also a moment to recognise the different histories and perspectives attached to it.","sections":[{"heading":"A date with a specific rule","body":"The US holiday is observed on the fourth Thursday of November; Canada’s Thanksgiving has a different date. Family meals, travel, community gatherings and expressions of gratitude are familiar parts of the American holiday, though people’s traditions and experiences vary widely."},{"heading":"There is more than one story","body":"Popular accounts of a single friendly “first Thanksgiving” can leave out Wampanoag perspectives and the consequences of colonisation. The Smithsonian’s National Museum of the American Indian offers resources that examine those national stories using evidence and Native voices. A thoughtful celebration can make room for that history while also valuing the people at your table or the community around you."}],"activity":{"text":"Learn one Wampanoag perspective from the Smithsonian resource, then tell someone one specific thing you appreciate about them.","label":"Explore Native perspectives","url":"https://americanindian.si.edu/nk360/thanksgiving/index.html"},"sources":[{"label":"Federal Reserve: 2026 holiday schedule","url":"https://www.stlouisfed.org/about-us/resources/legal-holiday-schedule","dateEvidence":true},{"label":"Smithsonian National Museum of the American Indian","url":"https://americanindian.si.edu/nk360/thanksgiving/index.html","dateEvidence":false}]},"2026-11-27:buy-nothing-day":{"id":"2026-11-27:buy-nothing-day","date":"2026-11-27","verification":"organiser","summary":"A day when leaving the basket empty is the whole idea. ♻️ Buy Nothing Day on 27 November 2026 invites a pause from shopping and a look at the habits behind what we buy.","sections":[{"heading":"The other side of Black Friday","body":"The UK campaign places the observance on the Friday after US Thanksgiving, alongside Black Friday. It encourages a 24-hour break from consumption as a personal experiment or public statement. The point is not to win a contest for spending the least, but to notice how advertising and convenience shape everyday decisions."},{"heading":"Try an alternative, not a punishment","body":"Borrowing, repairing, swapping and using what you already own can all give the day a practical shape. Choose one thing you were about to buy and ask what job you need it to do. You might still decide you need it later; creating a pause makes that decision more deliberate. Essentials and individual circumstances matter, so keep the experiment realistic."}],"activity":{"text":"Pick one non-essential purchase to postpone and try repairing, borrowing or repurposing something you already have instead.","label":"Explore the UK campaign","url":"https://www.buynothingday.co.uk/?page_id=7"},"sources":[{"label":"Buy Nothing Day UK: 27 November 2026","url":"https://www.buynothingday.co.uk/?page_id=7","dateEvidence":true}]},"2026-11-28:red-planet-day":{"id":"2026-11-28:red-planet-day","date":"2026-11-28","verification":"independent-calendar","summary":"Mars gets a day in the calendar. 🚀 The informal 28 November observance marks the launch of Mariner 4 in 1964, a mission that helped replace speculation about our planetary neighbour with close-up evidence.","sections":[{"heading":"A long journey for a few pictures","body":"NASA’s Mariner 4 launched on 28 November 1964 and flew past Mars in July 1965. It returned the first close-range images of the planet, showing a heavily cratered landscape. Those early pictures were modest compared with modern mission imagery, but represented an enormous change in what people could actually observe."},{"heading":"Look at how knowledge changes","body":"The mission opened a path for later orbiters, landers and rovers, each asking more detailed questions. For a small armchair expedition, compare one Mariner image with a modern view of Mars. Notice what improved resolution reveals, but also what an image alone cannot tell you. Red Planet Day is a themed learning opportunity, not an official NASA public holiday."}],"activity":{"text":"Explore Mariner 4’s mission story and compare an early image with a modern Mars photograph. What new questions does the detail create?","label":"Explore Mariner 4","url":"https://www.nasa.gov/history/55-years-ago-mariner-4-first-to-mars/"},"sources":[{"label":"Time and Date: Red Planet Day","url":"https://www.timeanddate.com/holidays/fun/red-planet-day","dateEvidence":true},{"label":"NASA: Mariner 4 mission history","url":"https://www.nasa.gov/history/55-years-ago-mariner-4-first-to-mars/","dateEvidence":false}]},"2026-11-29:secondhand-sunday":{"id":"2026-11-29:secondhand-sunday","date":"2026-11-29","verification":"organiser","summary":"Something with a past can still have a future. 👗 Secondhand Sunday falls on 29 November 2026, the Sunday after US Thanksgiving, and highlights secondhand sellers and keeping useful things in circulation.","sections":[{"heading":"A recent shopping-season idea","body":"Poshmark introduced Secondhand Sunday in 2022. Its own sustainability information describes an annual event on the Sunday after Thanksgiving, which places the 2026 observance on 29 November. This is a commercial-origin reuse campaign, not a public holiday or a promise that a particular sale will be running."},{"heading":"Look beyond a new purchase","body":"A charity-shop visit is one option, but taking part can also mean passing on a coat, repairing a favourite item or helping a friend find something they need. Check condition, usefulness and fit just as carefully as you would with a new object. The most satisfying find is often something that becomes part of everyday life, rather than a bargain that stays in a bag."}],"activity":{"text":"Choose one good-quality item you no longer use and offer it to someone who will, or browse a local charity shop with a specific need in mind.","label":"Explore the reuse campaign","url":"https://poshmark.com/sustainability"},"sources":[{"label":"Poshmark: Secondhand Sunday origin and rule","url":"https://poshmark.com/sustainability","dateEvidence":true},{"label":"Checkiday: Secondhand Sunday 2026","url":"https://www.checkiday.com/adc804814e5768691e2743612d8421fb/secondhand-sunday","dateEvidence":true}],"researchNote":"The annual date is confirmed by Poshmark’s Sunday-after-Thanksgiving rule and Checkiday. This does not confirm a specific 2026 Poshmark sale or event programme."},"2026-12-01":{"id":"2026-12-01","date":"2026-12-01","verification":"independent-calendar","summary":"A little sparkle for the start of December. ✨ Christmas Lights Day is an informal observance on 1 December, celebrating the decorations that turn familiar windows, streets and gardens into something worth a second look.","sections":[{"heading":"An unofficial seasonal marker","body":"Independent calendars list the day on 1 December. The exact origin of the named observance is not well documented, and it is not a public holiday. Its appeal is the shared experience of noticing festive light displays, whether your own celebration is religious, secular or simply an appreciation of a bright winter evening."},{"heading":"Make a tiny lights expedition","body":"Choose a nearby display or a familiar street and take a slow walk with someone. You could make up categories such as most ambitious roof, best tiny window or most enthusiastic reindeer. If putting up lights yourself, follow the product’s instructions and use decorations intended for the location. The day works just as well as an excuse to admire other people’s efforts."}],"activity":{"text":"Plan a short neighbourhood lights walk and photograph three displays you love. Give each one a completely unofficial award.","label":"See the December observance","url":"https://eventguide.com/today/days/2026/12/01.htm"},"sources":[{"label":"EventGuide: Christmas Lights Day, 1 December 2026","url":"https://eventguide.com/today/days/2026/12/01.htm","dateEvidence":true},{"label":"Holiday List: National Christmas Lights Day","url":"https://holidaydaylist.com/holidays/national-christmas-lights-day/","dateEvidence":true}]},"2026-12-02:world-computer-literacy-day":{"id":"2026-12-02:world-computer-literacy-day","date":"2026-12-02","verification":"organiser","summary":"Digital confidence can start with one useful task. 💻 World Computer Literacy Day on 2 December highlights access to computers and the skills that help people take part in work, learning and everyday life.","sections":[{"heading":"An initiative from NIIT","body":"The first World Computer Literacy Day took place on 2 December 2001, marking the twentieth anniversary of the Indian technology-training company NIIT. Contemporary reporting described first-time computer experiences and training as part of the initiative. The annual date continues to draw attention to gaps in digital opportunity."},{"heading":"Literacy is more than owning a device","body":"Access to equipment, an internet connection and a patient person to learn with can all matter. A helpful session starts with what the learner wants to do: attach a photograph, find a document, organise files or recognise a suspicious message. Let them control the keyboard and repeat the task themselves. Solving the problem for them is quicker once; building confidence can be more useful afterwards."}],"activity":{"text":"Ask someone which computer task frustrates them, then spend fifteen patient minutes helping them practise it themselves.","label":"Explore the day’s beginnings","url":"https://www.scidev.net/global/news/indian-firm-launches-world-computer-literacy-day/"},"sources":[{"label":"SciDev.Net: original 2001 launch report","url":"https://www.scidev.net/global/news/indian-firm-launches-world-computer-literacy-day/","dateEvidence":true},{"label":"NIIT: collected Computer Literacy Day reporting","url":"https://www.niit.com/authoring/NewsRoom/MediaKit/NIIT%20in%20the%20News/FINAL%20NIIT%20News%20%28Oct-Dec%202022%29%20Booklet_39%20pages%20%28enabled%20URL%20version%29.pdf","dateEvidence":true}]},"2026-12-04:hanukkah-begins-at-sundown":{"id":"2026-12-04:hanukkah-begins-at-sundown","date":"2026-12-04","verification":"organiser","summary":"Hanukkah begins at sundown on Friday 4 December in 2026 and continues until nightfall on 12 December. 🕎 The eight-night Jewish festival remembers the rededication of the Second Temple in Jerusalem.","sections":[{"heading":"Why the date moves","body":"Hanukkah begins on 25 Kislev in the Hebrew calendar, so its Gregorian dates change from year to year. This entry marks only the beginning; the festival continues for eight nights and days. In 2026, the first evening is also the start of Shabbat, which affects the timing of candle lighting."},{"heading":"Light, food and shared traditions","body":"An additional Hanukkah light is lit on each night, using a nine-branched hanukkiah with a separate helper light. Foods cooked in oil, dreidel games and time with family or community are among familiar traditions, with customs differing between households. Learning what the lights represent is a respectful way to understand the occasion even if it is not part of your own religious practice."}],"activity":{"text":"Explore Hebcal’s festival overview and candle calendar, then learn the difference between a hanukkiah’s eight festival lights and its helper light.","label":"Explore Hanukkah traditions","url":"https://www.hebcal.com/holidays/chanukah-2026?i=on"},"sources":[{"label":"Hebcal: Hanukkah 2026 dates and overview","url":"https://www.hebcal.com/holidays/chanukah-2026?i=on","dateEvidence":true}],"researchNote":"Festival begins at sundown 4 December and ends at nightfall 12 December 2026. Only its start is listed; Friday candle lighting is before sundown, as shown in Hebcal’s calendar."},"2026-12-05:krampusnacht":{"id":"2026-12-05:krampusnacht","date":"2026-12-05","verification":"organiser","summary":"Christmas folklore has a less cuddly side. 👹 Krampusnacht is associated with the evening of 5 December in Alpine traditions, when horned, masked figures appear alongside the season’s celebrations of Saint Nicholas.","sections":[{"heading":"The companion in the shadows","body":"In Austrian traditions, Krampus is the frightening companion of Saint Nicholas, whose feast follows on 6 December. Costumes can involve carved masks, horns, fur and loud bells. Austrian tourism sources note that the origins of the custom remain uncertain; confident claims that every detail is an unchanged ancient ritual should be treated cautiously."},{"heading":"A living, local tradition","body":"Krampus runs and related masked processions vary between towns, and organised events do not all take place on the same evening. Some are designed for families while others are noisy or deliberately intimidating. Learning about the costume-making and local groups can be as interesting as the spectacle itself. This calendar date is the traditional occasion, not a guarantee of a particular parade timetable."}],"activity":{"text":"Explore Austria’s account of the tradition and look closely at the craft involved in carved masks and handmade costumes.","label":"Meet Krampus and the customs","url":"https://www.austria.info/en-us/inspiration/raucous-traditions/"},"sources":[{"label":"Austrian National Tourist Office: winter traditions","url":"https://www.austria.info/en-us/inspiration/raucous-traditions/","dateEvidence":true}]},"2026-12-07:national-letter-writing-day":{"id":"2026-12-07:national-letter-writing-day","date":"2026-12-07","verification":"independent-calendar","summary":"Give somebody post that is not a bill. ✉️ The informal 7 December observance encourages a handwritten letter, a small piece of stationery and a message that takes a little longer to arrive.","sections":[{"heading":"A date for a slower message","body":"Independent calendars place Letter Writing Day on 7 December, while its creator is not clearly documented. Letters have long carried personal news, records and ideas across distances. The handwriting, paper and small details can make an ordinary account of your week feel different from a stream of messages on a screen."},{"heading":"You do not need a grand opening","body":"Start with one concrete memory, a thank-you or something that made you think of the recipient. A single page or a postcard is enough. If you are posting it, check the address and the current postage for its size and destination; a carefully written letter deserves to reach the right door. You can also hand-deliver a note to somebody nearby."}],"activity":{"text":"Write a short letter beginning “I remembered this today…” and use the Post Office guide if you need help addressing or posting it.","label":"Get your letter ready to post","url":"https://www.postoffice.co.uk/mail/how-to-send-letter"},"sources":[{"label":"Time and Date: Letter Writing Day","url":"https://www.timeanddate.com/holidays/fun/letter-writing-day","dateEvidence":true},{"label":"Post Office: how to send a letter","url":"https://www.postoffice.co.uk/mail/how-to-send-letter","dateEvidence":false}]},"2026-12-09":{"id":"2026-12-09","date":"2026-12-09","verification":"organiser","summary":"International Anti-Corruption Day on 9 December focuses on honesty, accountability and institutions people can trust. It recognises that corruption affects everyday services and opportunities, not only dramatic scandals involving powerful people.","sections":[{"heading":"The United Nations connection","body":"The UN General Assembly adopted the United Nations Convention against Corruption in 2003 and designated 9 December as the annual awareness day. UNODC serves as the convention’s secretariat. The observance highlights both the damage caused by corruption and the importance of prevention, cooperation and stronger public institutions."},{"heading":"Look for the practical systems","body":"Transparent decisions, independent reporting and clear routes for raising concerns can make public life more accountable. Learning how an organisation explains its spending or handles conflicts of interest can make the topic feel less abstract. The UN describes a role for governments, public bodies, businesses, researchers, media and communities, rather than leaving the whole issue to individual whistleblowers."}],"activity":{"text":"Choose a public organisation you use and look for its published accounts, complaints process or explanation of how decisions are made.","label":"Explore the UN background","url":"https://indonesia.un.org/en/254678-international-anti-corruption-day-9-december"},"sources":[{"label":"United Nations: Anti-Corruption Day background","url":"https://www.un.org/en/observances/anti-corruption-day/background","dateEvidence":true},{"label":"UN Indonesia: International Anti-Corruption Day","url":"https://indonesia.un.org/en/254678-international-anti-corruption-day-9-december","dateEvidence":true}]},"2026-12-10:international-animal-rights-day":{"id":"2026-12-10:international-animal-rights-day","date":"2026-12-10","verification":"organiser","summary":"Observed on 10 December, International Animal Rights Day asks how animals should be treated and protected. It draws attention to their experiences and to the ethical choices people make about animals in everyday life.","sections":[{"heading":"A deliberately chosen date","body":"Animal-rights organisation Uncaged began the event in 1998. It selected the same date as Human Rights Day to draw a connection between concern for human dignity and the treatment of other animals. The observance is an advocacy initiative; it is distinct from a United Nations-designated animal-rights day."},{"heading":"Understand the ideas before the slogan","body":"Animal welfare and animal rights overlap in concern for animals, but can ask different questions about human use of them. Sentience—the capacity for experiences and feelings—is central to many discussions. A useful way to join in is to examine one specific practice, listen to a credible animal-protection organisation and consider an action that addresses that issue rather than sharing a dramatic image without context."}],"activity":{"text":"Read the campaign overview and choose one animal-welfare issue to learn about in more detail before deciding how to help.","label":"Explore animal-rights questions","url":"https://www.worldanimalprotection.org/our-campaigns/sentience/animal-awareness-days/international-animal-rights-day/"},"sources":[{"label":"World Animal Protection: date, origin and context","url":"https://www.worldanimalprotection.org/our-campaigns/sentience/animal-awareness-days/international-animal-rights-day/","dateEvidence":true}]},"2026-12-12:gingerbread-house-day":{"id":"2026-12-12:gingerbread-house-day","date":"2026-12-12","verification":"independent-calendar","summary":"Architecture, but you can eat the building materials. 🏠 The informal 12 December celebration is an excuse to construct a gingerbread house, from a careful miniature cottage to a gloriously wonky biscuit shed.","sections":[{"heading":"A festive craft project","body":"Gingerbread houses combine baking, construction and decoration, and have become a familiar seasonal activity in many households. Independent calendars list the December date, though the creator of the named observance is not established. Ready-made kits simplify the construction, while a recipe and template let you build a house entirely from scratch."},{"heading":"Let the house have character","body":"Think about the design before assembling: roof panels, door position and a place to stand the finished model all help. The decoration does not need to be expensive or elaborate. A few sweets, a little icing and a strong opinion about window placement can be enough. If a wall collapses, it can become an imaginative ruin rather than a failed house."}],"activity":{"text":"Use the recipe and template to make a cottage, then give it a tiny estate-agent description when you show it off.","label":"Build a gingerbread house","url":"https://www.bbcgoodfood.com/recipes/simple-gingerbread-house"},"sources":[{"label":"National Day Calendar: Gingerbread House Day","url":"https://nationaldaycalendar.com/celebrations/gingerbread-house-day-december-12","dateEvidence":true},{"label":"Good Food: gingerbread house recipe and template","url":"https://www.bbcgoodfood.com/recipes/simple-gingerbread-house","dateEvidence":false}]},"2026-12-14":{"id":"2026-12-14","date":"2026-12-14","verification":"organiser","summary":"A day to appreciate primates without turning them into props. 🐒 Monkey Day on 14 December combines curiosity about these animals with attention to conservation and the ways they are treated.","sections":[{"heading":"From a joke to a wider observance","body":"World Animal Protection describes Monkey Day as an unofficial international celebration that began in 2000 with student Casey Sorrow and friends. It subsequently spread beyond that original group. The date is now used by wildlife organisations and others to talk about monkeys and the pressures they face."},{"heading":"Look beyond the cute clip","body":"A primate’s expression or movement can invite a very human interpretation, but a short video rarely explains an animal’s situation. Keeping wild primates as pets or using them for performances raises welfare concerns. Learning about the species, its social life and its natural environment is a richer way to appreciate it. Choose educational material that gives animals context rather than demanding a trick or a reaction."}],"activity":{"text":"Explore the animal-protection guide and learn one difference between the lives of wild monkeys and the situations shown in viral pet videos.","label":"Meet the animals behind the day","url":"https://www.worldanimalprotection.org/our-campaigns/sentience/animal-awareness-days/world-monkey-day/"},"sources":[{"label":"World Animal Protection: Monkey Day","url":"https://www.worldanimalprotection.org/our-campaigns/sentience/animal-awareness-days/world-monkey-day/","dateEvidence":true}]},"2026-12-15:national-cat-herders-day":{"id":"2026-12-15:national-cat-herders-day","date":"2026-12-15","verification":"independent-calendar","summary":"For everyone whose plans keep wandering off in different directions. 🐈 Cat Herders Day on 15 December celebrates the people trying to coordinate complicated jobs, competing priorities and wonderfully uncooperative circumstances.","sections":[{"heading":"It is mostly a metaphor","body":"Herding cats describes the difficulty of organising people or tasks that resist being neatly directed. National Day Calendar credits Thomas and Ruth Roy of Wellcat with creating the observance. The annual date is an informal appreciation day, rather than an instruction to round up actual cats."},{"heading":"Recognise the invisible organiser","body":"Think of the person who keeps a group trip, family appointment or work handover moving. Much of that coordination happens before anyone notices it, and a specific thank-you can be more meaningful than a general compliment. If you are that person today, choose one small part of the chaos to simplify instead of expecting the entire herd to line up perfectly at once."}],"activity":{"text":"Thank someone for one organising task they do that usually goes unnoticed, or offer to take a specific task off their list.","label":"Explore Cat Herders Day","url":"https://nationaldaycalendar.com/celebrations/cat-herders-day-december-15"},"sources":[{"label":"National Day Calendar: date and Wellcat origin","url":"https://nationaldaycalendar.com/celebrations/cat-herders-day-december-15","dateEvidence":true}]},"2026-12-17:wright-brothers-day":{"id":"2026-12-17:wright-brothers-day","date":"2026-12-17","verification":"organiser","summary":"On 17 December 1903, a short flight opened a very large chapter. ✈️ Wright Brothers Day is a US national observance remembering Orville and Wilbur Wright’s achievement and the experiments that made it possible.","sections":[{"heading":"The flight behind the anniversary","body":"The brothers made successful powered flights near Kitty Hawk, North Carolina, on 17 December 1903. The date is designated in US law and is marked by organisations including the First Flight Society. In 2026, it is the 123rd anniversary of that landmark in aviation history."},{"heading":"An achievement built from tests","body":"It is easy to turn an invention story into a single flash of inspiration. The Wrights’ work is also a reminder of repeated experiments, careful observation and changes made after things did not behave as expected. Looking at photographs of the early aircraft can raise good questions about control, balance and the practical problems the builders had to solve before a flight became possible."}],"activity":{"text":"Explore the First Flight Society’s history, then sketch an early aircraft and label the parts whose purpose you would like to understand.","label":"Explore the first flight","url":"https://firstflight.org/wright-brothersday/"},"sources":[{"label":"First Flight Society: Wright Brothers Day 2026","url":"https://firstflight.org/wright-brothersday/","dateEvidence":true},{"label":"US Code: 36 USC 143","url":"https://www.govinfo.gov/content/pkg/USCODE-2024-title36/html/USCODE-2024-title36-subtitleI-partA-chap1-sec143.htm","dateEvidence":true}]},"2026-12-19":{"id":"2026-12-19","date":"2026-12-19","verification":"independent-calendar","summary":"Tiny sweets, surprisingly interesting science. 🍬 The informal US food day on 19 December celebrates hard candy, from fruit drops and peppermints to bright lollipops that look almost too neat to eat.","sections":[{"heading":"How liquid becomes a sweet","body":"Candy-making changes sugar syrup into different textures by controlling water content, temperature and crystallisation. Hard candy is one result, while fudge, caramel and other sweets have different structures. The Exploratorium’s food-science resources explain how those changes produce the textures you can recognise in a sweet shop."},{"heading":"A pocket-sized taste test","body":"National Day Calendar lists 19 December but does not identify a confirmed founder for the observance. A small comparison can be enough to join in: notice flavour, shape and how the surface changes as the sweet dissolves. You could also ask somebody which sweet they remember from childhood and why. Familiar packaging can bring back a surprisingly precise memory."}],"activity":{"text":"Compare two familiar sweets or explore the museum’s candy-science resources to find out why their textures are different.","label":"Explore the science of sweets","url":"https://annex.exploratorium.edu/cooking/candy/index.html"},"sources":[{"label":"National Day Calendar: Hard Candy Day","url":"https://nationaldaycalendar.com/celebrations/national-hard-candy-day-december-19","dateEvidence":true},{"label":"Exploratorium: Science of Candy","url":"https://annex.exploratorium.edu/cooking/candy/index.html","dateEvidence":false}]},"2026-12-20:games-day":{"id":"2026-12-20:games-day","date":"2026-12-20","verification":"independent-calendar","summary":"A good excuse to gather around a table. 🎲 The informal 20 December calendar date recalls an early Games Workshop convention, but you can mark it at home with any game your group enjoys.","sections":[{"heading":"An anniversary, not a booking","body":"The first Games Workshop Games Day took place at Seymour Hall in London on 20 December 1975. Later conventions were held on different dates. Independent observance calendars use the original December anniversary as Games Day; that does not establish a scheduled Games Workshop convention on 20 December 2026."},{"heading":"Make a game session work for everyone","body":"Pick a game to suit the time available and the people taking part, then make space to explain it before starting. A quick card game, a cooperative puzzle or a familiar board game can all fit. Agreeing the stopping point is useful when someone has an early start. Teaching a favourite game patiently can be as satisfying as winning it."}],"activity":{"text":"Ask everyone for one game suggestion, pick a short session and agree the rules and finish time before the first turn.","label":"Explore the anniversary background","url":"https://www.checkiday.com/8e100dfa0c00a6b84cb7efc6e0770363/games-day"},"sources":[{"label":"Checkiday: December anniversary and convention history","url":"https://www.checkiday.com/8e100dfa0c00a6b84cb7efc6e0770363/games-day","dateEvidence":true}],"researchNote":"December 20 is an independently listed informal anniversary of the first 1975 convention. It is not confirmation of a Games Workshop convention in 2026; later conventions used different dates."},"2026-12-22":{"id":"2026-12-22","date":"2026-12-22","verification":"independent-calendar","summary":"A loaf that makes a cup of tea feel planned. 🍞 The informal 22 December observance celebrates date nut bread, a fruit-and-nut bake with a soft crumb and plenty of possibilities for sharing.","sections":[{"heading":"What goes into the loaf?","body":"Chopped dates bring sweetness and a distinctive texture, while nuts add crunch. Many versions are quick breads, using raising agents rather than a long yeasted rise. Recipes differ in flour, spices and the nuts used, so there is no need to treat one household’s version as the only correct one."},{"heading":"A useful winter bake","body":"National Day Calendar lists 22 December, while acknowledging that some sources also use a September date. That makes the observance informal rather than a uniquely regulated date. A loaf is easy to slice for a shared tea break, toast the next day or divide into portions for later. A handwritten note about the recipe can make a simple food gift feel more personal."}],"activity":{"text":"Try the Heart Foundation’s one-bowl date-and-walnut loaf and share a slice with someone who will give an honest review.","label":"Bake a date-and-walnut loaf","url":"https://www.heartfoundation.org.au/recipes/one-bowl-date-and-walnut-loaf"},"sources":[{"label":"National Day Calendar: Date Nut Bread Day","url":"https://nationaldaycalendar.com/celebrations/national-date-nut-bread-day-december-22/","dateEvidence":true},{"label":"Heart Foundation: one-bowl date and walnut loaf","url":"https://www.heartfoundation.org.au/recipes/one-bowl-date-and-walnut-loaf","dateEvidence":false}],"researchNote":"Informal food observance. December 22 is independently confirmed; some calendars also list a September date."},"2026-12-23:night-of-the-radishes":{"id":"2026-12-23:night-of-the-radishes","date":"2026-12-23","verification":"organiser","summary":"In Oaxaca, a radish can become a whole scene. 🎨 Noche de Rábanos takes place on 23 December, when artisans transform oversized vegetables and other materials into intricate, short-lived works of art.","sections":[{"heading":"A very particular Oaxacan tradition","body":"Mexico’s tourism information describes the celebration as growing from a late-nineteenth-century market contest into a competition of ephemeral art. Displays can depict local folklore, architecture, nativity scenes and traditions. The 2026 listing places it in Oaxaca City’s Zócalo on 23 December."},{"heading":"More than a vegetable carving contest","body":"The wider celebration also includes work made with corn husks, known as totomoxtle, and dried flowers, or flor inmortal. The materials are part of the fascination: ordinary growing things become detailed figures for an occasion that will not last. Looking closely at the skill and the local stories makes it more rewarding than treating the event as simply an amusing food photograph."}],"activity":{"text":"Explore the festival pictures and choose one tiny scene you would invent from an ordinary vegetable—then sketch the ambitious version before attempting it.","label":"Explore Oaxaca’s radish art","url":"https://visitmexico.com/en/actividad/832"},"sources":[{"label":"Visit Mexico: Noche de Rábanos 2026","url":"https://visitmexico.com/en/actividad/832","dateEvidence":true}]},"2026-12-25:national-pumpkin-pie-day":{"id":"2026-12-25:national-pumpkin-pie-day","date":"2026-12-25","verification":"independent-calendar","summary":"Christmas has room for more than one dessert tradition. 🥧 National Pumpkin Pie Day is an informal US food observance on 25 December, celebrating a spiced pie closely associated with autumn and winter gatherings.","sections":[{"heading":"The flavour behind the name","body":"Pumpkin pie pairs a pastry base with a smooth, gently spiced filling. Cinnamon, ginger, cloves or nutmeg appear in different versions, with the blend varying between cooks. The pie is familiar at both Thanksgiving and Christmas tables in the United States, rather than belonging to only one holiday."},{"heading":"A celebration without a fixed origin story","body":"National Day Calendar records the December date but has not identified a confirmed founder of the named observance. You can appreciate a slice without turning an uncertain origin story into a grand historical claim. For a small festive activity, compare the smell of the individual spices before tasting the finished pie, or ask someone about the dessert their own family always expects to see."}],"activity":{"text":"Try the pumpkin-pie recipe when you have time to bake, or make a tiny tasting plate and compare it with your usual festive dessert.","label":"Bake a pumpkin pie","url":"https://www.bbcgoodfood.com/recipes/pumpkin-pie"},"sources":[{"label":"National Day Calendar: Pumpkin Pie Day","url":"https://nationaldaycalendar.com/celebrations/national-pumpkin-pie-day-december-25/","dateEvidence":true},{"label":"Good Food: pumpkin pie","url":"https://www.bbcgoodfood.com/recipes/pumpkin-pie","dateEvidence":false}]},"2026-12-26:saint-stephen-s-day":{"id":"2026-12-26:saint-stephen-s-day","date":"2026-12-26","verification":"organiser","summary":"Saint Stephen’s Day is observed on 26 December in many Western Christian traditions. It remembers Stephen, described in the Acts of the Apostles as an early Christian deacon and the first Christian martyr.","sections":[{"heading":"The person behind the feast","body":"Christian accounts connect Stephen with service to the early community and care for people in need. His story in Acts includes a speech before the council and his death by stoning. The feast immediately after Christmas places a sober story of witness and sacrifice beside the season’s celebration of Christ’s birth."},{"heading":"One date, different local meanings","body":"The same date has other names and customs in different places, including Boxing Day in the UK. A shared date does not make every custom identical, and church calendars are not uniform across all Christian traditions. Learning about the person being remembered is a useful starting point before exploring how a particular community observes the day."}],"activity":{"text":"Read the Vatican’s short account of Stephen, then look for one local tradition connected with 26 December and how it differs from your own.","label":"Explore Stephen’s story","url":"https://www.vaticannews.va/en/saints/12/26/st--stephen--first-martyr.html"},"sources":[{"label":"Vatican News: Saint Stephen, 26 December","url":"https://www.vaticannews.va/en/saints/12/26/st--stephen--first-martyr.html","dateEvidence":true},{"label":"Vatican News: liturgy on 26 December 2026","url":"https://www.vaticannews.va/en/word-of-the-day/2026/12/26.html","dateEvidence":true}]},"2026-12-28:boxing-day-bank-holiday-substitute":{"id":"2026-12-28:boxing-day-bank-holiday-substitute","date":"2026-12-28","verification":"organiser","summary":"In 2026, the UK’s Boxing Day bank holiday is Monday 28 December. The usual 26 December date falls on a Saturday, so the official holiday is observed on a substitute weekday.","sections":[{"heading":"Why the date is different","body":"GOV.UK lists 28 December 2026 as the Boxing Day substitute bank holiday in England and Wales, Scotland, and Northern Ireland. The cultural date of Boxing Day remains 26 December; the substitute is the weekday used for the bank-holiday calendar, not a change to when every tradition takes place."},{"heading":"Make plans around the right calendar","body":"A bank holiday can affect opening hours, travel timetables and appointments, while many people still work through it. If you are planning a meeting or a relaxed outing, check the actual service or venue rather than assuming everything is open or closed. The entry is specific to the UK and to 2026, so it should not be copied into another country’s calendar automatically."}],"activity":{"text":"Check the official dates before making plans, then choose one low-effort way to use the day if your own schedule allows.","label":"Check UK bank-holiday dates","url":"https://www.gov.uk/bank-holidays"},"sources":[{"label":"GOV.UK: official 2026 bank holidays","url":"https://www.gov.uk/bank-holidays","dateEvidence":true}]},"2026-12-30":{"id":"2026-12-30","date":"2026-12-30","verification":"independent-calendar","summary":"An informal day for the smoky, salty ingredient that escapes the breakfast plate. 🥓 Bacon Day falls on 30 December, with a little room for food experimentation between the larger festive dates.","sections":[{"heading":"Not every bacon day is the same","body":"Independent calendars list this December observance separately from other bacon-themed dates during the year. Bacon itself also varies: cuts, curing and smoking methods differ between countries and producers. What one person imagines as a crisp strip may be quite different from another person’s usual breakfast rasher."},{"heading":"Make the contrast interesting","body":"The ingredient is often used for texture and seasoning as well as for the main part of a dish. A small amount can sit alongside sweet, sharp or fresh flavours, which is why it appears in so many sandwiches and festive accompaniments. If you do not eat pork, you can still use the day as a prompt to compare a smoky plant-based alternative or explore a different version of a familiar recipe."}],"activity":{"text":"Make a small sandwich or savoury snack with a new flavour pairing, then ask someone to judge the result without knowing your grand culinary intentions.","label":"Explore Bacon Day ideas","url":"https://nationaldaycalendar.com/celebrations/bacon-day-december-30"},"sources":[{"label":"National Day Calendar: Bacon Day","url":"https://nationaldaycalendar.com/celebrations/bacon-day-december-30","dateEvidence":true}]},"2026-12-31:national-champagne-day":{"id":"2026-12-31:national-champagne-day","date":"2026-12-31","verification":"independent-calendar","summary":"A suitably sparkling date for a year-end toast. 🥂 The informal US food-and-drink observance on 31 December celebrates Champagne, while the moment you are marking can matter more than what is in the glass.","sections":[{"heading":"A name connected to a place","body":"Champagne comes from the Champagne region of France and is made under rules associated with that name. It is one member of a much wider world of sparkling drinks. The bubbles are part of the appeal, but the region, production and blending are also subjects worth exploring."},{"heading":"Celebrate on your own terms","body":"National Day Calendar records the December date and notes that the observance’s exact origin is not established. A small toast can be about a friendship, something completed or simply getting through a difficult year. Alcohol-free bubbles or another favourite drink work perfectly well for that moment. If you are interested in the wine itself, the official Champagne website offers resources on serving and tasting rather than relying only on a bottle’s festive image."}],"activity":{"text":"Write down one specific thing worth remembering from the year and share a toast with your choice of drink; explore the tasting guide if Champagne interests you.","label":"Explore Champagne tasting","url":"https://www.champagne.fr/en/champagne-tasting"},"sources":[{"label":"National Day Calendar: Champagne Day","url":"https://nationaldaycalendar.com/celebrations/national-champagne-day-december-31/","dateEvidence":true},{"label":"Comité Champagne: tasting resources","url":"https://www.champagne.fr/en/champagne-tasting","dateEvidence":false}]},"2026-11-01:dia-de-los-muertos-begins":{"id":"2026-11-01:dia-de-los-muertos-begins","date":"2026-11-01","verification":"organiser","summary":"Marigolds, favourite foods and family stories welcome the memory of loved ones. Mexico’s Día de Muertos is a living tradition of remembrance, with its best-known celebrations on 1–2 November and distinctive customs in different communities.","sections":[{"heading":"A welcome, not a farewell","body":"In the Indigenous traditions recognised by UNESCO, the dead are understood to return temporarily to the world of the living. Families prepare offerings at home and in cemeteries, including favourite dishes, candles, flowers and paper decorations. The care given to an ofrenda expresses an ongoing relationship with people who have died."},{"heading":"Why the dates vary","body":"The festival brings together Indigenous beliefs and Catholic observances around All Saints’ and All Souls’ Days. Some communities begin commemorations in late October, while 1 November often remembers children and 2 November adults. It is much more than a single costume or a Mexican version of Halloween; local and family meanings matter."}],"activity":{"text":"Choose one photograph and write down the story you most want to remember about that person.","label":"Explore the tradition","url":"https://ich.unesco.org/en/RL/day-of-the-dead-heritage-00054"},"sources":[{"label":"UNESCO: Día de Muertos in Mexico","url":"https://www.unesco.org/es/articles/el-retorno-de-lo-querido-celebracion-del-dia-de-muertos-en-mexico","dateEvidence":true},{"label":"UNESCO intangible cultural heritage","url":"https://ich.unesco.org/en/RL/day-of-the-dead-heritage-00054","dateEvidence":false}]},"2026-11-02:end-impunity-for-crimes-against-journalists":{"id":"2026-11-02:end-impunity-for-crimes-against-journalists","date":"2026-11-02","verification":"organiser","summary":"This United Nations day asks a difficult question: what happens when attacks on journalists go unpunished? It highlights the need for accountability, independent reporting and an environment where people can investigate matters of public interest safely.","sections":[{"heading":"Why 2 November?","body":"The UN General Assembly established this observance through Resolution 68/163. The date commemorates two French journalists killed in Mali on 2 November 2013. Its focus is not only remembrance: it asks states to prevent attacks, investigate crimes and make justice available to victims and their families."},{"heading":"Why it reaches everyone","body":"Violence and intimidation can silence reporting about corruption, human rights and organised crime. Threats also include harassment and attacks online, rather than only killings. When journalists cannot work freely, the public loses information it needs. Supporting their safety therefore also protects the ability of communities to ask questions and make informed choices."}],"activity":{"text":"Read one investigation from a credible independent newsroom, then look at how its evidence is documented.","label":"Understand the UN observance","url":"https://www.un.org/en/events/journalists/index.shtml"},"sources":[{"label":"United Nations: end impunity for crimes against journalists","url":"https://www.un.org/en/events/journalists/index.shtml","dateEvidence":true}]},"2026-11-03:one-health-day":{"id":"2026-11-03:one-health-day","date":"2026-11-03","verification":"organiser","summary":"People, animals and the environments we share are connected. One Health Day brings those connections into focus, encouraging different fields to work together instead of treating human health, animal health and planetary health as separate stories.","sections":[{"heading":"A shared approach","body":"The One Health Commission, One Health Platform and One Health Initiative Team launched the day in 2016. It is observed annually on 3 November, although participating projects and events can happen throughout the year. The initiative brings together people from many professions and communities to learn from one another."},{"heading":"Look for the connections","body":"A practical way into the idea is to follow one everyday subject across boundaries: food production, clean water or the relationship between people and wildlife. Each involves more than one kind of expertise. The day encourages education and collaboration so problems can be understood in their wider setting rather than from a single viewpoint."}],"activity":{"text":"Pick an everyday item of food and trace the people, animals and environment involved in producing it.","label":"Explore One Health projects","url":"https://www.onehealthcommission.org/en/events_since_2001/one_health_day/"},"sources":[{"label":"One Health Commission: official One Health Day","url":"https://www.onehealthcommission.org/en/events_since_2001/one_health_day/","dateEvidence":true}]},"2026-11-05:bonfire-night":{"id":"2026-11-05:bonfire-night","date":"2026-11-05","verification":"organiser","summary":"Fireworks, woolly layers and a dark November sky: Bonfire Night marks the failure of the Gunpowder Plot in 1605. 🎆 Its familiar celebrations have grown from a much more complicated history of politics, religion and public commemoration.","sections":[{"heading":"Behind the fireworks","body":"The plot aimed to destroy the House of Lords during the State Opening of Parliament. Guy Fawkes was discovered with the gunpowder, but Robert Catesby was the leading conspirator. Parliament later made 5 November an annual thanksgiving, and the custom developed through church bells, bonfires and fireworks."},{"heading":"A tradition with a history","body":"Effigies and celebrations have changed over the centuries, and older commemorations reflected hostility towards Catholics. Today, many people know the date mainly through community firework displays. Events may happen on nearby evenings rather than exactly 5 November, so check the organiser’s date before setting off for a show."}],"activity":{"text":"Choose an organised local display, or explore the original plot through Parliament’s illustrated history.","label":"Discover the Gunpowder Plot","url":"https://www.parliament.uk/about/faqs/house-of-commons-faqs/gunpowder-plot/"},"sources":[{"label":"UK Parliament: Gunpowder Plot questions and history","url":"https://www.parliament.uk/about/faqs/house-of-commons-faqs/gunpowder-plot/","dateEvidence":true}]},"2026-11-06:national-saxophone-day":{"id":"2026-11-06:national-saxophone-day","date":"2026-11-06","verification":"independent-calendar","summary":"A little brass, a lot of personality. 🎷 This informal music day falls on the birthday of Adolphe Sax, the Belgian inventor whose family of saxophones found a place in jazz, pop, classical music and beyond.","sections":[{"heading":"Meet the inventor","body":"Adolphe Sax was born on 6 November 1814. His instrument was patented in 1846, and it was conceived for military bands and orchestras before becoming especially familiar through jazz and popular music. The Metropolitan Museum’s collection shows that the Sax family’s inventive work extended beyond the one instrument carrying his name."},{"heading":"One name, many voices","body":"A saxophone is not a single size or sound. Listening to different members of the family makes that obvious: some parts sit high and bright, while others carry a much lower voice. For today, compare recordings rather than simply looking for the fastest solo. Notice how the instrument changes the feeling of a whole piece."}],"activity":{"text":"Listen to the Arizona PBS feature, then compare a saxophone-led jazz track with an orchestral recording.","label":"Hear the saxophone feature","url":"https://azpbs.org/takenote/2022/11/saxophone-day/"},"sources":[{"label":"Arizona PBS: National Saxophone Day","url":"https://azpbs.org/takenote/2022/11/saxophone-day/","dateEvidence":true},{"label":"Metropolitan Museum: Celebrating Sax","url":"https://www.metmuseum.org/de/perspectives/celebrating-sax","dateEvidence":false}]},"2026-11-07:national-bittersweet-chocolate-with-almonds-day":{"id":"2026-11-07:national-bittersweet-chocolate-with-almonds-day","date":"2026-11-07","verification":"independent-calendar","summary":"Dark chocolate meets a satisfying crunch. 🍫 This wonderfully specific US food day celebrates bittersweet chocolate and almonds together, whether that means a tiny handful, a square of bark or a slice of something beautifully chocolatey.","sections":[{"heading":"A very specific pairing","body":"National Day Calendar lists this celebration on 7 November. It is a food observance rather than a public holiday, and the pleasure is in the pairing: chocolate brings richness while almonds add a contrasting texture. There is no need to turn the date into a health claim or a reason for an elaborate feast."},{"heading":"Make a small occasion","body":"For an easy tasting, try the same chocolate with whole roasted almonds and with finely chopped almonds, noticing how texture changes the experience. If baking sounds more appealing, the linked flourless chocolate-and-almond cake gives the combination a proper dessert outing. Check ingredients if sharing with someone who has a nut allergy."}],"activity":{"text":"Bake the chocolate-and-almond cake below, or make a little tasting plate with your favourite dark chocolate.","label":"Try the chocolate almond cake","url":"https://www.bbcgoodfood.com/recipes/flourless-chocolate-almond-cake"},"sources":[{"label":"National Day Calendar: bittersweet chocolate with almonds","url":"https://nationaldaycalendar.com/celebrations/national-bittersweet-chocolate-with-almonds-day-november-7/","dateEvidence":true},{"label":"Good Food: flourless chocolate and almond cake","url":"https://www.bbcgoodfood.com/recipes/flourless-chocolate-almond-cake","dateEvidence":false}]},"2026-11-08:national-stem-steam-day":{"id":"2026-11-08:national-stem-steam-day","date":"2026-11-08","verification":"organiser","summary":"Science can look like play, and art can be part of the experiment. 🔬 This US initiative celebrates science, technology, engineering, arts and mathematics, encouraging children to explore how these subjects appear in the things they already enjoy.","sections":[{"heading":"Why 8 November?","body":"MGA Entertainment established the day in 2015 alongside its Project Mc² brand. The fictional team was called NOV8, pronounced “innovate”, which supplied the November 8 date. The origin is a company-led educational campaign, rather than a United Nations observance or a public holiday."},{"heading":"Try thinking like a designer","body":"STEM covers science, technology, engineering and mathematics; STEAM makes the role of arts explicit. A paper bridge is a useful miniature example: shape, material, measurement and appearance all influence the result. Build two versions, test them in the same way, and change one feature at a time. A surprising failure gives you something new to investigate."}],"activity":{"text":"Build two bridges from scrap paper and compare how many coins each can hold before bending.","label":"Read the day’s founding announcement","url":"https://www.prnewswire.com/news-releases/november-8-is-national-stemsteam-day-300173696.html"},"sources":[{"label":"MGA Entertainment: founding announcement via PR Newswire","url":"https://www.prnewswire.com/news-releases/november-8-is-national-stemsteam-day-300173696.html","dateEvidence":true}]},"2026-11-10:world-science-day-for-peace-and-development":{"id":"2026-11-10:world-science-day-for-peace-and-development","date":"2026-11-10","verification":"organiser","summary":"Science belongs in everyday conversation, not only in laboratories. This UNESCO observance highlights its role in society, invites public discussion and asks how knowledge can help people build more peaceful and sustainable futures together.","sections":[{"heading":"The purpose of the day","body":"UNESCO proclaimed the observance in 2001, and it is held every 10 November. Its goals include connecting scientific work with the wider public and showing why research matters in daily life. The emphasis is on informed participation, so people can engage with scientific developments rather than simply receive conclusions from a distance."},{"heading":"The 2026 focus","body":"UNESCO’s 2026 theme is common ground through science diplomacy. It draws attention to the ways scientific cooperation can connect people and countries. A useful way to join in is to follow a question that crosses borders, such as shared environmental research, and ask who contributes the evidence, who benefits and who still needs a voice."}],"activity":{"text":"Choose one science story and compare the headline with the original research or institution’s explanation.","label":"Explore UNESCO’s science day","url":"https://www.unesco.org/en/days/science-peace-development"},"sources":[{"label":"UNESCO: World Science Day for Peace and Development","url":"https://www.unesco.org/en/days/science-peace-development","dateEvidence":true}]},"2026-11-11:world-origami-day":{"id":"2026-11-11:world-origami-day","date":"2026-11-11","verification":"organiser","summary":"One sheet, a few folds, and suddenly it has become something else. 🕊️ Japan’s Origami Day falls on 11 November, also the closing date of World Origami Days, an international celebration running from 24 October.","sections":[{"heading":"A day within a longer celebration","body":"OrigamiUSA promotes World Origami Days from 24 October, the birthday of its founder Lillian Oppenheimer, through 11 November, Origami Day in Japan. The international celebration therefore finishes, rather than begins, on this date. November 11 is a useful moment to share something folded or discover the Japanese observance."},{"heading":"More than a finished model","body":"Origami can be shared by teaching one fold, giving a model to a friend or displaying something you have made. You do not need elaborate paper or an impressive result to begin. Choose a simple model, practise it twice, and notice which instructions become clearer the second time. The process is part of the pleasure."}],"activity":{"text":"Fold a simple model from a square of scrap paper, then teach it to someone without touching their sheet.","label":"Find origami activities","url":"https://www.origamiusa.org/wod"},"sources":[{"label":"OrigamiUSA: World Origami Days","url":"https://www.origamiusa.org/wod","dateEvidence":true},{"label":"OrigamiUSA: 2026 celebration","url":"https://www.origamiusa.org/wod2026","dateEvidence":true}],"title":"Origami Day","researchNote":"The organiser distinguishes Japan’s Origami Day on 11 November from World Origami Days, which run 24 October–11 November. Renamed this single-date entry to avoid implying the whole international campaign begins today."},"2026-11-12:national-happy-hour-day":{"id":"2026-11-12:national-happy-hour-day","date":"2026-11-12","verification":"independent-calendar","summary":"A small break can become a social occasion. 🍹 This informal US calendar day celebrates happy hour, but the nicest part can simply be spending an unhurried hour with people you enjoy, with or without alcohol.","sections":[{"heading":"What the date means","body":"Independent calendars list National Happy Hour Day on 12 November. It is not a public holiday or a requirement for bars and restaurants to offer a promotion. Opening times, prices and event details belong to each venue, so a listing for the date is not a promise of a particular deal."},{"heading":"Make your own version","body":"Give the occasion a simple shape: choose a time, pick a drink you like and invite someone for a proper catch-up. A café, a mocktail at home or a short video call can work just as well as a bar. Decide the plan beforehand so the focus stays on enjoying the company rather than chasing an offer."}],"activity":{"text":"Invite a friend for a one-hour catch-up and try a new alcohol-free drink together.","label":"Explore the informal observance","url":"https://nationaltoday.com/national-happy-hour-day/"},"sources":[{"label":"National Today: National Happy Hour Day","url":"https://nationaltoday.com/national-happy-hour-day/","dateEvidence":true}]},"2026-11-13:symphonic-metal-day":{"id":"2026-11-13:symphonic-metal-day","date":"2026-11-13","verification":"independent-calendar","summary":"Big guitars meet even bigger drama. 🎻 Symphonic Metal Day is an informal music observance for the genre that mixes heavy metal with orchestral sounds, theatrical scale and, sometimes, soaring voices that seem built for a fantasy soundtrack.","sections":[{"heading":"What makes it symphonic?","body":"The name points to the meeting of metal’s weight and intensity with textures associated with orchestral music. It is a useful listening invitation rather than a rigid checklist: arrangements, voices and instruments can vary widely. Arizona PBS marks the day on 13 November with a short feature exploring the fusion."},{"heading":"Listen for the layers","body":"Try following a single layer of a song instead of taking it all in at once. First notice the rhythm section, then the strings, keyboards or other orchestral textures, and finally the vocal line. A second listen can reveal how these parts trade attention. You do not need to know the terminology to hear the contrasts."}],"activity":{"text":"Play the PBS listening feature, then choose one track and listen again for a layer you missed.","label":"Hear the symphonic metal feature","url":"https://azpbs.org/takenote/2026/11/symphonic-metal-day/"},"sources":[{"label":"Arizona PBS: Symphonic Metal Day","url":"https://azpbs.org/takenote/2026/11/symphonic-metal-day/","dateEvidence":true}]},"2026-11-15:national-recycling-day":{"id":"2026-11-15:national-recycling-day","date":"2026-11-15","verification":"organiser","summary":"A recycling symbol is a starting point, not the whole answer. ♻️ America Recycles Day invites people to learn what their local system actually accepts and turn that knowledge into habits that reduce waste throughout the year.","sections":[{"heading":"The organised observance","body":"Keep America Beautiful runs America Recycles Day on 15 November. It is also widely called National Recycling Day in US calendars. The campaign combines education, local events and practical action, with the aim of helping materials stay useful rather than becoming waste after a single use."},{"heading":"Make it local","body":"Recycling arrangements differ between places, so a rule from another town or country may not apply to your own collection. Pick one confusing item and look it up on your council or waste provider’s website. Then make a small reminder where you sort rubbish. Knowing what belongs in the bin is more useful than guessing hopefully."}],"activity":{"text":"Check the local rule for one item you regularly throw away, then try the campaign’s recycling quiz.","label":"Test your recycling knowledge","url":"https://kab.org/our-signature-programs/america-recycles-day/"},"sources":[{"label":"Keep America Beautiful: America Recycles Day","url":"https://kab.org/our-signature-programs/america-recycles-day/","dateEvidence":true}],"title":"America Recycles Day","researchNote":"Used the organiser’s name, America Recycles Day; National Recycling Day is an alternative US calendar label, not a separate international observance."},"2026-11-16:odd-socks-day":{"id":"2026-11-16:odd-socks-day","date":"2026-11-16","verification":"organiser","summary":"The drawer’s odd socks finally get their moment. 🧦 Odd Socks Day opens Anti-Bullying Week by celebrating individuality and reminding people that differences deserve respect, with no special outfit or expensive costume needed to take part.","sections":[{"heading":"The 2026 date","body":"The Anti-Bullying Alliance confirms Monday 16 November for Odd Socks Day 2026. Anti-Bullying Week runs from 16–20 November, with the theme “Break the Silence”. Andy Day and his band, Andy and the Odd Socks, support the campaign, which is coordinated in England, Wales and Northern Ireland."},{"heading":"A simple gesture with a message","body":"The invitation is to wear mismatched socks at school, work or home and use them to start a conversation about being yourself. Taking part does not depend on fundraising. The more meaningful part is what happens after the photograph: listening when someone speaks up, noticing exclusion and helping people feel that they belong."}],"activity":{"text":"Choose your most gloriously mismatched pair and ask someone what helps them feel included.","label":"Use the official activity resources","url":"https://anti-bullyingalliance.org.uk/anti-bullying-week-2026/odd-socks-day/what-odd-socks-day"},"sources":[{"label":"Anti-Bullying Alliance: Odd Socks Day 2026","url":"https://anti-bullyingalliance.org.uk/anti-bullying-week-2026/odd-socks-day/what-odd-socks-day","dateEvidence":true}]},"2026-11-17:national-homemade-bread-day":{"id":"2026-11-17:national-homemade-bread-day","date":"2026-11-17","verification":"independent-calendar","summary":"A loaf cooling on the counter is a very convincing reason to stay home. 🍞 National Homemade Bread Day is an informal US food day for mixing, kneading, baking and sharing something made with your own hands.","sections":[{"heading":"An informal kitchen tradition","body":"National Day Calendar lists the day on 17 November and says its founding origin remains uncertain. It celebrates homemade bread rather than one particular recipe. Yeast loaves, quick breads and family favourites all offer different ways to take part, depending on how much time and equipment you have."},{"heading":"Give the dough time","body":"A first loaf is easier to enjoy when it is not squeezed into a rushed schedule. Read the whole recipe before starting and include resting or proving time in the plan, not only the minutes spent mixing. The linked easy white bread recipe offers a straightforward place to begin, with a loaf you can slice, share or freeze."}],"activity":{"text":"Try a simple white loaf, then save a slice for tomorrow’s toast before everyone claims the crust.","label":"Bake an easy white loaf","url":"https://www.bbcgoodfood.com/recipes/easy-white-bread"},"sources":[{"label":"National Day Calendar: Homemade Bread Day","url":"https://nationaldaycalendar.com/celebrations/national-homemade-bread-day-november-17","dateEvidence":true},{"label":"Good Food: easy white bread","url":"https://www.bbcgoodfood.com/recipes/easy-white-bread","dateEvidence":false}]},"2026-11-18:world-copd-day":{"id":"2026-11-18:world-copd-day","date":"2026-11-18","verification":"organiser","summary":"World COPD Day brings attention to chronic obstructive pulmonary disease and the people living with it. Its 2026 focus is earlier diagnosis and better management, alongside access to care, reliable information and support for patients and families.","sections":[{"heading":"The 2026 campaign","body":"The Global Initiative for Chronic Obstructive Lung Disease, known as GOLD, confirms 18 November for World COPD Day 2026. It coordinates the observance with health professionals and patient groups around the world. This year’s theme highlights how missed or delayed diagnosis can affect people’s opportunities to receive appropriate care."},{"heading":"A wider view of lung health","body":"The campaign notes that COPD is not only a story about tobacco: other environmental exposures can contribute, and the condition is often misunderstood. The day is a chance to listen to lived experience and learn from qualified organisations. An awareness-day page cannot diagnose breathlessness or decide treatment; those questions belong with a healthcare professional."}],"activity":{"text":"Read the official campaign page and share one reliable resource rather than an unverified health claim.","label":"Explore GOLD’s 2026 campaign","url":"https://goldcopd.org/World%20COPD%20Day%202026/"},"sources":[{"label":"GOLD: World COPD Day 2026","url":"https://goldcopd.org/World%20COPD%20Day%202026/","dateEvidence":true}]},"2026-11-20:world-children-s-day":{"id":"2026-11-20:world-children-s-day","date":"2026-11-20","verification":"organiser","summary":"Children’s rights deserve more than a grown-up conversation about children. World Children’s Day gives young people a platform to speak about their lives, priorities and futures, and asks decision-makers to listen and act without discrimination.","sections":[{"heading":"Why 20 November?","body":"The date marks two milestones adopted by the UN General Assembly: the Declaration of the Rights of the Child in 1959 and the Convention on the Rights of the Child in 1989. UNICEF confirms that the 2026 observance takes place on 20 November, with action centred on protecting and fulfilling children’s rights."},{"heading":"Let children lead","body":"UNICEF’s activities include children taking over visible roles in media, politics, business and other settings so their perspectives can be heard. Buildings and schools may also turn blue in solidarity. At a smaller scale, the same principle means asking young people what matters to them, making space for their answers and following through on what can change."}],"activity":{"text":"Ask a child or young person what they would change about their community, then listen without correcting the answer.","label":"Explore children’s rights activities","url":"https://www.unicef.org/take-action/campaigns/world-childrens-day"},"sources":[{"label":"UNICEF: World Children’s Day 2026","url":"https://www.unicef.org/take-action/campaigns/world-childrens-day","dateEvidence":true}]},"2026-11-21:world-hello-day":{"id":"2026-11-21:world-hello-day","date":"2026-11-21","verification":"organiser","summary":"Ten greetings, one very simple idea: communication matters. 👋 World Hello Day invites people to acknowledge one another and use a small personal gesture to express support for peace, understanding and resolving conflict through conversation.","sections":[{"heading":"A grassroots beginning","body":"The event began in response to the 1973 conflict between Egypt and Israel. Its official website gives 21 November as the annual date and describes participation in countries around the world. Rather than asking everyone to attend a single event, it connects many small local interactions to a wider message about peace."},{"heading":"How to join in","body":"The invitation is to greet ten people. They might be neighbours, colleagues, someone at a shop or friends you have not spoken to recently. A greeting need not demand a conversation from someone who is busy or uncomfortable. The point is to acknowledge another person warmly and leave a little more room for human contact."}],"activity":{"text":"Say a friendly hello to ten people today, in person or through a message that feels personal.","label":"See the World Hello Day project","url":"https://worldhelloday.org/"},"sources":[{"label":"World Hello Day: official project","url":"https://worldhelloday.org/","dateEvidence":true}]},"2026-11-22:love-your-freckles-day":{"id":"2026-11-22:love-your-freckles-day","date":"2026-11-22","verification":"independent-calendar","summary":"An informal invitation to stop treating every distinctive feature as something to fix. ✨ Love Your Freckles Day celebrates freckled faces and the little details that make people recognisable, without turning anyone’s appearance into a competition.","sections":[{"heading":"A light-hearted calendar date","body":"Independent calendars place Love Your Freckles Day on 22 November. There is no well-documented founding organiser or official public-holiday status behind the listing. It works best as a playful prompt for appreciating natural variation, rather than as a claim that one kind of skin or appearance is better than another."},{"heading":"Make appreciation specific","body":"If you want to join in, try taking an unfiltered photograph that looks like you on an ordinary day. Notice the expression, the setting or a feature you would usually edit out. Compliments to other people are kinder when they are welcome, and nobody has to enjoy being photographed or discussing their skin to belong in the celebration."}],"activity":{"text":"Take an optional unfiltered portrait, or write down one thing you like about your appearance without adding a qualification.","label":"About the informal day","url":"https://nationaltoday.com/love-freckles-day/"},"sources":[{"label":"National Today: Love Your Freckles Day","url":"https://nationaltoday.com/love-freckles-day/","dateEvidence":true}]},"2026-11-23:thankful-for-my-dog-day":{"id":"2026-11-23:thankful-for-my-dog-day","date":"2026-11-23","verification":"independent-calendar","summary":"For the enthusiastic greetings, ridiculous sleeping positions and excellent company. 🐕 Thankful For My Dog Day is an informal US pet observance for noticing what a dog brings to daily life and giving some thoughtful attention back.","sections":[{"heading":"Where it came from","body":"Dogtipper’s pet-holiday calendar lists the date as 23 November and identifies M.Y.O.S. Canine Muscle Formula as its founder in 2020. That makes this a company-started appreciation day, not an official animal-welfare holiday. The date is an excuse for gratitude; it does not require buying any particular product."},{"heading":"Let the dog choose the fun","body":"A celebration can be based on what your own dog enjoys: a familiar walk with extra sniffing time, a favourite game or a quiet moment together. A dog that dislikes crowds or costumes does not need either for a photograph. If you do not have a dog, learning about a local rescue’s work is another way to appreciate them."}],"activity":{"text":"Give a dog you know ten unhurried minutes of their favourite ordinary activity, without a phone in your hand.","label":"Explore the pet-day background","url":"https://www.dogtipper.com/november-pet-holidays/"},"sources":[{"label":"Dogtipper: November pet holidays and founder","url":"https://www.dogtipper.com/november-pet-holidays/","dateEvidence":true},{"label":"Hepper: date and founder background","url":"https://articles.hepper.com/when-is-thankful-for-my-dog-day/","dateEvidence":true}]},"2026-11-24:loy-krathong":{"id":"2026-11-24:loy-krathong","date":"2026-11-24","verification":"organiser","summary":"Candlelit offerings reflect on the water under a full moon. Loy Krathong is a Thai festival of gratitude, renewal and community, with local traditions that make the celebrations in different parts of the country distinct.","sections":[{"heading":"The 2026 date","body":"Thailand’s government confirms Tuesday 24 November 2026, the full moon of the twelfth lunar month. A krathong is a small floating vessel, traditionally made using banana leaves and decorated with flowers, candles and incense. Larger local celebrations may run for several days around the main festival night."},{"heading":"More than a beautiful photograph","body":"Government descriptions connect floating krathongs with thanking the water that sustains life and asking forgiveness for polluting waterways. Some communities also honour the Buddha and maintain their own inherited customs. Making the offerings by hand passes on skills such as leaf folding and flower arranging. If visiting, follow local guidance and the event’s environmental rules rather than assuming every material or release is appropriate."}],"activity":{"text":"Explore a community’s celebration and learn the meaning of a krathong before making or photographing one.","label":"Explore the official festival guide","url":"https://www.thailand.go.th/public/useful-information-detail/celebrate-loy-krathong-across-thailand-on-24-november-under-the-full-moon"},"sources":[{"label":"Thai government: Loy Krathong 24 November 2026","url":"https://www.thailand.go.th/public/useful-information-detail/celebrate-loy-krathong-across-thailand-on-24-november-under-the-full-moon","dateEvidence":true}]},"2026-11-26:national-cake-day":{"id":"2026-11-26:national-cake-day","date":"2026-11-26","verification":"independent-calendar","summary":"A very convenient date for a slice. 🍰 National Cake Day is an informal US food celebration that makes room for everything from a simple sponge to an ambitious layered creation, with no birthday candles required.","sections":[{"heading":"An occasion, not an official holiday","body":"National Day Calendar lists Cake Day on 26 November and says its origin has not been established. The day celebrates cake in general rather than a particular style. It can be homemade, bought from a bakery or shared from a cake already sitting in the kitchen."},{"heading":"Choose your level of ambition","body":"There is no need to begin with the tallest cake on the internet. A plain vanilla sponge gives you something to decorate in your own way, while a single bakery slice turns the date into a small outing. If baking with someone, divide the jobs before starting and save the decorating for the part you can do together."}],"activity":{"text":"Bake a vanilla cake or split a bakery slice with someone and rate the best part: sponge, filling or icing.","label":"Try a vanilla cake recipe","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cake"},"sources":[{"label":"National Day Calendar: National Cake Day","url":"https://nationaldaycalendar.com/celebrations/national-cake-day-november-26","dateEvidence":true},{"label":"Good Food: vanilla cake","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cake","dateEvidence":false}]},"2026-11-27:lancashire-day":{"id":"2026-11-27:lancashire-day","date":"2026-11-27","verification":"organiser","summary":"A day for the Red Rose county and the people who call it home. 🌹 Lancashire Day celebrates local identity, history and community, with proclamations and traditions that reach beyond today’s administrative boundary lines.","sections":[{"heading":"Why 27 November?","body":"Friends of Real Lancashire connects the date to 1295, when Lancashire’s first elected representatives were called to Westminster for Edward I’s Model Parliament. The organisation promotes the historic county’s identity, and town criers read a Lancashire Day proclamation on 27 November."},{"heading":"A county in everyday life","body":"The celebration is also a chance to explore the things people associate with Lancashire now: their towns, landscapes, food, speech and family stories. County identity can mean different things to different people, particularly where historic and administrative boundaries differ. Learning one local story is a more rewarding starting point than treating the day as a geography quiz."}],"activity":{"text":"Ask someone with a Lancashire connection for their favourite place, phrase or family food tradition.","label":"Read the Lancashire Day story","url":"https://forl.co.uk/lancashire-day/"},"sources":[{"label":"Friends of Real Lancashire: Lancashire Day","url":"https://forl.co.uk/lancashire-day/","dateEvidence":true},{"label":"Visit Lancashire: annual proclamation","url":"https://www.visitlancashire.com/lancashire-day/the-lancashire-day-proclamation","dateEvidence":true}]},"2026-11-28:albanian-independence-day":{"id":"2026-11-28:albanian-independence-day","date":"2026-11-28","verification":"organiser","summary":"Red flags and a double-headed eagle mark a defining date in Albania’s history. Albanian Independence Day commemorates the declaration made in Vlorë on 28 November 1912 and is celebrated by Albanians at home and around the world.","sections":[{"heading":"The historic moment","body":"Ismail Qemali raised the Albanian flag in Vlorë when independence was declared in 1912. Albanian diplomatic accounts describe 28 November as both Independence Day and the Day of the National Flag. It is a date of remembrance for the people involved in the creation of the independent Albanian state."},{"heading":"Explore beyond the symbol","body":"A national day offers an opening into a country’s languages, music, places and personal histories, but it does not mean everyone celebrates in exactly the same way. Try learning how someone with an Albanian connection marks the occasion, or explore a cultural story rather than only a list of political dates. The best discoveries often begin with a specific person or place."}],"activity":{"text":"Locate Vlorë on a map, then ask an Albanian friend or cultural organisation about a favourite national-day tradition.","label":"Explore the Albanian historical account","url":"https://arkiva.president.al/en/arkivi-historik/"},"sources":[{"label":"Albanian presidency: historical archive","url":"https://arkiva.president.al/en/arkivi-historik/","dateEvidence":true},{"label":"Albanian embassy: independence commemoration","url":"https://ambasadat.gov.al/kosova/en/newsroom/the-speech-of-the-ambassador-of-albania-in-kosovo-h-e-mr-petrit-malaj-at-the-reception-on-the-occasion-of-the-111th-independence-of-albania/","dateEvidence":true}]},"2026-11-30:st-andrew-s-day":{"id":"2026-11-30:st-andrew-s-day","date":"2026-11-30","verification":"organiser","summary":"Scotland’s national day makes room for music, food, stories and a generous welcome. St Andrew’s Day honours the country’s patron saint on 30 November, with celebrations among Scottish communities both in Scotland and around the world.","sections":[{"heading":"A date shared around the world","body":"Scotland’s national cultural information site describes 30 November celebrations through dancing, music and food. St Andrew’s societies overseas helped spread the tradition, including a society founded in Charleston in 1729. The day connects national identity with communities that have carried Scottish connections far beyond Scotland itself."},{"heading":"What it means in 2026","body":"The Scottish Government lists Monday 30 November as the 2026 St Andrew’s Day bank holiday. A bank holiday does not mean every workplace or venue closes, so check individual arrangements if planning an outing. To join the cultural side, choose a Scottish musician, a local story or a dish you have not tried before."}],"activity":{"text":"Make a short playlist of Scottish artists, including one musician you have never listened to before.","label":"Explore St Andrew’s Day traditions","url":"https://www.scotland.org/events/st-andrews-day/who-was-st-andrew"},"sources":[{"label":"Scottish Government: 2026 bank holidays","url":"https://www.gov.scot/publications/bank-holidays/pages/current-year/","dateEvidence":true},{"label":"Scotland.org: St Andrew’s Day history","url":"https://www.scotland.org/events/st-andrews-day/who-was-st-andrew","dateEvidence":true}]},"2026-12-01:world-aids-day":{"id":"2026-12-01:world-aids-day","date":"2026-12-01","verification":"organiser","summary":"A day of solidarity with people living with HIV and remembrance of those lost to AIDS-related illness. World AIDS Day also challenges stigma and asks whether prevention, testing, treatment and support are genuinely accessible to everyone who needs them.","sections":[{"heading":"Why the red ribbon?","body":"World AIDS Day has been held on 1 December since 1988. UNAIDS describes the red ribbon as a symbol of awareness and support for people living with HIV. Campaigns bring together communities, health organisations, governments and civil society, with the voices of people living with HIV at the centre."},{"heading":"The 2026 focus","body":"The 2026 UNAIDS campaign centres on access: services, rights, resources and political leadership. Its message is that scientific progress only helps when people can reach care without barriers or discrimination. A useful contribution is to learn from reliable HIV organisations and challenge an inaccurate assumption, rather than treating awareness as a substitute for listening to lived experience."}],"activity":{"text":"Read a current UNAIDS resource and share one fact that counters stigma, using respectful language.","label":"Explore the 2026 access campaign","url":"https://www.unaids.org/en/2026-world-aids-day"},"sources":[{"label":"UNAIDS: World AIDS Day date and background","url":"https://www.unaids.org/en/World_AIDS_Day","dateEvidence":true},{"label":"UNAIDS: 2026 campaign","url":"https://www.unaids.org/en/2026-world-aids-day","dateEvidence":true}]},"2026-12-03":{"id":"2026-12-03","date":"2026-12-03","verification":"organiser","summary":"Accessibility and equal participation belong in everyday decisions. This United Nations observance focuses on the rights and leadership of disabled people, encouraging communities and institutions to remove barriers rather than expect individuals to work around them alone.","sections":[{"heading":"The 2026 observance","body":"Held on 3 December, the day’s 2026 programme marks twenty years since the UN adopted the Convention on the Rights of Persons with Disabilities. The convention provides a framework for protecting rights and full participation in society. The anniversary is a chance to consider achievements alongside the changes still needed."},{"heading":"Notice the barriers","body":"The UN highlights participation in decisions, accessible information and inclusive communication. You can apply those ideas to an ordinary setting: can people enter a venue, use its information and take part in what happens there? Ask what would help rather than assuming that all disabilities are visible or that one adjustment works for everyone."}],"activity":{"text":"Check one event invitation or shared document for clear text, meaningful image descriptions and accessible practical information.","label":"Explore the UN observance","url":"https://www.un.org/en/observances/day-of-persons-with-disabilities"},"sources":[{"label":"United Nations: International Day of Persons with Disabilities","url":"https://www.un.org/en/observances/day-of-persons-with-disabilities","dateEvidence":true}]},"2026-12-04:international-cheetah-day":{"id":"2026-12-04:international-cheetah-day","date":"2026-12-04","verification":"organiser","summary":"Fast is only the beginning of the story. 🐆 International Cheetah Day celebrates the world’s fastest land mammal while drawing attention to the people, habitats and conservation work needed for cheetahs to survive in the wild.","sections":[{"heading":"Why 4 December?","body":"Cheetah Conservation Fund founder Dr Laurie Marker designated the day in 2010 in memory of Khayam, a cheetah she raised. Khayam’s birthday was 4 December. Work involving Khayam took Marker to Namibia, where she witnessed conflict between farmers protecting livestock and cheetahs living on the same landscape."},{"heading":"Conservation alongside people","body":"The day is not simply a speed contest or an invitation to admire a striking animal photograph. CCF’s account shows why understanding livelihoods and human-wildlife conflict matters. Learning how conservation groups work with local communities gives a fuller picture than imagining wildlife protection as a task carried out far away from people."}],"activity":{"text":"Explore CCF’s story of Khayam and identify one way conservation work includes local communities.","label":"Meet the cheetah conservation project","url":"https://cheetah.org/about/what-we-do/international-cheetah-day/"},"sources":[{"label":"Cheetah Conservation Fund: official International Cheetah Day","url":"https://cheetah.org/about/what-we-do/international-cheetah-day/","dateEvidence":true}]},"2026-12-06":{"id":"2026-12-06","date":"2026-12-06","verification":"organiser","summary":"Small gifts, acts of generosity and stories of a gift-giving saint make 6 December special in many communities. 🎁 Saint Nicholas Day has its own traditions, distinct from Christmas Day, with customs that vary between countries and families.","sections":[{"heading":"A saint behind a familiar figure","body":"Saint Nicholas is connected with the history of Santa Claus and Father Christmas, but the feast also has a Christian meaning of its own. The St Nicholas Center emphasises his example of generosity and care for people in need, with small treats and family celebrations rather than an emphasis on receiving expensive presents."},{"heading":"Not one universal date or custom","body":"The feast is commonly observed on 6 December; some churches following the Julian calendar celebrate on 19 December in the civil calendar. Local customs differ, so a family’s way of marking the day is not a rule for everyone. A thoughtful act given quietly can be as appropriate as a traditional sweet or decoration."}],"activity":{"text":"Leave a small anonymous kindness for someone, or try a Saint Nicholas craft or recipe together.","label":"Find Saint Nicholas activities","url":"https://www.stnicholascenter.org/how-to-celebrate"},"sources":[{"label":"St Nicholas Center: feast dates and celebrations","url":"https://www.stnicholascenter.org/how-to-celebrate","dateEvidence":true}]},"2026-12-07:national-cotton-candy-day":{"id":"2026-12-07:national-cotton-candy-day","date":"2026-12-07","verification":"independent-calendar","summary":"A cloud you can eat is a fairly strong fairground invention. 🍭 National Cotton Candy Day celebrates the spun-sugar treat also known as candy floss or fairy floss, bringing a little carnival nostalgia to December.","sections":[{"heading":"The calendar occasion","body":"National Day Calendar lists the informal US food day on 7 December and notes that its founding origin remains unknown. Cotton candy is associated with fairs, circuses and carnivals, but the calendar date is simply an appreciation day; it is not an anniversary that every venue marks."},{"heading":"Look closely at the cloud","body":"Heated sugar is spun into very fine strands that gather into a much larger-looking puff. The familiar treat is as much about its airy texture as its colour or flavour. If you are sharing some today, try describing the texture before it dissolves, or compare the different names people use for it in different places."}],"activity":{"text":"Share a small puff of candy floss and ask everyone which name suits it best: cotton candy, candy floss or fairy floss.","label":"Explore the cotton candy day","url":"https://nationaldaycalendar.com/celebrations/national-cotton-candy-day-december-7/"},"sources":[{"label":"National Day Calendar: Cotton Candy Day","url":"https://nationaldaycalendar.com/celebrations/national-cotton-candy-day-december-7/","dateEvidence":true}]},"2026-12-09:national-pastry-day":{"id":"2026-12-09:national-pastry-day","date":"2026-12-09","verification":"independent-calendar","summary":"Flaky, crisp, buttery or filled with something delicious: pastry has many personalities. 🥐 This informal US food day celebrates sweet and savoury baking, from a simple tart to a bakery creation worth making a special trip for.","sections":[{"heading":"A whole family of bakes","body":"National Day Calendar places the observance on 9 December, while saying the day’s origin is still uncertain. Pastry is not one single kind of dough: shortcrust, puff, choux and filo produce very different results. The celebration is broad enough to include savoury parcels as well as sweet treats."},{"heading":"Start with a comparison","body":"A bakery visit can become a miniature tasting exercise. Choose two contrasting textures and notice what you like, rather than assuming the most elaborate bake will be your favourite. If making something at home, a recipe using prepared pastry is a perfectly reasonable starting point. The fun is in filling, shaping and sharing it, not proving your patience."}],"activity":{"text":"Try a pastry you would usually overlook, or choose a manageable bake from the recipe collection.","label":"Choose a pastry recipe","url":"https://www.bbcgoodfood.com/recipes/collection/patisserie-recipes"},"sources":[{"label":"National Day Calendar: National Pastry Day","url":"https://nationaldaycalendar.com/celebrations/national-pastry-day-december-9","dateEvidence":true},{"label":"Good Food: patisserie recipes","url":"https://www.bbcgoodfood.com/recipes/collection/patisserie-recipes","dateEvidence":false}]},"2026-12-11":{"id":"2026-12-11","date":"2026-12-11","verification":"organiser","summary":"Mountains are homes, working landscapes and sources of life far beyond their slopes. International Mountain Day looks past the summit photograph to the communities and ecosystems that need attention, with mountain pastoralists at the centre of the 2026 campaign.","sections":[{"heading":"The annual observance","body":"The UN designated 11 December as International Mountain Day, observed annually since 2003. The Food and Agriculture Organization coordinates the global celebration. It aims to build awareness of mountain environments and the opportunities and challenges faced by the people who live and work in them."},{"heading":"The 2026 focus","body":"This year’s theme highlights pastoralists who raise animals and sustain mountain rangelands, knowledge and livelihoods. FAO describes the value of Indigenous and local knowledge for soils, vegetation, water cycles and wildlife habitats. It is a reminder that conservation stories include people’s skills and work, not only scenery that visitors pass through."}],"activity":{"text":"Explore FAO’s mountain stories and learn about one pastoral community you have not heard of before.","label":"Explore the 2026 mountain campaign","url":"https://www.fao.org/international-mountain-day/en/"},"sources":[{"label":"FAO: International Mountain Day 2026","url":"https://www.fao.org/international-mountain-day/en/","dateEvidence":true}]},"2026-12-12:universal-health-coverage-day":{"id":"2026-12-12:universal-health-coverage-day","date":"2026-12-12","verification":"organiser","summary":"Getting the care you need should not mean losing the money for essentials. Universal Health Coverage Day draws attention to access to health services and protection from unaffordable costs, asking governments to turn commitments into practical support.","sections":[{"heading":"Why 12 December?","body":"The UN-designated observance marks the anniversary of the unanimous endorsement of universal health coverage as a global development priority in 2012. The World Health Organization uses the date as a rallying point for people still waiting for affordable care and for advocates holding decision-makers to their commitments."},{"heading":"What the 2026 campaign asks","body":"WHO’s 2026 campaign closes a three-year series focused on financial protection. It calls for removing barriers to care, meeting people’s health needs and protecting them from costs they cannot afford. The day concerns how health systems work for whole communities, rather than suggesting that an individual can solve access problems simply by making better personal choices."}],"activity":{"text":"Look at the campaign materials and identify one access barrier that matters in your own community.","label":"Explore WHO’s 2026 campaign","url":"https://www.who.int/campaigns/universal-health-coverage-day/2026"},"sources":[{"label":"World Health Organization: UHC Day 2026","url":"https://www.who.int/campaigns/universal-health-coverage-day/2026","dateEvidence":true}]},"2026-12-14:roast-chestnuts-day":{"id":"2026-12-14:roast-chestnuts-day","date":"2026-12-14","verification":"independent-calendar","summary":"A warm paper bag and a winter smell that feels like a film scene. 🌰 Roast Chestnuts Day is an informal seasonal food occasion for enjoying edible chestnuts, either as a simple snack or in a comforting dish.","sections":[{"heading":"The date on the calendar","body":"Independent celebration calendars list Roast Chestnuts Day on 14 December. There is no clearly established founding organiser, so it is best understood as a playful food prompt rather than a historic anniversary. The appeal is seasonal: a small ritual that makes an ordinary December evening feel a little more festive."},{"heading":"Bring the street-stall feeling home","body":"Buy chestnuts sold for cooking and follow a proper roasting guide, including how to prepare the shells. Good Food’s linked recipe includes oven and air-fryer methods. If a whole tray sounds like too much, choose a chestnut dish or share a portion with someone; the occasion is about enjoying the flavour, not buying special equipment."}],"activity":{"text":"Try a small batch using the linked recipe and serve them while settling into a favourite winter film.","label":"Try the roast chestnuts recipe","url":"https://www.bbcgoodfood.com/recipes/roast-chestnuts"},"sources":[{"label":"National Today: Roast Chestnuts Day","url":"https://nationaltoday.com/roast-chestnuts-day/","dateEvidence":true},{"label":"Good Food: roast chestnuts","url":"https://www.bbcgoodfood.com/recipes/roast-chestnuts","dateEvidence":false}]},"2026-12-16":{"id":"2026-12-16","date":"2026-12-16","verification":"independent-calendar","summary":"Today’s very scientific question: would this be better dipped in chocolate? 🍓 Chocolate Covered Anything Day is an informal US food observance for experimenting with familiar treats, from fruit and biscuits to something with a salty crunch.","sections":[{"heading":"An unofficial excuse to experiment","body":"National Day Calendar places the celebration on 16 December and says its origin is not established. It encourages dipping and drizzling rather than celebrating one particular product. Despite the name, “anything” is playful exaggeration: the idea is to choose foods you already enjoy and discover a pleasing new combination."},{"heading":"Make a miniature tasting tray","body":"Pick a few contrasting foods and make a small selection instead of one enormous batch. You might compare something crisp, something soft and a piece of fruit. The linked chocolate-dipped strawberries recipe offers a straightforward starting point. Give each combination a ridiculous tasting note and decide which deserves a return appearance."}],"activity":{"text":"Make chocolate-dipped strawberries or a three-item tasting tray, then vote for the unexpectedly good combination.","label":"Try chocolate-dipped strawberries","url":"https://www.bbcgoodfood.com/recipes/chocolate-dipped-strawberries"},"sources":[{"label":"National Day Calendar: Chocolate-Covered Anything Day","url":"https://nationaldaycalendar.com/celebrations/national-chocolate-covered-anything-day-december-16","dateEvidence":true},{"label":"Good Food: chocolate-dipped strawberries","url":"https://www.bbcgoodfood.com/recipes/chocolate-dipped-strawberries","dateEvidence":false}]},"2026-12-17:national-re-gifting-day":{"id":"2026-12-17:national-re-gifting-day","date":"2026-12-24","verification":"independent-calendar","summary":"An unused present can have a much better second destination than the back of a cupboard. 🎁 Re-Gifting Day encourages thoughtful gift reuse, with a useful reminder that a good match matters more than simply passing something unwanted along.","sections":[{"heading":"A date with conflicting listings","body":"Some calendars use the third Thursday of December, which is 17 December in 2026. National Day Calendar and Checkiday explicitly list 24 December, following “the Thursday before Christmas”, a rule also used by Money Management International. The date is not universally standardised; this December 24 observance follows the latter rule."},{"heading":"Thoughtful, rather than thoughtless","body":"The day grew from conversations about holiday spending and office gift exchanges. The helpful question is whether the recipient would genuinely enjoy the item. Choose something new and in good condition, check for personal notes or names, and avoid using a gift exchange as a way to unload broken, unsuitable or sentimental belongings."}],"activity":{"text":"Find one unused gift and name a person who would genuinely enjoy it; if nobody fits, leave it out.","label":"Explore the regifting background","url":"https://www.moneymanagement.org/blog/happy-national-regifting-day"},"sources":[{"label":"National Day Calendar: 24 December 2026","url":"https://nationaldaycalendar.com/celebrations/national-re-gifting-day-thursday-before-christmas/","dateEvidence":true},{"label":"Checkiday: 24 December 2026","url":"https://www.checkiday.com/a86bbe475ba34a43483fdab24c2e90cd/national-regifting-day","dateEvidence":true},{"label":"Money Management International: Thursday before Christmas","url":"https://www.moneymanagement.org/blog/happy-national-regifting-day","dateEvidence":true},{"label":"Alternative third-Thursday calendar: 17 December","url":"https://www.thereisadayforthat.com/holidays/usa/national-re-gifting-day","dateEvidence":true}],"researchNote":"Corrected 17 Dec to 24 Dec using NDC/Checkiday explicit 2026 dates and the Thursday-before-Christmas wording in MMI’s own 2008 article. Sources disagree: some calendars and an older MMI 2013 press-release listing use third Thursday (17 Dec). The popup explicitly explains this uncertainty."},"2026-12-19:national-emo-day":{"id":"2026-12-19:national-emo-day","date":"2026-12-19","verification":"independent-calendar","summary":"Bring back the chorus you still know by heart. 🖤 National Emo Day is an informal celebration of emo music and the communities around it, making 19 December a convenient excuse to revisit an emotionally oversized playlist.","sections":[{"heading":"Music before the haircut","body":"Emo developed from emotional hardcore and punk scenes before its later mainstream visibility in the 2000s. The label has covered changing sounds and communities, so the music is more varied than a single outfit or stereotype suggests. Independent calendars place the appreciation day on 19 December, but its precise founding origin is uncertain."},{"heading":"Listen across the eras","body":"Start with a track that meant something to you, then try one from a different period or a band you missed. Notice what carries the feeling: the words, the vocal delivery, a sudden change in volume or the crowd singing along. You can enjoy the nostalgia without having to defend every teenage fashion decision."}],"activity":{"text":"Make a five-song playlist: two old favourites, two unfamiliar tracks and one chorus you would absolutely shout along to.","label":"Explore the music-day background","url":"https://www.awarenessdays.com/awareness-days-calendar/national-emo-day/"},"sources":[{"label":"Awareness Days: National Emo Day 2026","url":"https://www.awarenessdays.com/awareness-days-calendar/national-emo-day/","dateEvidence":true}]},"2026-12-21":{"id":"2026-12-21","date":"2026-12-21","verification":"organiser","summary":"The Northern Hemisphere reaches its shortest stretch of daylight, while the Southern Hemisphere turns towards its longest day. 🌙 The December solstice is an astronomical turning point, offering a moment to notice the light and the season around you.","sections":[{"heading":"The 2026 moment","body":"Royal Observatory Greenwich gives the December solstice as 21 December 2026 at 20:50 GMT, which is also 20:50 UTC. It is one shared astronomical moment, although its local clock time depends on where you are. In the Northern Hemisphere it is the winter solstice; south of the equator it is the summer solstice."},{"heading":"Why the Sun seems to pause","body":"Earth’s tilt changes how high the Sun appears and how much daylight different places receive across the year. Around a solstice, the Sun reaches an extreme in its apparent north-south path before the pattern reverses. The term comes from a Latin expression meaning the Sun stands still, describing that apparent turning rather than the Sun literally stopping."}],"activity":{"text":"Notice your local sunrise and sunset, then take one photograph that captures what this season’s light feels like.","label":"Explore the Observatory’s solstice guide","url":"https://www.rmg.co.uk/stories/time/summer-solstice"},"sources":[{"label":"Royal Observatory Greenwich: 2026 solstice table and explanation","url":"https://www.rmg.co.uk/stories/time/summer-solstice","dateEvidence":true}],"researchNote":"Northern Hemisphere winter; Southern Hemisphere summer. The source gives 21 December 2026 20:50 GMT/UTC; local clock times differ."},"2026-12-22:national-mathematics-day":{"id":"2026-12-22:national-mathematics-day","date":"2026-12-22","verification":"organiser","summary":"Patterns, puzzles and a mathematician whose ideas still inspire new work. 🔢 India’s National Mathematics Day marks Srinivasa Ramanujan’s birthday on 22 December, inviting people to discover a subject that reaches far beyond classroom arithmetic.","sections":[{"heading":"Remembering Ramanujan","body":"Ramanujan was born on 22 December 1887 in Erode, Tamil Nadu. The Indian government’s science portal describes his contributions to number theory and the thousands of identities and equations he developed during a short life. His results continue to motivate mathematical research, making the birthday an occasion to explore both a person and their ideas."},{"heading":"Give a puzzle some room","body":"You do not need advanced mathematics to enjoy the day. Choose one question with several possible approaches, such as finding different ways to make a target number, and compare methods with someone else. Write down your working, including an attempt that fails. Discovering why a pattern does not work can be as satisfying as spotting one that does."}],"activity":{"text":"Find three different ways to make 24 using numbers and operations, then compare your most surprising solution with a friend.","label":"Discover Ramanujan’s story","url":"https://www.indiascienceandtechnology.gov.in/listingpage/india-celebrating-national-mathematics-day"},"sources":[{"label":"India Science, Technology and Innovation portal: National Mathematics Day","url":"https://www.indiascienceandtechnology.gov.in/listingpage/india-celebrating-national-mathematics-day","dateEvidence":true}]},"2026-12-24":{"id":"2026-12-24","date":"2026-12-24","verification":"organiser","summary":"The last preparations, a familiar song and the feeling that tomorrow is nearly here. 🎄 Christmas Eve is 24 December in Western Christian calendars, marked through religious services, family traditions and many personal ways of spending the evening.","sections":[{"heading":"An evening of anticipation","body":"Many Christian churches hold services late on Christmas Eve, including Midnight Mass, which can continue into Christmas Day. The Church of England describes it as a service with carols, a short talk and Holy Communion. Lessons and Carols is a different format, alternating Bible readings with music to tell the Christmas story."},{"heading":"Make room for your own evening","body":"Not everyone celebrates Christmas or spends the date with family, and there is no single correct version of the evening. Some people attend a service, others share food, work a shift or enjoy a quiet night. If you would like an outing, check local service or event times rather than assuming “midnight” describes when every gathering begins."}],"activity":{"text":"Choose one small tradition for tonight: a song, a call, a favourite film or a local carol service.","label":"Explore Christmas Eve service traditions","url":"https://www.churchofengland.org/faith/advent-and-christmas/what-expect-church-christmas"},"sources":[{"label":"Church of England: Christmas services and Christmas Eve","url":"https://www.churchofengland.org/faith/advent-and-christmas/what-expect-church-christmas","dateEvidence":true}]},"2026-12-25:a-phabet-day-no-l-day":{"id":"2026-12-25:a-phabet-day-no-l-day","date":"2026-12-25","verification":"independent-calendar","summary":"No L? Noël. Yes, the entire occasion really is a pun. 🔠 A’Phabet Day turns 25 December into a playful word challenge: try saying or writing something without using the letter L, and see how inventive you become.","sections":[{"heading":"A tiny joke with a calendar date","body":"National Day Calendar and other independent listings place No “L” Day on 25 December. The connection is the sound of “Noel”, associated with Christmas. This is an informal wordplay observance, not a separate public holiday, and you do not need to celebrate Christmas to enjoy the language game."},{"heading":"Try a small constraint","body":"Start with one sentence rather than promising to change how you speak for the whole day. “Have a merry day!” already passes the test. Then try describing your breakfast, writing a tiny poem or explaining a film plot without L. The awkward workarounds are the point, and the challenge works best when nobody is taking it too seriously."}],"activity":{"text":"Write a three-sentence message without the letter L, then ask someone to spot what is unusual about it.","label":"Explore the No L word game","url":"https://nationaldaycalendar.com/celebrations/aphabet-day-or-no-l-day-december-25"},"sources":[{"label":"National Day Calendar: A’Phabet Day / No L Day","url":"https://nationaldaycalendar.com/celebrations/aphabet-day-or-no-l-day-december-25","dateEvidence":true}]},"2026-12-27":{"id":"2026-12-27","date":"2026-12-27","verification":"independent-calendar","summary":"A dense little slice with a surprisingly divided fan club. 🍒 National Fruitcake Day is an informal US food occasion for the dried-fruit-filled bake that appears around the festive season, whether you love it or remain politely unconvinced.","sections":[{"heading":"The calendar entry","body":"National Day Calendar lists 27 December as National Fruitcake Day and says its founding origin is unknown. The observance celebrates the food rather than establishing a single authentic recipe. Fruitcakes differ in fruit, nuts, spices, decoration and other ingredients, so one disappointing example need not settle the question forever."},{"heading":"Give it a fair tasting","body":"Try a small slice and notice the balance between cake and fruit, rather than judging it only by the festive wrapping. If making one, read the recipe’s timing before starting; some styles are a longer project than a quick sponge. The linked apple fruit cake offers a specific alternative to explore, or you can compare family recipes and the stories attached to them."}],"activity":{"text":"Share a small fruitcake tasting or try the apple fruit cake recipe and decide what you would change next time.","label":"Try an apple fruit cake","url":"https://www.bbcgoodfood.com/recipes/easy-apple-fruit-cake"},"sources":[{"label":"National Day Calendar: National Fruitcake Day","url":"https://nationaldaycalendar.com/celebrations/national-fruitcake-day-december-27","dateEvidence":true},{"label":"Good Food: easy apple fruit cake","url":"https://www.bbcgoodfood.com/recipes/easy-apple-fruit-cake","dateEvidence":false}]},"2026-12-28:national-call-a-friend-day":{"id":"2026-12-28:national-call-a-friend-day","date":"2026-12-28","verification":"independent-calendar","summary":"“We should catch up” can become an actual conversation today. 📞 This informal observance on 28 December encourages people to reconnect with a friend, especially someone whose name keeps appearing on the list of people they mean to contact.","sections":[{"heading":"A deliberately simple occasion","body":"Independent calendars list Call a Friend Day on 28 December. It is not an official public holiday and its founding origin is not clearly documented. Its usefulness is in the prompt: a date in a busy season that invites you to make room for a relationship without organising an elaborate occasion."},{"heading":"Make the contact welcome","body":"Send a quick message first if you do not know whether the person is free, especially across time zones. A voice call is one option, but a video call, voice note or another accessible form of conversation can serve the same purpose. Ask a question that invites a real answer, then leave enough quiet space to listen."}],"activity":{"text":"Message a friend with a specific invitation: “Would you be free for a ten-minute catch-up this evening?”","label":"About Call a Friend Day","url":"https://nationaltoday.com/national-call-a-friend-day/"},"sources":[{"label":"National Today: Call a Friend Day","url":"https://nationaltoday.com/national-call-a-friend-day/","dateEvidence":true},{"label":"Checkiday: 28 December 2026 observances","url":"https://www.checkiday.com/12/28/2026","dateEvidence":true}]},"2026-12-30:national-resolution-planning-day":{"id":"2026-12-30:national-resolution-planning-day","date":"2026-12-30","verification":"independent-calendar","summary":"Before the New Year starts making grand demands, give one idea a practical shape. 📝 National Resolution Planning Day is an informal prompt to think about next year’s intentions and turn a vague ambition into a manageable first step.","sections":[{"heading":"A planning date, not a deadline","body":"Independent calendars place the observance on 30 December. It is not a public holiday or a requirement to reinvent your life before January. Think of it as an optional pause between the year’s experiences and whatever you would like to try next, without needing a long list of promises."},{"heading":"Make one plan usable","body":"Choose something that matters to you, describe the smallest action that counts, and decide when it could happen. “Read more” might become “read two pages after making my evening tea”. Add a simple backup for a busy day and a way to notice progress. A plan is allowed to change when you learn what fits your actual life."}],"activity":{"text":"Write one small action for next year, the moment you will try it, and a simpler version for difficult days.","label":"Explore the planning-day prompt","url":"https://nationaltoday.com/national-resolution-planning-day/"},"sources":[{"label":"National Today: Resolution Planning Day","url":"https://nationaltoday.com/national-resolution-planning-day/","dateEvidence":true},{"label":"Parade: December observances","url":"https://parade.com/living/december-holidays-observances","dateEvidence":true}]},"2026-11-01:all-saints-day":{"id":"2026-11-01:all-saints-day","date":"2026-11-01","verification":"organiser","summary":"All Saints’ Day honours the saints of Christian tradition, including lives never recorded in a calendar. It is a day of worship, remembrance and hope, with customs that differ between churches and countries.","sections":[{"heading":"What the day means","body":"In the Catholic calendar, 1 November is the Solemnity of All Saints. The celebration includes both named saints and the many people believed to share in eternal life without public recognition. It looks towards the example of holy lives rather than being a festival about frightening spirits or a second Halloween."},{"heading":"A tradition with a long history","body":"The feast developed over centuries, including the dedication of the Pantheon in Rome to Christian worship in the seventh century. November observances later spread more widely. Some Christian traditions use a different date, so the calendar here follows the Western 1 November observance. Reading about one local custom is a good way to see how a shared feast takes different forms."}],"activity":{"text":"Choose one saint associated with a place you know and discover the story behind their name.","label":"Explore the feast","url":"https://www.vaticanstate.va/en/component/content/article/november-1-all-saints-day.html"},"sources":[{"label":"Vatican City: All Saints’ Day","url":"https://www.vaticanstate.va/en/component/content/article/november-1-all-saints-day.html","dateEvidence":true}]},"2026-11-02:colour-the-world-orange-day":{"id":"2026-11-02:colour-the-world-orange-day","date":"2026-11-02","verification":"organiser","summary":"Orange landmarks and orange clothes carry a message today: people living with complex regional pain syndrome deserve understanding. The organiser confirms 2 November for the 2026 Color The World Orange awareness campaign.","sections":[{"heading":"Why orange appears","body":"Color The World Orange is an independent awareness initiative focused on complex regional pain syndrome, also called CRPS or RSD. Its shared colour makes an often unseen condition more visible. Supporters include individuals, community groups and landmarks whose lighting creates a conversation about people’s experiences of persistent pain."},{"heading":"One date, many local lightings","body":"The main day falls on the first Monday in November, which is 2 November in 2026. Individual building lightings can happen on neighbouring dates and may change, so a local listing matters more than assuming every orange landmark switches on together. Participation can be quiet and personal: listening respectfully is as valuable as a photograph of a lit-up skyline."}],"activity":{"text":"Look at the organiser’s lighting list, or wear something orange and share the reason without making assumptions about someone’s health.","label":"See the lighting list","url":"https://www.colortheworldorange.com/celebrate"},"sources":[{"label":"Color The World Orange: 2026 celebration","url":"https://www.colortheworldorange.com/celebrate","dateEvidence":true}],"title":"Color The World Orange Day"},"2026-11-04:national-stress-awareness-day":{"id":"2026-11-04:national-stress-awareness-day","date":"2026-11-04","verification":"organiser","summary":"Stress Awareness Day opens a conversation about pressures people face and the changes that could help. In 2026 it falls on Wednesday 4 November, during International Stress Awareness Week.","sections":[{"heading":"More than a reminder to relax","body":"The International Stress Management Association uses the day to improve understanding of stress and wellbeing. Its 2026 programme includes a summit about making working life more human. Workload, communication, support and organisational culture belong in this conversation alongside individual coping habits; people should not be expected to solve every pressure on their own."},{"heading":"Make a useful conversation possible","body":"A practical check-in is more specific than asking someone whether they are stressed. Ask which part of their day is making things harder, listen without competing stories, and consider what can actually change. In a workplace, that might mean clearer priorities or a discussion about demands. The day is an awareness occasion, not a diagnosis or a promise that one activity fixes a difficult situation."}],"activity":{"text":"Ask a colleague or friend which pressure they would most like help with, and agree one realistic change together.","label":"Explore the campaign resources","url":"https://www.matesinmind.org/training-and-resources/stress-awareness-week-november"},"sources":[{"label":"ISMA: Stress Awareness Day 2026","url":"https://isma.org.uk/node/24721","dateEvidence":true},{"label":"Mates in Mind: November awareness resources","url":"https://www.matesinmind.org/training-and-resources/stress-awareness-week-november","dateEvidence":true}]},"2026-11-05:world-tsunami-awareness-day":{"id":"2026-11-05:world-tsunami-awareness-day","date":"2026-11-05","verification":"organiser","summary":"World Tsunami Awareness Day highlights the value of warning systems, education and preparedness. The United Nations marks 5 November each year, turning a frightening hazard into a conversation about informed communities.","sections":[{"heading":"Why 5 November?","body":"The date recalls a Japanese account from 1854 in which a villager set fire to rice sheaves to warn neighbours about an approaching tsunami. The UN established the observance in 2015. The story emphasises a lasting principle: warnings matter when people understand them and know what action to take."},{"heading":"Preparedness is a shared task","body":"A useful warning system connects science, communication and communities. Plans also need to work for people with different languages, mobility and access needs. Today is a chance to learn how coastal places communicate risk, rather than treating every unusual wave as an emergency. For any real situation, local emergency authorities provide the instructions and evacuation information that apply to that location."}],"activity":{"text":"If you visit a coastal area, take a moment to locate its official warning information and learn what the local signs mean.","label":"Explore the UN observance","url":"https://www.un.org/en/observances/world-tsunami-awareness-day"},"sources":[{"label":"UN resolution establishing 5 November","url":"https://mandates.un.org/mandate/A/RES/70/203","dateEvidence":true},{"label":"United Nations: tsunami awareness","url":"https://www.un.org/en/observances/world-tsunami-awareness-day","dateEvidence":true}]},"2026-11-06:fountain-pen-day":{"id":"2026-11-06:fountain-pen-day","date":"2026-11-06","verification":"organiser","summary":"A tiny ink reservoir, an expressive nib and a very satisfying line. ✒️ Fountain Pen Day celebrates handwriting and the people who enjoy it; the organiser confirms Friday 6 November for the 2026 edition.","sections":[{"heading":"A day for putting pen to paper","body":"Fountain Pen Day takes place on the first Friday in November. It invites people to use, share and talk about fountain pens, whether they treasure a vintage model or have a simple everyday pen. The community includes pen clubs, shows, specialist shops and people who simply enjoy writing a card by hand."},{"heading":"You do not need a new collection","body":"Try writing a short note with a pen you already own, noticing the shape of the letters and the feel of the paper. A fountain pen’s line can vary with its nib and ink, which is part of its appeal. The point is enjoying the process, not producing perfect calligraphy or turning a pleasant hobby into a shopping requirement."}],"activity":{"text":"Write a postcard or a three-line thank-you note, then give it to someone who would enjoy receiving real handwriting.","label":"Find the pen community","url":"https://www.fountainpenday.com/"},"sources":[{"label":"Fountain Pen Day organiser: 2026 date","url":"https://www.fountainpenday.com/","dateEvidence":true}]},"2026-11-07:kekri":{"id":"2026-11-07:kekri","date":"2026-11-07","verification":"organiser","summary":"Kekri is Finland’s harvest-season celebration: good food, stories and a pause after the work is done. 🍂 Its timing varies between communities; 7 November is one contemporary celebration date, not a fixed national day.","sections":[{"heading":"A season rather than one date","body":"Traditionally, Kekri happened after a household finished its autumn work. That made its date flexible, with celebrations across the autumn rather than a single nationwide anniversary. Food and hospitality were central: a full table recognised the completed harvest and welcomed both living guests and, in traditional belief, visiting ancestors."},{"heading":"A wonderfully unruly celebration","body":"Old customs included costumed visitors, storytelling, singing and the kekri goat, whose disguise could involve an inside-out fur coat and improvised horns. Modern festivals bring food, markets, art and gatherings into this tradition. There are events on 7 November 2026, but other Finnish celebrations take place in September, October and early November. The calendar date here is a seasonal invitation to explore it."}],"activity":{"text":"Make a small seasonal supper and ask everyone to bring a story from their year, rather than treating it as an exact national holiday.","label":"Discover Kekri traditions","url":"https://kekri.fi/in-english/"},"sources":[{"label":"Finnish Kekri campaign: traditions and season","url":"https://kekri.fi/in-english/","dateEvidence":false},{"label":"Lokal: Kekri event on 7 November 2026","url":"https://lokalhelsinki.com/product/kekri/","dateEvidence":true}],"researchNote":"Kekri has no universal fixed date. Retain 7 November only as a clearly labelled seasonal feature; specific Finnish events occur then, while other 2026 Kekri events occur earlier."},"2026-11-09:go-to-an-art-museum-day":{"id":"2026-11-09:go-to-an-art-museum-day","date":"2026-11-09","verification":"independent-calendar","summary":"An invitation to spend a little time with art, even if you do not know the artist’s name. 🖼️ Independent calendars list 9 November as Go to an Art Museum Day, an informal cultural occasion.","sections":[{"heading":"No expert knowledge required","body":"This is an unofficial observance rather than a public holiday or a day with a single international organiser. Its useful idea is simple: make room for looking at art. A small local gallery counts just as much as a famous museum, and one painting can be enough for a worthwhile visit."},{"heading":"Try looking before reading","body":"Choose a work and give it a minute before reading the label. Notice a colour, a gesture or a detail that draws your eye, then see what the museum tells you about it. If a visit is not possible, a museum’s own online collection offers a free alternative. You can compare impressions with a friend without needing to agree on what the painting means."}],"activity":{"text":"Pick one painting from the National Gallery’s online collection and describe three things you notice before checking its story.","label":"Explore a museum collection","url":"https://www.nationalgallery.org.uk/paintings/must-sees"},"sources":[{"label":"AnydayGuide: 9 November listing","url":"https://anydayguide.com/calendar/4340","dateEvidence":true},{"label":"National Gallery: explore the collection","url":"https://www.nationalgallery.org.uk/paintings/must-sees","dateEvidence":false}]},"2026-11-10:sesame-street-day":{"id":"2026-11-10:sesame-street-day","date":"2026-11-10","verification":"organiser","summary":"Sunny days, familiar monsters and lessons that arrive disguised as fun. Sesame Street Day marks the programme’s 10 November 1969 television debut and the lasting idea that learning can belong in everyone’s neighbourhood.","sections":[{"heading":"A television anniversary with a city behind it","body":"New York City proclaimed 10 November 2009 Sesame Street Day for the series’ fortieth anniversary. The programme’s home city also marked the occasion with a temporary street sign near Sesame Workshop. The anniversary has continued to be recognised by the show’s own organisation, including its 2025 season launch."},{"heading":"More than letters and numbers","body":"Sesame Workshop is a nonprofit educational organisation, and the programme combines music, comedy, puppets and human characters. Its stories have also made room for friendship, emotions and everyday difficulties. A good way to revisit it is to notice how a short, playful scene communicates something clearly without sounding like a lesson. You might remember the song before you remember the skill it taught."}],"activity":{"text":"Share a favourite Sesame Street song with someone, or explore a current resource together and notice what it teaches through play.","label":"Visit Sesame Workshop","url":"https://sesameworkshop.org/"},"sources":[{"label":"New York City: Sesame Street Day proclamation","url":"https://www.nyc.gov/html/film/html/news_2009/110109_sesame_street_anniversary.shtml","dateEvidence":true},{"label":"Sesame Workshop: anniversary recognition","url":"https://sesameworkshop.org/about-us/press-room/sesame-streets-new-reimagined-season-launches-monday-november-10-on-netflix-and-pbs-kids/","dateEvidence":true}]},"2026-11-11:singles-day":{"id":"2026-11-11:singles-day","date":"2026-11-11","verification":"independent-calendar","summary":"Four ones, one very recognisable date. Singles’ Day began as a celebration of single life in China and grew into a major shopping event. Enjoying your own company does not require buying anything. ✨","sections":[{"heading":"Why 11.11?","body":"The repeated ones in 11 November are associated with people standing alone, which gives the day its memorable visual identity. It is also called Double 11. Its celebration of single life became closely linked with large online sales, and retailers in other countries now borrow the date for promotions."},{"heading":"A celebration you can define yourself","body":"Singles’ Day can be a chance to appreciate friendships, independence or an evening spent doing precisely what you enjoy. Relationship status is not a measure of how complete a life is. If the shopping side interests you, decide what you genuinely want before browsing and compare ordinary prices as well as sale labels. There is no need to turn an informal celebration into an obligation to spend."}],"activity":{"text":"Plan a small solo treat using something you already have: a favourite film, a meal you love or an uninterrupted chapter.","label":"Explore the date’s background","url":"https://www.timeanddate.com/holidays/world/singles-day"},"sources":[{"label":"timeanddate: Singles’ Day date and history","url":"https://www.timeanddate.com/holidays/world/singles-day","dateEvidence":true}]},"2026-11-12:national-pizza-with-the-works-except-anchovies-day":{"id":"2026-11-12:national-pizza-with-the-works-except-anchovies-day","date":"2026-11-12","verification":"independent-calendar","summary":"A delightfully specific pizza occasion: all your favourite toppings, with one named exception. 🍕 Independent calendars mark 12 November for this informal US food day; your own slice can follow whichever topping rules you like.","sections":[{"heading":"An unofficial invitation to customise","body":"National Pizza with the Works Except Anchovies Day appears in independent celebration calendars. It is not an Italian national holiday or an official rule about pizza. The extravagant name is the joke: the pleasure comes from choosing a generous mixture of toppings while leaving out the little fish that divide opinions."},{"heading":"What belongs on your pizza?","body":"Treat the day as a chance to create a combination with friends rather than piling on every ingredient in the fridge. Try balancing a vegetable, something savoury and a finishing herb, or make separate halves for different tastes. Anchovy enthusiasts are allowed to opt out of the joke. A homemade base, a shop-bought one or a favourite local pizzeria can all supply the starting point."}],"activity":{"text":"Ask each person to nominate one topping and build a shared pizza with a different combination on each half.","label":"Explore the food-day listing","url":"https://www.nationaldayarchives.com/day/national-pizza-with-the-works-except-anchovies-day/"},"sources":[{"label":"National Day Archives: 12 November listing","url":"https://www.nationaldayarchives.com/day/national-pizza-with-the-works-except-anchovies-day/","dateEvidence":true}]},"2026-11-14:world-diabetes-day":{"id":"2026-11-14:world-diabetes-day","date":"2026-11-14","verification":"organiser","summary":"World Diabetes Day brings attention to people living with diabetes and the care, information and support they need. Led by the International Diabetes Federation, it is observed around the world on 14 November.","sections":[{"heading":"A day for understanding, not assumptions","body":"The campaign makes diabetes visible through education, advocacy and community events. Diabetes includes different conditions and people’s experiences are not interchangeable. Awareness is more useful when it challenges stigma and makes room for people to describe their own lives, rather than making assumptions about someone’s food, body or personal choices."},{"heading":"Use trustworthy information","body":"The International Diabetes Federation provides resources for the public and for people involved in diabetes care. Reading a reliable explanation can help distinguish the different types of diabetes and the barriers people face in accessing support. This calendar is introducing an awareness day, not offering diagnosis or treatment advice. A respectful conversation can begin with asking what someone wishes others understood about living with the condition."}],"activity":{"text":"Read one IDF resource about diabetes, then share an accurate point that challenges a common assumption rather than commenting on someone’s choices.","label":"Explore IDF resources","url":"https://idf.org/"},"sources":[{"label":"International Diabetes Federation: World Diabetes Day","url":"https://idf.org/","dateEvidence":true}]},"2026-11-15:steve-irwin-day":{"id":"2026-11-15:steve-irwin-day","date":"2026-11-15","verification":"organiser","summary":"Khaki clothes and a very big enthusiasm for wildlife: Steve Irwin Day celebrates the conservationist’s life and legacy. 🐊 Australia Zoo marks 15 November, with an invitation to care about wildlife wherever you live.","sections":[{"heading":"Why this date?","body":"Australia Zoo explains that 15 November was chosen as the birthday of Harriet, Steve Irwin’s favourite Galápagos tortoise. The day celebrates the interests associated with his work: family, fun, wildlife and conservation. Its focus is continuing that work rather than simply revisiting famous television moments."},{"heading":"Conservation close to home","body":"Australia Zoo and Wildlife Warriors connect the day with conservation projects and their wildlife hospital. You do not need to travel to Queensland to take part in the underlying idea. Learning about a local species, giving animals space and finding out what a reputable conservation group actually does are useful starting points. Wildlife is most interesting when its needs come before the photograph or the encounter."}],"activity":{"text":"Choose one animal native to where you live and find out which local habitat or conservation project helps it survive.","label":"Explore Steve Irwin Day","url":"https://australiazoo.com.au/event/steve-irwin-day/"},"sources":[{"label":"Australia Zoo: Steve Irwin Day","url":"https://australiazoo.com.au/event/steve-irwin-day/","dateEvidence":true},{"label":"Australia Zoo: event calendar and Harriet connection","url":"https://australiazoo.com.au/visit-us/event-calendar/","dateEvidence":true}]},"2026-11-16:national-fast-food-day":{"id":"2026-11-16:national-fast-food-day","date":"2026-11-16","verification":"independent-calendar","summary":"Burgers, tacos, fries or the dependable thing you order when you are in a hurry. 🍟 National Fast Food Day is an informal US food-calendar occasion on 16 November, celebrating the convenience-food counter.","sections":[{"heading":"Speed is the defining ingredient","body":"Fast food refers to meals prepared and served quickly, often packaged for eating elsewhere. The modern industry became closely associated with American car culture, drive-ins and drive-through service, but quick prepared food has taken many forms. Today’s menus include far more than the hamburger-and-fries combination that often comes to mind."},{"heading":"Make it a small food adventure","body":"You could compare favourite orders with a friend, try an independent takeaway or build your own version of a familiar fast-food meal. The origin of this particular food day is not well established, so there is no official ceremony or required purchase. If you do order, choose something you actually want and appreciate the people preparing and serving it on a busy shift."}],"activity":{"text":"Recreate your favourite takeaway sandwich at home, or try one unfamiliar item from a local independent takeaway.","label":"Explore the food-day background","url":"https://nationaldaycalendar.com/celebrations/national-fast-food-day-november-16"},"sources":[{"label":"National Day Calendar: 16 November","url":"https://nationaldaycalendar.com/celebrations/national-fast-food-day-november-16","dateEvidence":true}]},"2026-11-17:national-baklava-day":{"id":"2026-11-17:national-baklava-day","date":"2026-11-17","verification":"independent-calendar","summary":"Crisp filo, chopped nuts and syrup finding its way between the layers. 🍯 National Baklava Day is an informal US food occasion on 17 November, offering a good excuse to explore a pastry shared across many cuisines.","sections":[{"heading":"One name, many local versions","body":"Baklava is made in a wide range of regional styles, with different nuts, shapes and flavourings. Pistachios and walnuts are familiar fillings, while syrups may feature honey, citrus or fragrant spices. Its history crosses borders, so assigning the entire pastry tradition to one modern country would miss much of the story."},{"heading":"Enjoy the layers","body":"Making baklava rewards patience: thin pastry sheets, a nut filling and a syrup finish create its contrasting textures. A bakery tasting is an equally practical way to notice the differences between varieties. The food day’s own origins are not firmly documented, but the pastry needs no invented founding legend. If you share it, check which nuts and other ingredients are in the version you choose."}],"activity":{"text":"Try two bakery varieties side by side, or make the linked nutty baklava and share the finished pieces with friends.","label":"Try a baklava recipe","url":"https://www.bbcgoodfood.com/recipes/nutty-baklava"},"sources":[{"label":"National Day Calendar: 17 November","url":"https://nationaldaycalendar.com/celebrations/national-baklava-day-november-17","dateEvidence":true},{"label":"Good Food: nutty baklava recipe","url":"https://www.bbcgoodfood.com/recipes/nutty-baklava","dateEvidence":false}]},"2026-11-19:international-men-s-day":{"id":"2026-11-19:international-men-s-day","date":"2026-11-19","verification":"organiser","summary":"International Men’s Day celebrates positive contributions by men and boys while opening practical conversations about wellbeing, equality and support. The annual 19 November observance welcomes participation from people of all genders.","sections":[{"heading":"Six shared aims","body":"The UK campaign describes six broad pillars: positive role models, men’s contributions, health and wellbeing, addressing disadvantage, improving gender relations and creating a safer world. The focus can include ordinary people who quietly make a difference, rather than only public figures or sporting heroes. The modern international event began in Trinidad and Tobago in 1999."},{"heading":"Turn appreciation into something specific","body":"A useful message tells someone what you appreciate about them: the way they listen, care for family or help a community. The day can also make room for conversations about expectations that make asking for help harder. Different organisations choose different activities, so it is worth checking the actual event and its purpose rather than assuming every campaign has one single theme or viewpoint."}],"activity":{"text":"Thank a man who has made a positive difference in your life, naming the action or quality you appreciate.","label":"Explore the campaign’s aims","url":"https://ukmensday.org.uk/about-imd-uk/the-six-pillars-of-international-mens-day/"},"sources":[{"label":"International Men’s Day UK: date and six pillars","url":"https://ukmensday.org.uk/about-imd-uk/the-six-pillars-of-international-mens-day/","dateEvidence":true}]},"2026-11-20:transgender-day-of-remembrance":{"id":"2026-11-20:transgender-day-of-remembrance","date":"2026-11-20","verification":"organiser","summary":"Transgender Day of Remembrance honours transgender people whose lives have been lost to anti-transgender violence. Marked on 20 November, it is a solemn occasion for remembrance, solidarity and listening to affected communities.","sections":[{"heading":"Where the observance began","body":"Transgender advocate Gwendolyn Ann Smith began the observance in 1999 with a vigil honouring Rita Hester, who had been killed the previous year. It grew into an annual tradition of remembering transgender people lost to violence, with vigils and community gatherings in many places."},{"heading":"Remember people with dignity","body":"Events often include reading names and reflecting on lives as well as on the circumstances of loss. Local transgender organisations can explain how to participate respectfully and what support is useful. This is not an occasion for sensational images or demands that someone share a traumatic experience. Using people’s names and pronouns accurately, listening and supporting work led by the community are practical ways to show care."}],"activity":{"text":"Read GLAAD’s background guide and look for a remembrance event organised by a local transgender or LGBTQ+ community group.","label":"Read the remembrance guide","url":"https://glaad.org/tdor/"},"sources":[{"label":"GLAAD: Transgender Day of Remembrance","url":"https://glaad.org/tdor/","dateEvidence":true}]},"2026-11-21:national-gingerbread-cookie-day":{"id":"2026-11-21:national-gingerbread-cookie-day","date":"2026-11-21","verification":"independent-calendar","summary":"A little ginger, a little spice and a biscuit cutter with ambition. 🍪 National Gingerbread Cookie Day falls on 21 November in informal US food calendars, inviting a first batch before December gets busy.","sections":[{"heading":"A biscuit with plenty of personality","body":"Gingerbread can be cut into people, animals, stars or whatever shape survives the journey from worktop to baking tray. Ginger and other warm spices give it its familiar character, while icing turns a plain biscuit into a miniature art project. This November date concerns cookies; other gingerbread-themed dates appear elsewhere in the year."},{"heading":"Make decorating the main event","body":"Bake or buy plain biscuits, put a few decorations in small bowls and give everyone the same playful challenge: a grumpy star, a very overdressed person or an animal nobody can identify. Let the biscuits cool before decorating and check ingredients before sharing. The food day itself has no firmly documented origin, so the only tradition you need is one you would enjoy repeating."}],"activity":{"text":"Make a small batch of gingerbread biscuits and challenge a friend to decorate the funniest face using only three colours.","label":"Explore gingerbread ideas","url":"https://nationaldaycalendar.com/celebrations/national-gingerbread-cookie-day-november-21/"},"sources":[{"label":"National Day Calendar: 21 November","url":"https://nationaldaycalendar.com/celebrations/national-gingerbread-cookie-day-november-21/","dateEvidence":true}]},"2026-11-22:national-cranberry-relish-day":{"id":"2026-11-22:national-cranberry-relish-day","date":"2026-11-22","verification":"independent-calendar","summary":"Sharp, bright and ready to rescue a rich plate of food: cranberry relish gets an informal US food day on 22 November. 🍊 Try a fresh orange-and-cranberry version instead of leaving the berries in a decorative bowl.","sections":[{"heading":"Relish is not always the cooked sauce","body":"Cranberries appear in many Thanksgiving accompaniments, and family versions vary. A fresh relish can be chopped rather than cooked, keeping a different texture from a smooth or jellied sauce. Ocean Spray’s linked recipe uses cranberries and orange, making it a useful starting point if you have only met cranberry in a jar."},{"heading":"Give it somewhere interesting to go","body":"A small spoonful can add tartness to a sandwich, a plate of leftovers or another savoury dish you already like. Taste the finished relish alongside the food rather than judging it only on its own. The origin of the food holiday is not firmly established, so this is a seasonal cooking prompt rather than a claim that every American family observes it."}],"activity":{"text":"Make a small batch of fresh cranberry-orange relish using the linked recipe, then try it in a savoury sandwich.","label":"Try cranberry-orange relish","url":"https://www.oceanspray.com/recipes/fresh-cranberry-orange-relish"},"sources":[{"label":"National Day Calendar: 22 November","url":"https://nationaldaycalendar.com/celebrations/national-cranberry-relish-day-november-22","dateEvidence":true},{"label":"Ocean Spray: fresh cranberry-orange relish","url":"https://www.oceanspray.com/recipes/fresh-cranberry-orange-relish","dateEvidence":false}]},"2026-11-24:guru-nanak-gurpurab":{"id":"2026-11-24:guru-nanak-gurpurab","date":"2026-11-24","verification":"organiser","summary":"Guru Nanak Gurpurab celebrates the birth of Guru Nanak, the founder of Sikhism. India’s official 2026 holiday calendar lists 24 November; Sikh communities mark the occasion with worship, shared food and service.","sections":[{"heading":"Celebration through prayer and community","body":"Gurpurab programmes can include readings of the Guru Granth Sahib, kirtan or sung hymns, processions and gatherings at a gurdwara. Celebrations may begin before the main birthday date and continue through a programme of events. Local schedules therefore vary, even when a calendar gives one principal observance day."},{"heading":"The meaning of sharing a meal","body":"Langar, the communal meal served at a gurdwara, is part of the celebration’s expression of welcome and equality. Seva means selfless service and can include preparing food, helping with community activities or other useful work. If you are visiting, ask the gurdwara about its programme and visitor guidance. Learning directly from the community keeps the occasion connected to the faith and people who celebrate it."}],"activity":{"text":"Learn how langar and seva work, then ask a local gurdwara about its visitor guidance or community-service opportunities.","label":"Explore Gurpurab traditions","url":"https://dsgmc.in/Sikhism/Gurpurbs"},"sources":[{"label":"Government of India: 2026 holiday date","url":"https://www.cgca.gov.in/ccadl/list-of-holiday","dateEvidence":true},{"label":"Delhi Sikh Gurdwara Management Committee: Gurpurabs","url":"https://dsgmc.in/Sikhism/Gurpurbs","dateEvidence":false}]},"2026-11-25:end-violence-against-women-day":{"id":"2026-11-25:end-violence-against-women-day","date":"2026-11-25","verification":"organiser","summary":"The International Day for the Elimination of Violence against Women calls attention to prevention, safety and justice. The United Nations marks 25 November, opening the annual period of activism that runs through Human Rights Day.","sections":[{"heading":"Why 25 November matters","body":"Women’s rights activists chose this date to remember the Mirabal sisters, political activists murdered in the Dominican Republic in 1960. The UN later formally designated the international day. It connects remembrance with the work of preventing violence and protecting the rights of women and girls."},{"heading":"Support needs to be practical","body":"The campaign emphasises accessible services, accountability and approaches centred on survivors. Violence can take place at home, in public, at work or online, so prevention cannot be reduced to one setting or stereotype. Listening without blame and learning about reliable local organisations are useful starting points. Public awareness should not pressure someone to disclose an experience or treat their story as material for a social-media post."}],"activity":{"text":"Learn what a trusted women’s organisation in your area actually provides, and share its public resources in a considerate way.","label":"Explore the UN background","url":"https://www.un.org/en/observances/ending-violence-against-women-day/background"},"sources":[{"label":"United Nations: date and campaign","url":"https://www.un.org/en/observances/ending-violence-against-women-day","dateEvidence":true},{"label":"United Nations: historical background","url":"https://www.un.org/en/observances/ending-violence-against-women-day/background","dateEvidence":true}],"title":"International Day for the Elimination of Violence against Women"},"2026-11-26:world-sustainable-transport-day":{"id":"2026-11-26:world-sustainable-transport-day","date":"2026-11-26","verification":"organiser","summary":"World Sustainable Transport Day is about journeys that connect people without leaving access, safety or the environment behind. 🚉 The United Nations marks 26 November, with a focus that reaches far beyond choosing a different vehicle.","sections":[{"heading":"Transport is also about opportunity","body":"A useful transport system helps people reach work, education, healthcare and one another. The UN observance recognises that affordability, accessibility and reliable connections are part of sustainability, alongside lower environmental impacts. A service that people cannot use or afford is not solving the whole problem."},{"heading":"Try looking at a familiar journey differently","body":"Consider one route you make often. Is there a realistic walking, wheeling, cycling or public-transport option, or would better connections be needed first? Weather, disability, shift times and local provision all affect the answer. The day can be a chance to learn about transport improvements as well as personal choices, rather than assuming the same solution works for every person or every place."}],"activity":{"text":"Compare the options for one familiar journey and identify one change—personal or local—that would make it easier to travel sustainably.","label":"Explore sustainable transport","url":"https://www.un.org/en/observances/sustainable-transport-day"},"sources":[{"label":"United Nations: World Sustainable Transport Day","url":"https://www.un.org/en/observances/sustainable-transport-day","dateEvidence":true}]},"2026-11-27:national-illustration-day":{"id":"2026-11-27:national-illustration-day","date":"2027-01-22","verification":"organiser","summary":"Illustration is everywhere, from picture books to packaging and maps. 🎨 The organiser has moved National Illustration Day to 22 January 2027, so the old late-November date should no longer be used for this celebration.","sections":[{"heading":"An organiser-announced date change","body":"The Quentin Blake Centre for Illustration first ran National Illustration Day in 2023 and held it on the last Friday of November for three years. Its current announcement says the next celebration will be Friday 22 January 2027. Some independent calendars still show a November date, but the organiser’s update takes priority."},{"heading":"Look at the pictures doing a job","body":"Illustration communicates ideas, tells stories and helps people understand the world. It can be decorative, explanatory, funny or quietly practical. A useful activity for the new date is to collect examples from an ordinary day: a book cover, a food packet, an instructional drawing or an illustrated sign. Notice what the image achieves that words alone would have to explain at greater length."}],"activity":{"text":"Choose an ordinary object and draw it as a character, then save the organiser’s January date if you want to join the celebration.","label":"See the organiser’s update","url":"https://qbcentre.org.uk/national-illustration-day"},"sources":[{"label":"Quentin Blake Centre: announced move to January 2027","url":"https://qbcentre.org.uk/national-illustration-day","dateEvidence":true}],"researchNote":"Corrected from 27 November 2026. Organiser explicitly moved the next National Illustration Day to 22 January 2027 after three November editions; omit from the November–December 2026 calendar."},"2026-11-29:first-sunday-of-advent":{"id":"2026-11-29:first-sunday-of-advent","date":"2026-11-29","verification":"organiser","summary":"The first Sunday of Advent begins a season of expectation before Christmas in many Western Christian churches. In 2026 it falls on 29 November, with local traditions of prayer, candles, music and reflection.","sections":[{"heading":"The beginning of a church season","body":"Advent does not begin on 1 December every year. Its first Sunday moves with the calendar, and in 2026 church calendars identify 29 November as the starting point. The season prepares for Christmas and begins a new liturgical year in these traditions. Other Christian communities may follow different calendars and customs."},{"heading":"A slower way to notice the season","body":"Many people associate Advent with a wreath and candles, while churches may offer readings, music or acts of service. An Advent calendar is only one modern expression of the wider season. If you are exploring from outside the tradition, a service programme or a short explanation from a church can provide context without requiring you to share the belief. Local details matter more than assuming every household celebrates in the same way."}],"activity":{"text":"Look up a local Advent concert or read the day’s church-calendar explanation to see what the season means to those observing it.","label":"Explore the 2026 Advent date","url":"https://www.vaticannews.va/en/word-of-the-day/2026/11/29.html"},"sources":[{"label":"Vatican News: First Sunday of Advent 2026","url":"https://www.vaticannews.va/en/word-of-the-day/2026/11/29.html","dateEvidence":true},{"label":"Catholic Bishops’ Conference: 2026 calendar","url":"https://www.liturgyoffice.org.uk/Calendar/2026/Calendar-2026.pdf","dateEvidence":true}]},"2026-11-30:national-computer-security-day":{"id":"2026-11-30:national-computer-security-day","date":"2026-11-30","verification":"independent-calendar","summary":"A useful day for doing the small digital jobs you keep putting off. 🔐 Computer Security Day is observed on 30 November, encouraging people to protect the accounts, devices and files that matter to them.","sections":[{"heading":"Protect the ordinary things that matter","body":"Computer security is not only a concern for specialist teams. Everyday devices hold photographs, messages, work and access to important services. The University of Ottawa traces Computer Security Day to 1988 and uses the occasion to explain habits such as updating software, protecting accounts and making backups."},{"heading":"Choose one manageable check","body":"Instead of trying to overhaul your whole digital life at once, pick an important account or device. Check that its software is current, review its sign-in protection or confirm that a valuable file has a separate backup. Be cautious with unexpected links and downloads. A good security habit makes an ordinary task safer and easier to repeat, rather than relying on one annual burst of attention."}],"activity":{"text":"Pick your main email account and review its security settings, then check that an important document or photograph is backed up.","label":"Read practical security tips","url":"https://www.uottawa.ca/about-us/information-technology/services/security/awareness/computer-security-day"},"sources":[{"label":"University of Ottawa: Computer Security Day","url":"https://www.uottawa.ca/about-us/information-technology/services/security/awareness/computer-security-day","dateEvidence":true}],"title":"Computer Security Day"},"2026-12-01:national-eat-a-red-apple-day":{"id":"2026-12-01:national-eat-a-red-apple-day","date":"2026-12-01","verification":"independent-calendar","summary":"An unusually straightforward food-day instruction: enjoy a red apple. 🍎 Independent calendars mark 1 December for this informal US occasion, and the real fun is discovering that different apple varieties can taste surprisingly different.","sections":[{"heading":"More than one kind of red","body":"Colour is only one part of an apple’s character. Varieties differ in crispness, sweetness, acidity and how well they suit eating fresh or cooking. A red skin does not make every apple taste alike, and a familiar supermarket favourite is only a small part of the wider range."},{"heading":"Try a tiny tasting","body":"Slice two different varieties and compare them before checking their labels. Notice whether the flesh is firm or soft, whether the flavour is sharp or sweet, and which one you would choose with cheese or in a sandwich. The food day’s origin is not well documented, and its old-fashioned name is not a health claim. It is simply a convenient prompt to pay attention to a familiar fruit."}],"activity":{"text":"Taste two red apple varieties side by side and give each a three-word review before choosing your favourite.","label":"Explore the food-day listing","url":"https://nationaldaycalendar.com/celebrations/national-eat-a-red-apple-day-december-1"},"sources":[{"label":"National Day Calendar: 1 December","url":"https://nationaldaycalendar.com/celebrations/national-eat-a-red-apple-day-december-1","dateEvidence":true}]},"2026-12-03:celebrate-shelter-pets-day":{"id":"2026-12-03:celebrate-shelter-pets-day","date":"2026-12-03","verification":"independent-calendar","summary":"A celebration of the animals whose stories continue after a shelter or rescue stay. 🐾 Celebrate Shelter Pets Day falls on the first Thursday after US Thanksgiving, which is 3 December in 2026.","sections":[{"heading":"Stories can change assumptions","body":"The observance grew out of the Shelter Pet Project, with support from animal-welfare organisations including Maddie’s Fund. Its early online format encouraged people to share experiences of adopted animals, helping others see individual companions rather than an anonymous label. It is a celebration of people-and-pet relationships as well as an awareness occasion."},{"heading":"Support does not have to mean adopting today","body":"Bringing an animal home is a long-term decision, not a deadline created by a calendar entry. You can instead share a reputable rescue’s accurate appeal, offer a skill or ask what supplies it currently needs. If you already live with a former shelter pet, a small story about their real personality can be more useful than a dramatic before-and-after narrative."}],"activity":{"text":"Share a favourite story about a former shelter pet, or ask a local rescue which practical help it currently needs.","label":"Learn about the observance","url":"https://www.catster.com/lifestyle/celebrate-shelter-pets-day/"},"sources":[{"label":"Catster: first Thursday after Thanksgiving and 2026 date","url":"https://www.catster.com/lifestyle/celebrate-shelter-pets-day/","dateEvidence":true},{"label":"Maddie’s Fund: Shelter Pet Project context","url":"https://www.maddiesfund.org/topic-live-outcomes-adoptions-and-adoption-programs.htm","dateEvidence":false}]},"2026-12-04:national-sock-day":{"id":"2026-12-04:national-sock-day","date":"2026-12-04","verification":"organiser","summary":"For once, the sock that survived the wash gets some recognition. 🧦 National Sock Day on 4 December began with Pair of Thieves and now also highlights the value of practical support for communities in need.","sections":[{"heading":"A playful idea with a useful purpose","body":"The founder describes the day as starting with an affection for socks and developing into an occasion for service. Pair of Thieves uses 4 December for volunteering and work with charitable partners. The theme includes appreciating the everyday usefulness of something that is easy to take for granted."},{"heading":"Let the socks do something","body":"Wear a favourite pair, take a photograph of the ones that have somehow stayed together, or find out whether a local organisation is requesting new socks. If donating, follow its current wish list and requirements rather than assuming used or mismatched items will be helpful. A colourful pair can start the conversation; asking what someone actually needs gives the gesture a practical next step."}],"activity":{"text":"Wear your most cheerful matching pair, then check a local charity’s current wish list for new socks or other essentials.","label":"See the founder’s community work","url":"https://pairofthieves.com/pages/good-fits"},"sources":[{"label":"Pair of Thieves: National Sock Day and 4 December","url":"https://pairofthieves.com/pages/good-fits","dateEvidence":true}]},"2026-12-06:national-gazpacho-day":{"id":"2026-12-06:national-gazpacho-day","date":"2026-12-06","verification":"independent-calendar","summary":"A cold soup in December? The calendar enjoys a plot twist. 🍅 National Gazpacho Day is an informal US food occasion on 6 December, celebrating the refreshing Spanish soup more often associated with warm weather.","sections":[{"heading":"A soup with southern Spanish roots","body":"Gazpacho is closely associated with Andalusia. Familiar versions combine tomatoes with vegetables, bread, olive oil and vinegar, but ingredients and textures vary. It is usually served chilled rather than steaming hot. The existence of this winter food day does not mean it is a traditional Spanish December festival."},{"heading":"Make the vegetables the point","body":"Good gazpacho gives simple ingredients space to taste of themselves. A small chilled glass can work as a starter or a bright contrast to another dish. The linked Good Food recipe offers one practical Spanish-style version, rather than claiming to be the only authentic formula. The food holiday’s own origins are not firmly documented, so it is best understood as an invitation to try the soup."}],"activity":{"text":"Make a small batch of gazpacho and serve it in little glasses, with toppings kept separate so everyone can choose their texture.","label":"Try a gazpacho recipe","url":"https://www.bbcgoodfood.com/recipes/gazpacho"},"sources":[{"label":"National Day Calendar: 6 December","url":"https://nationaldaycalendar.com/celebrations/national-gazpacho-day-december-6/","dateEvidence":true},{"label":"Good Food: gazpacho recipe","url":"https://www.bbcgoodfood.com/recipes/gazpacho","dateEvidence":false}]},"2026-12-08":{"id":"2026-12-08","date":"2026-12-08","verification":"independent-calendar","summary":"Fudgy middle, crisp edge or the corner piece everyone negotiates over? 🍫 National Brownie Day appears in US food calendars on 8 December, celebrating a small bake with a very enthusiastic following.","sections":[{"heading":"Brownies have more than one personality","body":"Chocolate brownies can range from dense and fudgy to lighter and more cake-like. Blondies are a related bake usually built around brown sugar rather than chocolate. Early printed brownie recipes appeared around the turn of the twentieth century, but the origin of this particular food day remains uncertain."},{"heading":"Make a tray worth sharing","body":"Choose one recipe and decide what matters most to you: a soft centre, a crackly top or a particular mix-in. Cut the finished bake into small pieces for an easy tasting with friends or colleagues. Let a recipe guide baking and cooling rather than relying on a dramatic origin myth about an accidental mistake. Bought brownies are also entirely capable of supplying a good piece of chocolate-based happiness."}],"activity":{"text":"Bake the linked chocolate brownies, then compare an edge piece and a middle piece and settle your own household’s favourite.","label":"Bake chocolate brownies","url":"https://www.bbcgoodfood.com/recipes/best-ever-chocolate-brownies-recipe"},"sources":[{"label":"National Day Calendar: 8 December","url":"https://nationaldaycalendar.com/celebrations/national-brownie-day-december-8","dateEvidence":true},{"label":"Good Food: chocolate brownie recipe","url":"https://www.bbcgoodfood.com/recipes/best-ever-chocolate-brownies-recipe","dateEvidence":false}]},"2026-12-09:christmas-card-day":{"id":"2026-12-09:christmas-card-day","date":"2026-12-09","verification":"independent-calendar","summary":"A small piece of post can say more than another notification. 💌 Christmas Card Day is an informal 9 December occasion for sending a greeting, especially to someone you might otherwise miss during the festive rush.","sections":[{"heading":"The early commercial Christmas card","body":"The familiar history of Christmas cards includes Henry Cole’s 1843 commission to artist John Callcott Horsley. Printed cards made it easier to send seasonal greetings to a wider circle. The tradition later expanded into many forms, from family photographs and illustrated cards to postcards and messages sent electronically."},{"heading":"A personal line makes the difference","body":"You do not need a long annual newsletter or a perfect photograph. Mention a shared memory, ask a real question or say something you appreciate about the recipient. A handmade card can be as simple as a folded piece of paper with one drawing. The origin of the calendar day is uncertain; the enduring idea is making a deliberate connection rather than producing a large pile of identical messages."}],"activity":{"text":"Write one card to someone you have not spoken to recently, adding a specific memory rather than only a printed greeting.","label":"Explore the card tradition","url":"https://nationaldaycalendar.com/celebrations/christmas-card-day-december-9/"},"sources":[{"label":"National Day Calendar: Christmas Card Day","url":"https://nationaldaycalendar.com/celebrations/christmas-card-day-december-9/","dateEvidence":true}]},"2026-12-11:national-tango-day":{"id":"2026-12-11:national-tango-day","date":"2026-12-11","verification":"organiser","summary":"Argentina’s National Tango Day celebrates a musical culture that can be heard as well as danced. 🎶 Every 11 December honours the birthdays of singer Carlos Gardel and orchestra leader Julio de Caro.","sections":[{"heading":"Two birthdays, one cultural celebration","body":"The date became an official Argentine celebration in 1977 after a campaign associated with producer Ben Molar. Gardel and de Caro represent different contributions to tango’s development, so the day is about a musical world as much as the image of a dancing couple."},{"heading":"Start by listening","body":"Tango has a distinctive conversation between melody, rhythm, voice and movement. Listening to a recording before trying the steps can make it easier to notice that relationship. For a social class or a milonga, check what beginners are welcome to do and respect the etiquette of the event. A quiet listening session is a perfectly good way to begin; no dramatic pose or dance partner is required."}],"activity":{"text":"Listen to one Carlos Gardel recording and one orchestral tango, noticing how the mood changes between a voice-led and instrumental performance.","label":"Explore Argentina’s tango story","url":"https://www.argentina.gob.ar/noticias/11-de-diciembre-dia-nacional-del-tango-0"},"sources":[{"label":"Argentina’s government: 11 December and origins","url":"https://www.argentina.gob.ar/noticias/11-de-diciembre-dia-nacional-del-tango-0","dateEvidence":true}],"title":"National Tango Day · Argentina"},"2026-12-13":{"id":"2026-12-13","date":"2026-12-13","verification":"independent-calendar","summary":"A favourite mug, a chocolatey drink and five minutes without rushing. ☕ National Cocoa Day falls on 13 December in informal US food calendars, offering an especially cosy excuse to make something warm.","sections":[{"heading":"Cocoa or hot chocolate?","body":"The names are often used interchangeably, but cocoa commonly starts with cocoa powder, while drinking chocolate can use chocolate containing cocoa butter. Home recipes may combine both. Different milks, chocolate strengths and toppings produce quite different drinks, from a light cocoa to something almost dessert-like."},{"heading":"Build a mug that suits you","body":"Use a familiar recipe and change just one element: a little cinnamon, a different chocolate or a topping to share. A small home cocoa bar can be as simple as two mugs and a few choices in bowls. The food day’s origins are not clearly documented, and its appeal does not need exaggerated health claims. Enjoy it as a drink you like, not as a treatment or a test of festive enthusiasm."}],"activity":{"text":"Make the linked single-mug hot chocolate, then add one favourite topping and drink it somewhere comfortable.","label":"Make a chocolatey mug","url":"https://www.bbcgoodfood.com/recipes/homemade-hot-chocolate"},"sources":[{"label":"National Day Calendar: 13 December","url":"https://nationaldaycalendar.com/celebrations/national-cocoa-day-december-13","dateEvidence":true},{"label":"Good Food: homemade hot chocolate","url":"https://www.bbcgoodfood.com/recipes/homemade-hot-chocolate","dateEvidence":false}]},"2026-12-14:national-bouillabaisse-day":{"id":"2026-12-14:national-bouillabaisse-day","date":"2026-12-14","verification":"independent-calendar","summary":"A fish soup with the personality of a port city. 🐟 National Bouillabaisse Day is an informal US food date on 14 December, pointing towards the much older cooking traditions of Marseille in southern France.","sections":[{"heading":"The dish behind the name","body":"Bouillabaisse is associated with Mediterranean fish, a fragrant broth and strong local opinions about how it should be made. Saffron, fennel and other aromatics appear in familiar versions. Bread and rouille, a strongly flavoured accompaniment, can be part of the serving ritual. Recipes outside Marseille often adapt to the fish available locally."},{"heading":"A cooking project rather than a quick shortcut","body":"The linked recipe is a substantial kitchen project, so read it through before buying ingredients or inviting a whole dinner party. You can also use the day to learn what distinguishes bouillabaisse from another fish stew. The American food holiday is not the origin of the French dish, and its own founding story is not firmly documented. The interesting history belongs to the food and its region."}],"activity":{"text":"Read the linked bouillabaisse recipe and plan a small seafood supper, asking a fishmonger which suitable fish are available locally.","label":"Explore a bouillabaisse recipe","url":"https://www.bbcgoodfood.com/recipes/bouillabaisse"},"sources":[{"label":"National Day Calendar: 14 December","url":"https://nationaldaycalendar.com/celebrations/national-bouillabaisse-day-december-14/","dateEvidence":true},{"label":"Good Food: bouillabaisse recipe","url":"https://www.bbcgoodfood.com/recipes/bouillabaisse","dateEvidence":false}]},"2026-12-16:day-of-reconciliation":{"id":"2026-12-16:day-of-reconciliation","date":"2026-12-16","verification":"organiser","summary":"South Africa’s Day of Reconciliation is a public holiday on 16 December. It invites reflection on the country’s divided history and the continuing work of building a society in which people can belong equally.","sections":[{"heading":"A date carrying different histories","body":"Before democracy, 16 December was associated with the Day of the Vow in Afrikaner tradition. It also marked the 1961 formation of Umkhonto we Sizwe in the anti-apartheid struggle. The democratic government retained the date as a public holiday but reframed it around reconciliation and national unity."},{"heading":"Looking forward requires looking honestly","body":"The renamed Day of Reconciliation was first celebrated in 1995. Its purpose is not to pretend that historical conflict or present inequalities have disappeared. It creates space to understand different experiences and consider what a shared future requires. Reading South African accounts from more than one community is a more meaningful starting point than reducing the occasion to a general message about everyone getting along."}],"activity":{"text":"Read the South African government’s background, then choose a South African writer or museum account that adds another perspective on the history.","label":"Explore the holiday’s background","url":"https://www.gov.za/day-reconciliation"},"sources":[{"label":"South African Government: 2026 public holidays","url":"https://www.gov.za/zu/about-sa/public-holidays","dateEvidence":true},{"label":"South African Government: Day of Reconciliation background","url":"https://www.gov.za/day-reconciliation","dateEvidence":false}]},"2026-12-18":{"id":"2026-12-18","date":"2026-12-18","verification":"organiser","summary":"International Migrants Day recognises the rights, experiences and contributions of people who move between countries. The United Nations marks 18 December, encouraging informed discussion that keeps individual lives visible behind statistics and labels.","sections":[{"heading":"Why 18 December?","body":"The UN General Assembly proclaimed International Migrants Day in 2000. The date connects with the international convention on migrant workers and their families adopted on 18 December 1990. The observance encourages the sharing of information and experience while supporting respect for human rights."},{"heading":"There is no single migrant story","body":"People move for many reasons, and experiences can include opportunity, family connections, study, work or serious hardship. A thoughtful conversation makes room for that variety without demanding that one person speak for everyone. Listening to first-person accounts and checking the context of a claim can be more useful than treating migration as an abstract debate. Rights and dignity remain relevant whatever someone’s journey looks like."}],"activity":{"text":"Read one first-person migration account from a trusted organisation and notice which details disappear when the story is reduced to a headline.","label":"Explore the UN observance","url":"https://www.un.org/en/observances/international-migrants-day"},"sources":[{"label":"United Nations: International Migrants Day","url":"https://www.un.org/en/observances/international-migrants-day","dateEvidence":true},{"label":"UN resolution proclaiming 18 December","url":"https://digitallibrary.un.org/record/428989/files/A_RES_55_93-EN.pdf","dateEvidence":true}]},"2026-12-19:look-for-an-evergreen-day":{"id":"2026-12-19:look-for-an-evergreen-day","date":"2026-12-19","verification":"independent-calendar","summary":"Evergreens are doing their quiet winter work while other trees look bare. 🌲 Independent calendars list Look for an Evergreen Day on 19 December: a simple prompt to notice the greenery beyond the decorated Christmas tree.","sections":[{"heading":"Evergreen is a habit, not one tree","body":"Evergreen plants retain foliage through the year, but they are not all pines and they do not all look alike. Shape, leaves or needles, bark and cones can help identify a tree. A park, garden or ordinary street can offer useful examples without requiring a long woodland expedition."},{"heading":"Look closely, leave things growing","body":"Use a reliable identification guide and compare several features rather than deciding from colour alone. Photograph a leaf arrangement or the overall silhouette, and keep any uncertain identification tentative. You do not need to collect branches or taste berries to enjoy the activity. The day is an informal nature occasion, and accounts of its precise founder are not consistently documented; the winter walk is the dependable part."}],"activity":{"text":"Find two evergreen trees or shrubs on a short walk and compare their leaf shapes using the Woodland Trust’s guide.","label":"Use a tree-identification guide","url":"https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/how-to-identify-trees/"},"sources":[{"label":"Days of Observance: 19 December listing","url":"https://daysofobservance.com/look-for-an-evergreen-day/","dateEvidence":true},{"label":"Woodland Trust: tree identification","url":"https://www.woodlandtrust.org.uk/trees-woods-and-wildlife/british-trees/how-to-identify-trees/","dateEvidence":false}],"researchNote":"Independent calendars agree on 19 December; founder attribution to the former National Arborist Association is not presented as confirmed."},"2026-12-21:world-meditation-day":{"id":"2026-12-21:world-meditation-day","date":"2026-12-21","verification":"organiser","summary":"World Meditation Day is a United Nations observance on 21 December, established in 2024. It opens space to learn about meditation’s varied traditions and modern practices, without making calmness into another task to get right.","sections":[{"heading":"A recent international observance","body":"The UN General Assembly adopted the resolution creating the day in December 2024. It invites governments, organisations and individuals to raise awareness of meditation. The calendar date is internationally designated, while the practices discussed under that heading come from many different cultural, religious and secular settings."},{"heading":"A small experiment is enough","body":"You can approach the day as a chance to notice attention rather than to achieve a particular state. Try a brief quiet pause, or learn how a tradition describes its own practice. Some people enjoy guided exercises while others prefer a different way of resting or reflecting. The day does not mean meditation suits everyone, replaces care or guarantees a health outcome; curiosity is a more useful starting point than pressure."}],"activity":{"text":"Take one unhurried minute to notice the sounds around you, or read how the UN describes the purpose of the day.","label":"Explore World Meditation Day","url":"https://www.un.org/en/observances/meditation-day"},"sources":[{"label":"UN resolution creating World Meditation Day","url":"https://mandates.un.org/mandate/A/RES/79/137","dateEvidence":true},{"label":"United Nations: meditation-day background","url":"https://www.un.org/en/observances/meditation-day","dateEvidence":false}]},"2026-12-22:national-cookie-exchange-day":{"id":"2026-12-22:national-cookie-exchange-day","date":"2026-12-22","verification":"independent-calendar","summary":"The most efficient way to try six kinds of biscuit without baking six batches. 🍪 National Cookie Exchange Day is an informal US occasion on 22 December, built around sharing homemade treats and borrowing each other’s favourites.","sections":[{"heading":"How a cookie exchange works","body":"Each person brings one type of cookie or biscuit, then everyone takes home a selection. The scale can be tiny: two friends swapping a few pieces still captures the idea. Independent calendars agree on 22 December, but there is no single organisation setting the rules or requiring an elaborate party."},{"heading":"Make the exchange easy to enjoy","body":"Agree quantities in advance so nobody arrives with a mountain of baking, and label ingredients clearly. Keep different types separate and include a recipe name or a small note about the bake. You could also swap a recipe, a decorating idea or a small shop-bought favourite if baking is not realistic. The useful tradition is generous variety, not competing to produce the most impressive box."}],"activity":{"text":"Invite two friends to bring one biscuit variety each, label the ingredients and swap a few pieces with the recipe names.","label":"Plan a small cookie swap","url":"https://www.punchbowl.com/holidays/national-cookie-exchange-day"},"sources":[{"label":"Punchbowl: 22 December 2026 listing","url":"https://www.punchbowl.com/holidays/national-cookie-exchange-day","dateEvidence":true},{"label":"Awareness Days: independent-calendar date convention","url":"https://www.awarenessdays.com/awareness-days-calendar/national-cookie-exchange-day/","dateEvidence":true}]},"2026-12-24:christmas-book-flood":{"id":"2026-12-24:christmas-book-flood","date":"2026-12-24","verification":"organiser","summary":"A new book, a comfortable corner and an evening given over to reading. 📚 Iceland’s Christmas book flood is a whole publishing season, with a much-loved tradition of exchanging books and beginning them on Christmas Eve.","sections":[{"heading":"The flood begins before Christmas Eve","body":"Jólabókaflóð refers to the seasonal cycle of books being published, discovered and given as Christmas presents. It is not a one-day national holiday invented for reading in bed. Visit Iceland describes the exchange of books on Christmas Eve and the pleasure of spending the evening, and often the following day, reading them."},{"heading":"Borrow the spirit, not a rigid rule","body":"You can choose a second-hand book, a library book to read together or a title that has a particular meaning for the recipient. Add a short note about why you chose it, then allow an undisturbed stretch of reading time. There is no need for matching pyjamas, an expensive gift or a photograph proving that the evening was cosy. The appeal is giving a story some room."}],"activity":{"text":"Choose a book for someone and tuck in a note explaining your choice, then set aside a quiet hour to read your own.","label":"Discover the Icelandic tradition","url":"https://www.visiticeland.com/article/book-flood/"},"sources":[{"label":"Visit Iceland: the Christmas Book Flood","url":"https://www.visiticeland.com/article/book-flood/","dateEvidence":true}],"title":"Jólabókaflóð · Christmas Eve reading","researchNote":"24 December represents the Christmas Eve book-giving/reading custom. Jólabókaflóð itself is the wider seasonal publishing and gift-buying cycle, not a fixed one-day public holiday."},"2026-12-26":{"id":"2026-12-26","date":"2026-12-26","verification":"organiser","summary":"Kwanzaa begins on 26 December and continues through 1 January, celebrating African heritage, community and shared values. Its seven days each focus on a principle, making the opening date the start of a week rather than a standalone holiday.","sections":[{"heading":"A modern cultural celebration","body":"Maulana Karenga created Kwanzaa in 1966 in the United States. Its name and traditions draw on African harvest-festival ideas, while the celebration centres African American cultural connection and community. It is a cultural holiday, not a requirement to follow one religion, and families choose how to make it part of their lives."},{"heading":"Seven principles across the week","body":"The Nguzo Saba include unity, self-determination, collective work and responsibility, cooperative economics, purpose, creativity and faith. The first day focuses on unity, or Umoja. Ceremonies can include lighting candles in a kinara, storytelling, music, shared food and reflection. Only the opening is shown in this calendar; the rest of the date range belongs to the same celebration. Learning from community-led accounts keeps the symbols connected to their meaning."}],"activity":{"text":"Explore the Smithsonian’s introduction and choose one of the seven principles to discuss with family or friends.","label":"Explore Kwanzaa with the Smithsonian","url":"https://nmaahc.si.edu/explore/moments/kwanzaa"},"sources":[{"label":"Smithsonian NMAAHC: Kwanzaa dates and principles","url":"https://nmaahc.si.edu/explore/moments/kwanzaa","dateEvidence":true},{"label":"Smithsonian: 26 December 2026–1 January 2027 programme","url":"https://www.si.edu/newsdesk/releases/anacostia-community-museum-marks-nearly-50-years-kwanzaa-traditions-weeklong","dateEvidence":true}]},"2026-12-27:international-day-of-epidemic-preparedness":{"id":"2026-12-27:international-day-of-epidemic-preparedness","date":"2026-12-27","verification":"organiser","summary":"The International Day of Epidemic Preparedness is observed on 27 December. It highlights the systems, knowledge and cooperation that help communities prepare for outbreaks and keep essential services working when health emergencies happen.","sections":[{"heading":"Preparedness happens before a crisis","body":"The UN created the observance in 2020, with the experience of COVID-19 showing how epidemics can affect health, livelihoods and everyday life. The focus includes resilient health systems, education and the exchange of reliable information. It recognises that preparation involves communities and institutions, not only individual supplies or decisions."},{"heading":"Connection is part of the work","body":"The UN also highlights cooperation across borders and the links between human, animal and environmental health. A practical way to approach the day is to learn which public-health sources serve your area and how they communicate updates. This calendar is an introduction to the observance, not an emergency bulletin or personal medical guidance. Current local advice is more useful than recycled claims from a different outbreak or country."}],"activity":{"text":"Identify your local public-health information source and check how it shares current updates and explains uncertain information.","label":"Explore the UN preparedness day","url":"https://www.un.org/en/observances/epidemic-preparedness-day"},"sources":[{"label":"United Nations: epidemic preparedness observance","url":"https://www.un.org/en/observances/epidemic-preparedness-day","dateEvidence":true},{"label":"UN resolution establishing the day","url":"https://digitallibrary.un.org/record/3895278","dateEvidence":true}]},"2026-12-29":{"id":"2026-12-29","date":"2026-12-29","verification":"independent-calendar","summary":"The year is nearly over, but this is not a demand to finish your entire life admin pile. ⏰ Tick Tock Day on 29 December is an informal prompt to notice one piece of unfinished business and decide what deserves attention.","sections":[{"heading":"A deliberately timely idea","body":"National Day Calendar attributes Tick Tock Day to Thomas and Ruth Roy of Wellcat Holidays. Its date puts it just before New Year, when practical deadlines and personal projects can feel especially visible. It is a novelty observance, not an official deadline and not a rule that everything must be completed before midnight on 31 December."},{"heading":"Choose, finish or consciously let go","body":"Make a short list and separate genuinely time-sensitive tasks from things that can wait. Pick one small action you can actually complete: send a message, file a document or finish a chapter. Some items may no longer matter, and deciding not to do them can be useful too. Where a task has a real legal, financial or workplace deadline, use the actual terms rather than a calendar-day suggestion."}],"activity":{"text":"Choose one ten-minute unfinished task, complete it, and deliberately move or remove one item that does not need your attention now.","label":"Explore Tick Tock Day","url":"https://nationaldaycalendar.com/celebrations/tick-tock-day-december-29/"},"sources":[{"label":"National Day Calendar: 29 December and founders","url":"https://nationaldaycalendar.com/celebrations/tick-tock-day-december-29/","dateEvidence":true}]},"2026-12-30:falling-needles-family-fest-day":{"id":"2026-12-30:falling-needles-family-fest-day","date":"2026-12-30","verification":"independent-calendar","summary":"When the Christmas tree starts redecorating the floor, it has its own unofficial occasion. 🌲 Falling Needles Family Fest Day on 30 December turns the seasonal clear-up into a shared task, with a chance to plan sensible tree recycling.","sections":[{"heading":"A deliberately silly name","body":"This novelty day is attributed to Thomas and Ruth Roy of Wellcat Holidays. Its joke is the familiar sight of needles falling from a real Christmas tree after the celebrations. You do not have to take decorations down on this date; different households and traditions keep them up for different lengths of time."},{"heading":"Give the tree a useful next step","body":"If you are ready to clear up, remove decorations and check local collection or drop-off arrangements before putting a tree outside. Recycle Now notes that UK councils often publish special real-tree collections or recycling points in early January. Artificial trees need different handling. A quick plan now can keep a dried tree from becoming an inconvenient pavement obstacle and make the final festive job easier to share."}],"activity":{"text":"Check your council’s real-tree recycling arrangements, then split the undecorating and needle-sweeping jobs with someone at home.","label":"Find tree-recycling guidance","url":"https://www.recyclenow.com/recycle-an-item/christmas-trees"},"sources":[{"label":"National Day Calendar: 30 December and founders","url":"https://nationaldaycalendar.com/celebrations/falling-needles-family-fest-day-december-30","dateEvidence":true},{"label":"Recycle Now: real Christmas trees","url":"https://www.recyclenow.com/recycle-an-item/christmas-trees","dateEvidence":false}]},"2026-11-01:national-cinnamon-day":{"id":"2026-11-01:national-cinnamon-day","date":"2026-11-01","verification":"organiser","summary":"A little cinnamon can make a kitchen smell like someone has excellent plans. 🍂 This US food celebration, launched by McCormick in 2019, gives the familiar baking spice its own November moment.","sections":[{"heading":"A day with a known beginning","body":"McCormick announced the first National Cinnamon Day for 1 November 2019, linking it with the start of the holiday cooking season. Unlike many food-calendar dates with uncertain origins, this one has a documented commercial founder. It is a promotional food celebration, rather than a US public holiday or a traditional religious festival."},{"heading":"More than a cinnamon roll","body":"The spice appears in sweet baking, warm drinks and savoury cooking. Ground cinnamon mixes readily into a filling or batter; sticks are handy for infusing a drink and lifting out afterwards. For a low-effort celebration, upgrade toast or porridge. For a baking project, make a batch of rolls and let the icing be delightfully untidy."}],"activity":{"text":"Bake a batch of cinnamon rolls, or add a sprinkle to a breakfast you already enjoy.","label":"Try cinnamon rolls","url":"https://www.bbcgoodfood.com/recipes/cinnamon-rolls"},"sources":[{"label":"McCormick’s original 2019 announcement","url":"https://ir.mccormick.com/news-releases/news-release-details/cinnamon-lovers-everywhere-have-reason-celebrate-first-ever","dateEvidence":true},{"label":"Good Food: cinnamon rolls","url":"https://www.bbcgoodfood.com/recipes/cinnamon-rolls","dateEvidence":false}]},"2026-11-03:national-sandwich-day":{"id":"2026-11-03:national-sandwich-day","date":"2026-11-03","verification":"independent-calendar","summary":"Lunch deserves an upgrade. 🥪 National Sandwich Day is an informal US food date for everything from a crisp toastie to an extravagantly filled baguette, celebrated each year on 3 November.","sections":[{"heading":"The name behind the lunch","body":"The modern word sandwich is associated with John Montagu, the fourth Earl of Sandwich. The familiar story says he wanted food he could eat without abandoning his game, but that story should not be treated as proof that he invented putting fillings in bread. Bread-and-filling combinations have a much wider history."},{"heading":"Build something worth a lunch break","body":"A sandwich can be hot or cold, open-faced or enclosed, and the bread is part of the flavour rather than just packaging. Try balancing a rich filling with something sharp or crunchy: cheese with pickle, roasted vegetables with a bright dressing, or a classic filling on a different loaf. There is no official winning combination to copy."}],"activity":{"text":"Choose one new bread, spread or crunchy ingredient and give your usual sandwich a small reinvention.","label":"Find a sandwich recipe","url":"https://www.greatbritishchefs.com/collections/sandwich-recipes"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-sandwich-day-november-3","dateEvidence":true},{"label":"Great British Chefs: sandwich recipes","url":"https://www.greatbritishchefs.com/collections/sandwich-recipes","dateEvidence":false}]},"2026-11-04:national-candy-day":{"id":"2026-11-04:national-candy-day","date":"2026-11-04","verification":"independent-calendar","summary":"A date for the sweet-shop counter and the treats you remember from childhood. 🍬 National Candy Day falls on 4 November in US food calendars, without a firmly documented founding organisation.","sections":[{"heading":"A very broad sweet category","body":"In American English, candy covers a wide assortment of confectionery, including hard sweets, chewy pieces, chocolate bars and marshmallows. Its variety comes from different ingredients and ways of handling sugar, chocolate and texture. The observance celebrates that whole colourful category; it is not limited to a single recipe, brand or style of sweet."},{"heading":"Make a tiny sweet-shop tasting","body":"Choose a couple of contrasting favourites and compare what you like: sour versus creamy, crunchy versus chewy, or a nostalgic flavour against something unfamiliar. A small shared selection works perfectly. If you would rather make something, rocky road turns chocolate, biscuit pieces and sweet additions into a playful traybake without requiring professional confectionery equipment."}],"activity":{"text":"Make rocky road with a few favourite sweet additions, then share the finished pieces.","label":"Make easy rocky road","url":"https://www.bbcgoodfood.com/recipes/easy-rocky-road"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-candy-day-november-4","dateEvidence":true},{"label":"Good Food: easy rocky road","url":"https://www.bbcgoodfood.com/recipes/easy-rocky-road","dateEvidence":false}]},"2026-11-05:international-stout-day":{"id":"2026-11-05:international-stout-day","date":"2026-11-05","verification":"independent-calendar","summary":"Dark beer gets a moment in the spotlight. International Stout Day falls on the first Thursday of November—5 November in 2026—and invites curiosity about a beer family with plenty of variety.","sections":[{"heading":"Why the date moves","body":"This informal drinks observance follows a weekday rule, rather than a fixed date: the first Thursday in November. That puts it on 5 November in 2026. It is separate from International Beer Day and from individual breweries’ launch events, so a tasting promotion may happen on a nearby evening instead."},{"heading":"Dark does not mean one flavour","body":"Stout is a dark beer style, with roasted-grain character that can suggest coffee or chocolate without those ingredients necessarily being added. There are dry, sweet, oatmeal and stronger interpretations, among others. You can explore the language of a tasting menu, ask a brewer about the malt, or choose an alcohol-free example; drinking alcohol is entirely optional."}],"activity":{"text":"Ask about the roasted-grain flavours in a stout, including an alcohol-free option if you prefer.","label":"Explore Stout Day","url":"https://www.timeanddate.com/holidays/fun/international-stout-day"},"sources":[{"label":"Time and Date: International Stout Day","url":"https://www.timeanddate.com/holidays/fun/international-stout-day","dateEvidence":true},{"label":"WSET: 2026 drinks calendar","url":"https://www.wsetglobal.com/news-insights/insight-opinion/the-drinks-calendar/","dateEvidence":true}]},"2026-11-06:gumboot-friday":{"id":"2026-11-06:gumboot-friday","date":"2026-11-06","verification":"organiser","summary":"Gumboot Friday is a New Zealand campaign supporting access to counselling for young people. Its 2026 nationwide fundraising day is Friday 6 November, using an ordinary pair of boots as a conversation starter.","sections":[{"heading":"Why a pair of gumboots?","body":"The campaign uses walking through mud as a way to describe how difficult daily life can feel when someone is struggling with depression. Wearing gumboots is a visible gesture of support and a prompt for conversation. The metaphor belongs to the campaign; it does not mean everyone experiences mental-health difficulties in the same way."},{"heading":"A practical local initiative","body":"Run through the I Am Hope Foundation, Gumboot Friday connects eligible young people in New Zealand with counselling support. Schools, workplaces, sports groups and families take part in its awareness and fundraising activities. The campaign explains that this service is intended to bridge immediate need alongside existing support, rather than replace government services. Its organiser publishes current participation information and resources."}],"activity":{"text":"Look through the organiser’s event resources and choose a respectful way to support young people in your community.","label":"See campaign resources","url":"https://www.gumbootfriday.org.nz/fundraise"},"sources":[{"label":"Gumboot Friday: official 2026 campaign","url":"https://www.gumbootfriday.org.nz/fundraise","dateEvidence":true}]},"2026-11-08:diwali":{"id":"2026-11-08:diwali","date":"2026-11-08","verification":"organiser","summary":"Diwali brings lamps, shared food and gatherings to communities around the world. The main 2026 Diwali date is Sunday 8 November; its meanings and the surrounding festival days differ between traditions.","sections":[{"heading":"Light, stories and celebration","body":"Often called the festival of lights, Diwali is marked by many Hindus and has related observances in other faith communities. Diyas, candles and illuminated decorations are familiar features, alongside food, visits and prayer. The stories highlighted vary by region and community, so one family’s celebration should not be presented as the universal version of the festival."},{"heading":"More than a single evening","body":"Diwali commonly spans several days, with particular customs and significance attached to each. This calendar lists its principal 2026 date once, rather than repeating the whole festival. Rangoli designs, sweets and welcoming lights are useful starting points for learning about it. If attending a public celebration, follow the hosts’ guidance about photography, clothing and participation in religious activities."}],"activity":{"text":"Explore the Smithsonian’s introduction to the lamps, stories and customs before joining a local Diwali celebration.","label":"Explore Diwali traditions","url":"https://asia.si.edu/whats-on/events/celebrations/diwali/"},"sources":[{"label":"High Commission of India, London: 2026 holidays","url":"https://www.hcilondon.gov.in/page/list-of-the-holidays/","dateEvidence":true},{"label":"Smithsonian National Museum of Asian Art: Diwali","url":"https://asia.si.edu/whats-on/events/celebrations/diwali/","dateEvidence":false}]},"2026-11-09:carl-sagan-day":{"id":"2026-11-09:carl-sagan-day","date":"2026-11-09","verification":"independent-calendar","summary":"Look up: the universe has not run out of interesting things. 🔭 Carl Sagan Day is an informal science-appreciation occasion on 9 November, the birthday of the astronomer, author and much-loved science communicator.","sections":[{"heading":"The scientist behind the storyteller","body":"Born on 9 November 1934, Sagan worked in planetary science and advised NASA missions. He also helped bring complex scientific questions to a much wider audience through books and television. His interests included planetary atmospheres, the search for life beyond Earth and the possibilities opened by exploring our neighbouring worlds."},{"heading":"Curiosity is the point","body":"Community birthday observances became associated with astronomy activities, talks and screenings. This is an informal occasion rather than a public holiday, and there is no required programme. Choose a question you have genuinely wondered about—why planets look different, what a space probe measures, or how scientists investigate life elsewhere—and start with a trustworthy science source rather than a sensational headline."}],"activity":{"text":"Read NASA’s account of Sagan’s planetary work, then pick one mission you want to understand better.","label":"Meet Carl Sagan at NASA","url":"https://science.nasa.gov/people/carl-sagan/"},"sources":[{"label":"NASA: Carl Sagan biography","url":"https://science.nasa.gov/people/carl-sagan/","dateEvidence":true},{"label":"TheDayOf: informal birthday observance","url":"https://www.thedayof.net/fun-weird/carl-sagan-day/","dateEvidence":true}]},"2026-11-10:national-vanilla-cupcake-day":{"id":"2026-11-10:national-vanilla-cupcake-day","date":"2026-11-10","verification":"independent-calendar","summary":"Vanilla is getting its own little cake celebration. 🧁 This informal US food date on 10 November gives a familiar flavour the starring role, whether your cupcake is beautifully piped or gloriously lopsided.","sections":[{"heading":"A small cake with a long story","body":"Individual cakes have appeared in cookbooks for centuries. National Day Calendar points to an American recipe for cakes baked in small cups in 1796, with the word cupcake appearing in a later nineteenth-century collection. That baking history is separate from the origins of Vanilla Cupcake Day, whose founder is not clearly established."},{"heading":"Let the vanilla do some work","body":"Vanilla can flavour both the cake and its topping, so an apparently simple cupcake still offers room to experiment. Fruit, a little jam filling or a contrasting buttercream can change the result without disguising the base flavour. Bake a small batch to share, or choose a local baker’s version and notice how the sponge and icing work together."}],"activity":{"text":"Try a batch of vanilla cupcakes and let everyone choose a different topping.","label":"Bake vanilla cupcakes","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cupcakes"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-vanilla-cupcake-day-november-10/","dateEvidence":true},{"label":"Good Food: easy vanilla cupcakes","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cupcakes","dateEvidence":false}]},"2026-11-11:national-sundae-day":{"id":"2026-11-11:national-sundae-day","date":"2026-11-11","verification":"independent-calendar","summary":"An ordinary scoop can have excellent accessories. 🍨 National Sundae Day is an informal US food celebration on 11 November, giving sauces, toppings and the final cherry a chance to show off.","sections":[{"heading":"A dessert with competing origin stories","body":"A sundae usually brings ice cream together with a sauce or syrup and other toppings in a dish. Several American towns have claimed a part in its creation, and the evidence does not support a single simple invention story. The beginnings of the November observance are also uncertain, so enjoy the dessert without needing to settle the argument."},{"heading":"Build it for the contrast","body":"Cold ice cream, a flowing sauce and something crisp make a satisfying combination, but there is no compulsory formula. Try fruit and biscuit pieces, chocolate and nuts, or an ingredient already in your cupboard. Sharing a few topping bowls turns dessert into a small make-your-own occasion. Choose ingredients that suit the people joining you, including any allergies."}],"activity":{"text":"Create a little sundae bar, or try this caramel-and-chocolate version as a starting point.","label":"Make a sundae","url":"https://www.bbcgoodfood.com/recipes/nutty-caramel-choc-sundaes"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-sundae-day-november-11","dateEvidence":true},{"label":"Good Food: caramel and chocolate sundaes","url":"https://www.bbcgoodfood.com/recipes/nutty-caramel-choc-sundaes","dateEvidence":false}]},"2026-11-13:world-kindness-day":{"id":"2026-11-13:world-kindness-day","date":"2026-11-13","verification":"organiser","summary":"Kindness does not need an elaborate announcement. World Kindness Day, held on 13 November, encourages ordinary considerate actions and the connections they create between people, communities and countries.","sections":[{"heading":"Where the day began","body":"The World Kindness Movement introduced World Kindness Day in 1998. It grew from cooperation between kindness organisations rather than a United Nations public holiday. The movement encourages people to recognise helpful actions and share ideas across communities, using the day as a reason to make kindness more visible in everyday life."},{"heading":"Make it useful to the recipient","body":"A thoughtful action is about what someone would welcome, rather than what makes a good photograph. You could offer a specific practical favour, write a genuine thank-you, return something you borrowed, or give someone your full attention. Ask before taking over a task, respect a no, and avoid creating an obligation for the person you are trying to help."}],"activity":{"text":"Pick one person and offer a small, specific favour they can comfortably accept or decline.","label":"Find kindness ideas","url":"https://www.randomactsofkindness.org/kindness-ideas"},"sources":[{"label":"World Kindness Movement: history and date","url":"https://theworldkindnessmovement.org/about-us-2/story/","dateEvidence":true},{"label":"Random Acts of Kindness Foundation: ideas","url":"https://www.randomactsofkindness.org/kindness-ideas","dateEvidence":false}]},"2026-11-14:national-pickle-day":{"id":"2026-11-14:national-pickle-day","date":"2026-11-14","verification":"independent-calendar","summary":"A sharp little celebration for the jar in the fridge door. 🥒 National Pickle Day appears in US food calendars on 14 November, welcoming dill lovers, sweet-pickle fans and anyone firmly in the cornichon camp.","sections":[{"heading":"Pickle means more than cucumber","body":"In US usage, a pickle often means a preserved cucumber, but many fruits and vegetables can be pickled. Different brines, seasonings and processes produce very different results: sweet, sour, spicy, crisp or softly tangy. National Day Calendar confirms the November date while noting that the observance’s founder has not been identified."},{"heading":"Try a simple comparison","body":"Taste two styles alongside the same sandwich or cheese and notice how each changes the meal. A quick refrigerator pickle is an approachable cooking project, while fermented and shelf-stable preserves involve different methods. Follow a tested recipe and its storage instructions rather than treating every jar as interchangeable. You can also simply enjoy a pickle you already know you like."}],"activity":{"text":"Make quick cucumber ribbons to add crunch to a sandwich, salad or fish dish.","label":"Try quick pickled cucumbers","url":"https://www.bbcgoodfood.com/recipes/quick-pickled-cucumbers"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-pickle-day-november-14","dateEvidence":true},{"label":"Good Food: quick pickled cucumbers","url":"https://www.bbcgoodfood.com/recipes/quick-pickled-cucumbers","dateEvidence":false}]},"2026-11-15:national-bundt-day":{"id":"2026-11-15:national-bundt-day","date":"2026-11-15","verification":"organiser","summary":"A cake that comes out of its tin looking dressed for the occasion. 🍰 National Bundt Day is celebrated on 15 November, recognising the distinctive ring-shaped bake and the pans that give it those curves.","sections":[{"heading":"The pan is part of the story","body":"Nordic Ware, the company associated with the Bundt pan, established the celebration around its sixtieth anniversary in 2006. The date is a commercial food celebration, not a public holiday. Bundt describes the cake’s pan and shape, so there is no single flavour or one mandatory cake recipe that qualifies."},{"heading":"Make the shape the decoration","body":"The centre tube and patterned sides can turn a fairly simple batter into an eye-catching cake. Choose a recipe intended for the size and shape of your tin, and follow its preparation and cooling advice before turning it out. A light glaze or dusting can show off the ridges; an enormous layer of icing may hide all that useful geometry."}],"activity":{"text":"Bake a classic vanilla Bundt, then choose whether the ridges need glaze, icing sugar or nothing at all.","label":"Bake a vanilla Bundt","url":"https://www.kingarthurbaking.com/recipes/classic-vanilla-bundt-cake-recipe"},"sources":[{"label":"Nordic Ware: National Bundt Day","url":"https://www.nordicware.com/","dateEvidence":true},{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-bundt-day-november-15/","dateEvidence":true},{"label":"King Arthur Baking: classic vanilla Bundt","url":"https://www.kingarthurbaking.com/recipes/classic-vanilla-bundt-cake-recipe","dateEvidence":false}]},"2026-11-16:icelandic-language-day":{"id":"2026-11-16:icelandic-language-day","date":"2026-11-16","verification":"organiser","summary":"Icelandic gets a day for its stories, sound and future. Icelandic Language Day is held on 16 November, the birthday of poet Jónas Hallgrímsson, with celebrations of the language and those who care for it.","sections":[{"heading":"A poet’s birthday becomes a language day","body":"Iceland’s government chose the date in 1995 to draw attention to the language’s importance. Recognition and cultural events mark work done for Icelandic, connecting its literary inheritance with its present-day use. The National and University Library also maintains material about Hallgrímsson, including his writing and manuscripts, as part of that living cultural record."},{"heading":"Hear the language rather than just looking","body":"A phrase, poem or recording can be a more inviting introduction than a list of difficult-looking letters. Listen for the rhythm of a short passage and compare it with a translation if one is available. You do not have to master pronunciation in an afternoon; noticing what a language carries in stories, humour and everyday conversation is a worthwhile beginning."}],"activity":{"text":"Explore the national library’s introduction to Hallgrímsson and follow a poem or story that catches your attention.","label":"Visit the Icelandic library","url":"https://landsbokasafn.is/en/icelandic-language-day/"},"sources":[{"label":"Government of Iceland: Icelandic Language Day","url":"https://www.stjornarradid.is/default.aspx?PageID=3ca20762-9c59-11e6-940f-005056bc530c","dateEvidence":true},{"label":"National and University Library of Iceland","url":"https://landsbokasafn.is/en/icelandic-language-day/","dateEvidence":true}]},"2026-11-18:apple-cider-day":{"id":"2026-11-18:apple-cider-day","date":"2026-11-18","verification":"independent-calendar","summary":"A warm apple drink is a very reasonable November plan. 🍎 Apple Cider Day is an informal US food-calendar occasion on 18 November; here, cider may mean a fresh, non-alcoholic apple drink.","sections":[{"heading":"One word, different drinks","body":"In American usage, apple cider often refers to pressed, unfiltered apple juice, while fermented alcoholic cider is usually distinguished as hard cider. In Britain, cider normally means the alcoholic drink. That difference matters when choosing a recipe or ordering a glass: check the description instead of assuming that the name tells you the alcohol content."},{"heading":"Make an autumn pause","body":"This is a seasonal food observance rather than an official holiday, and its founder is not firmly documented. You can appreciate the apple harvest without pressing fruit yourself: try a cloudy juice, compare two apple drinks, or gently warm a spiced version. The linked recipe offers a non-alcoholic option, so the occasion can be about flavour and a comforting mug."}],"activity":{"text":"Warm apple juice with seasonal spices for a simple alcohol-free drink to share.","label":"Make mulled apple juice","url":"https://www.bbcgoodfood.com/recipes/mulled-apple-juice"},"sources":[{"label":"Holiday Insights: Apple Cider Day","url":"https://www.holidayinsights.com/moreholidays/november/apple-cider-day.htm","dateEvidence":true},{"label":"Good Food: mulled apple juice","url":"https://www.bbcgoodfood.com/recipes/mulled-apple-juice","dateEvidence":false}]},"2026-11-19:world-toilet-day":{"id":"2026-11-19:world-toilet-day","date":"2026-11-19","verification":"organiser","summary":"World Toilet Day puts an everyday necessity at the centre of a serious global conversation. Held on 19 November, it highlights safe sanitation, dignity and the people still living without a suitable toilet.","sections":[{"heading":"An essential service, not a joke","body":"The United Nations has officially observed World Toilet Day since 2013, with UN-Water coordinating the campaign. It connects sanitation with the wider goal of clean water and sanitation for everyone. A safe toilet involves much more than a seat and a door: the waste also needs to be contained, removed and treated appropriately."},{"heading":"Why access changes daily life","body":"Sanitation affects people’s privacy, safety and ability to take part in school, work and community life. Problems are not distributed evenly, and facilities need to work for different bodies and circumstances. The useful focus is on practical systems and people’s rights, rather than jokes or images that turn communities into spectacles. Established organisations explain how local projects are developed with communities."}],"activity":{"text":"Explore a sanitation organisation’s projects and choose an educational or campaigning action you can take.","label":"Explore WaterAid’s work","url":"https://www.wateraid.org/uk/get-involved"},"sources":[{"label":"United Nations: World Toilet Day","url":"https://www.un.org/en/observances/toilet-day","dateEvidence":true},{"label":"WaterAid: ways to get involved","url":"https://www.wateraid.org/uk/get-involved","dateEvidence":false}]},"2026-11-20:national-peanut-butter-fudge-day":{"id":"2026-11-20:national-peanut-butter-fudge-day","date":"2026-11-20","verification":"independent-calendar","summary":"Peanut butter and fudge have agreed to share the spotlight. 🥜 This informal US food date on 20 November celebrates the rich, nutty confection, whether you prefer smooth squares or a little added crunch.","sections":[{"heading":"One flavour in a wider fudge family","body":"National Peanut Butter Fudge Day is recorded separately from the broader National Fudge Day in June. Fudge has a long place in American confectionery, but the creator of this particular calendar observance is not well established. The date is a food-calendar celebration rather than a public holiday or an instruction to follow one official recipe."},{"heading":"A small batch with a big personality","body":"Peanut butter can provide both flavour and texture, with smooth or crunchy versions producing a different finish. Recipes vary in method, ingredients and how they set, so choose one that suits the equipment and time you have. If sharing a batch, clearly mention the peanuts and other allergens. A few neatly wrapped pieces can make an appealing homemade gift."}],"activity":{"text":"Try a peanut butter fudge recipe and package a few pieces for someone who enjoys it.","label":"Make peanut butter fudge","url":"https://www.bbcgoodfood.com/recipes/peanut-butter-fudge"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-peanut-butter-fudge-day-november-20","dateEvidence":true},{"label":"Good Food: peanut butter fudge","url":"https://www.bbcgoodfood.com/recipes/peanut-butter-fudge","dateEvidence":false}]},"2026-11-21:family-volunteer-day":{"id":"2026-11-21:family-volunteer-day","date":"2026-11-21","verification":"organiser","summary":"Put a useful hour on the family calendar. Family Volunteer Day takes place on Saturday 21 November in 2026, bringing different generations together to help their communities through practical projects and shared effort.","sections":[{"heading":"An organiser-confirmed 2026 date","body":"Points of Light invites families to take part on 21 November 2026, with in-person and virtual opportunities. The idea is to volunteer together, helping people see how their different skills can contribute to a shared task. The organiser offers project guides and an opportunities platform rather than a single event that everyone must attend."},{"heading":"Choose the task before collecting the supplies","body":"A useful family project starts with what a community organisation actually needs. Ask about age limits, accessibility, supervision and the items or time requested. Writing cards, making agreed care packages or helping with an organised local activity may be suitable, but check first. Give everyone a manageable role and allow time afterwards to talk about what you learned from doing the work."}],"activity":{"text":"Choose one of the organiser’s family-friendly project guides, then check what a local organisation needs.","label":"Find a family project","url":"https://www.pointsoflight.org/family-volunteer-day/"},"sources":[{"label":"Points of Light: Family Volunteer Day 2026","url":"https://www.pointsoflight.org/family-volunteer-day/","dateEvidence":true}]},"2026-11-23:doctor-who-day":{"id":"2026-11-23:doctor-who-day","date":"2026-11-23","verification":"organiser","summary":"A blue box, impossible journeys and a very long television story. 🛸 Doctor Who Day marks 23 November, the anniversary of the programme’s first BBC broadcast in 1963, and gives fans a reason to revisit it.","sections":[{"heading":"Why 23 November?","body":"The first episode aired on BBC television at 5.15pm on 23 November 1963. Anniversary celebrations have made that date especially meaningful to the programme’s audience. The official Doctor Who site explains how later anniversary adventures brought different incarnations of the Doctor together, turning the show’s changing cast and history into part of its storytelling."},{"heading":"Your first episode is allowed","body":"You do not need to know every Doctor, companion or continuity puzzle to take part. Revisit a favourite story, ask a fan which accessible adventure they would recommend, or explore an official clip or feature. The enjoyable bit is discovering what appeals to you: a strange new world, a clever problem, a memorable monster, or the people travelling through it."}],"activity":{"text":"Explore the official anniversary feature and its clips, then choose one Doctor Who story to try.","label":"Explore Doctor Who Day","url":"https://www.doctorwho.tv/news-and-features/why-is-november-23rd-doctor-who-day"},"sources":[{"label":"BBC Studios: why 23 November is Doctor Who Day","url":"https://www.doctorwho.tv/news-and-features/why-is-november-23rd-doctor-who-day","dateEvidence":true}]},"2026-11-24:national-fairy-bread-day":{"id":"2026-11-24:national-fairy-bread-day","date":"2026-11-24","verification":"organiser","summary":"Butter, bread and hundreds-and-thousands: a surprisingly complete party plan. 🌈 Fairy Bread Day is celebrated on 24 November, with an Australian campaign that turns childhood-party nostalgia into support for children in foster care.","sections":[{"heading":"From a playful idea to a campaign","body":"The organisers trace Fairy Bread Day to Adam Schell suggesting a celebration in 2014. Dollar Sweets supports the event, and its current campaign benefits The Pyjama Foundation. The date is 24 November; the familiar food is buttered bread covered with small colourful sprinkles. It is a community and fundraising occasion rather than a public holiday."},{"heading":"Keep it wonderfully uncomplicated","body":"Fairy bread is associated with Australian and New Zealand children’s parties, where the point is colour and enjoyment rather than complicated baking. You can make a few traditional triangles, compare sprinkle combinations, or try one of the organiser’s creative variations. If joining a fundraiser, use the published event information and make sure the people sharing your food know its ingredients."}],"activity":{"text":"Make a plate of fairy bread or try a sprinkle-covered variation from the campaign’s recipe ideas.","label":"Try fairy bread ideas","url":"https://www.dollarsweets.com/fairy-bread-day-recipes"},"sources":[{"label":"Fairy Bread Day: official campaign","url":"https://www.fairybreadday.com/","dateEvidence":true},{"label":"Fairy Bread Day: history","url":"https://www.fairybreadday.com/our-history","dateEvidence":true},{"label":"Dollar Sweets: recipe ideas","url":"https://www.dollarsweets.com/fairy-bread-day-recipes","dateEvidence":false}]},"2026-11-25:national-jukebox-day":{"id":"2026-11-25:national-jukebox-day","date":"2026-11-25","verification":"organiser","summary":"Someone gets to choose the next song. 🎶 National Jukebox Day falls on the day before US Thanksgiving—25 November in 2026—celebrating the shared soundtrack of bars, cafés and memorable nights out.","sections":[{"heading":"A celebration with a music-industry founder","body":"TouchTunes founded National Jukebox Day to recognise the machines that let customers select music for a shared space. The day-before-Thanksgiving rule gives it a changing date. The company’s 2026 announcement explicitly places it on Wednesday 25 November, so it should not be fixed to the 23rd just because the first celebration fell then."},{"heading":"From one chosen record to a whole catalogue","body":"Older jukeboxes offered a physical selection of recordings; networked digital versions can provide a much larger catalogue. In either case, choosing a song means sharing it with the room. Try remembering a track you associate with a particular place, or make a short collaborative playlist where everyone gets one choice and nobody quietly replaces the whole queue."}],"activity":{"text":"Make a five-song shared jukebox playlist: give each person one pick and listen to the whole selection.","label":"Explore jukebox favourites","url":"https://www.touchtunes.com/touchtunes-year-end-charts-reveal-americas-top-soundtracks"},"sources":[{"label":"TouchTunes: 2026 announcement and Jukebox Day date","url":"https://www.touchtunes.com/touchtunes-year-end-charts-reveal-americas-top-soundtracks","dateEvidence":true},{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-jukebox-day-day-before-thanksgiving/","dateEvidence":true}]},"2026-11-26:good-grief-day":{"id":"2026-11-26:good-grief-day","date":"2026-11-26","verification":"independent-calendar","summary":"Good grief, it is a cartoonist’s birthday. 🐾 This informal 26 November observance honours Charles M. Schulz and Peanuts—the comic world of Charlie Brown, Snoopy and a remarkably persistent football joke.","sections":[{"heading":"A birthday tribute, not a grief campaign","body":"Schulz was born on 26 November 1922. Independent calendars use his birthday for Good Grief Day, referring to the expression associated with his characters. The Charles M. Schulz Museum documents his life and work. This particular November occasion should not be confused with bereavement-support campaigns that may use similar language."},{"heading":"Look at how a little strip works","body":"Peanuts makes room for disappointment, friendship, imagination and the strange logic of everyday life within a few panels. Read a short run of strips and notice the timing: a pause, a facial expression or the last panel can carry the whole joke. If you prefer making something, draw a four-panel comic about a tiny frustration without needing polished illustration skills."}],"activity":{"text":"Read a few Peanuts strips or draw your own four-panel comic about a very small everyday disaster.","label":"Explore Schulz’s life","url":"https://schulzmuseum.org/about-schulz/schulz-biography/"},"sources":[{"label":"Charles M. Schulz Museum: biography","url":"https://schulzmuseum.org/about-schulz/schulz-biography/","dateEvidence":false},{"label":"Checkiday: Good Grief Day","url":"https://www.checkiday.com/f1ef7481f88bfad33dcf841605548101/good-grief-day","dateEvidence":true}],"researchNote":"Some calendar descriptions incorrectly confuse this Schulz birthday tribute with bereavement awareness; the in-app copy distinguishes them."},"2026-11-28:small-business-saturday":{"id":"2026-11-28:small-business-saturday","date":"2026-11-28","verification":"organiser","summary":"Independent shops and neighbourhood favourites get a shared spotlight. Small Business Saturday takes place on 28 November in the United States in 2026, encouraging support for smaller businesses during the busy holiday shopping season.","sections":[{"heading":"A specific US shopping date","body":"American Express founded the campaign in 2010, and the US Small Business Administration has cosponsored it since 2011. It follows the Saturday after Thanksgiving, making 28 November the 2026 date. The UK runs a separate Small Business Saturday campaign on a different date, so the two should not be treated as one worldwide holiday."},{"heading":"Support can be more than shopping","body":"Visit an independent business you already value, choose a nearby café when you would have bought a drink anyway, or leave a useful and honest review. Sharing opening hours or recommending a genuinely good service can also help. A campaign is not a reason to spend money you had not intended to spend; thoughtful attention counts as well."}],"activity":{"text":"Recommend one independent shop or service you genuinely like, or leave it a specific, helpful review.","label":"See the US campaign","url":"https://www.sba.gov/about-sba/organization/observances/small-business-saturday/"},"sources":[{"label":"US Small Business Administration: 2026 date","url":"https://www.sba.gov/about-sba/organization/observances/small-business-saturday/","dateEvidence":true},{"label":"American Express: Shop Small","url":"https://www.americanexpress.com/en-us/benefits/shop-small/","dateEvidence":true}]},"2026-11-29:international-jaguar-day":{"id":"2026-11-29:international-jaguar-day","date":"2026-11-29","verification":"organiser","summary":"The Americas’ largest wild cat needs room to roam. International Jaguar Day, on 29 November, highlights jaguars, the habitats linking their populations and the communities working to protect this remarkable predator.","sections":[{"heading":"Why corridors matter","body":"Conservation is not only about protecting isolated patches of habitat. Jaguars need connected landscapes that allow animals to move between areas. The international campaign brings attention to these corridors and to cooperation across the species’ range, from Mexico towards Argentina. Protecting those wider landscapes can benefit many other plants and animals sharing them."},{"heading":"A day rooted in conservation cooperation","body":"The call for an International Jaguar Day emerged from the Jaguar 2030 Forum in 2018, where representatives of range countries and conservation partners discussed shared action. The day is observed annually on 29 November. Its focus includes habitat protection, reducing conflict with people and involving local communities, rather than treating a photograph of a beautiful cat as the whole conservation story."}],"activity":{"text":"Explore the Jaguar Corridor map and learn why a route between habitats can matter as much as one reserve.","label":"Explore Jaguar Day","url":"https://www.internationaljaguarday.org/"},"sources":[{"label":"International Jaguar Day: campaign and roadmap","url":"https://www.internationaljaguarday.org/","dateEvidence":true}]},"2026-11-30:national-mousse-day":{"id":"2026-11-30:national-mousse-day","date":"2026-11-30","verification":"independent-calendar","summary":"Light, airy, creamy: mousse is doing impressive things with bubbles. 🍫 National Mousse Day is an informal US food-calendar occasion on 30 November, and it welcomes savoury versions as well as chocolate dessert pots.","sections":[{"heading":"What makes it a mousse?","body":"The French word mousse means foam. In cooking, a mousse gets its characteristic texture by incorporating air, often through whipped cream or egg whites, although recipes use different ingredients and techniques. Chocolate is a familiar version, but fruit, coffee and savoury flavours can also be used. A mousse can be served alone or as a filling."},{"heading":"Try texture as well as flavour","body":"An airy mousse and a dense pudding can taste very different even when both are chocolate-based. A small home-made batch lets you notice that difference. Follow a tested recipe, allow any requested chilling time and choose a topping that adds contrast, such as fruit or a little grated chocolate. The origin of the November observance itself is not firmly documented."}],"activity":{"text":"Make individual chocolate mousses and give each one a different finishing touch.","label":"Try chocolate mousse","url":"https://www.bbcgoodfood.com/recipes/easy-chocolate-mousse"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-mousse-day-november-30","dateEvidence":true},{"label":"Good Food: chocolate mousse","url":"https://www.bbcgoodfood.com/recipes/easy-chocolate-mousse","dateEvidence":false}]},"2026-12-02":{"id":"2026-12-02","date":"2026-12-02","verification":"organiser","summary":"Excellent ears, interesting family trees, very good dogs. 🐶 National Mutt Day celebrates mixed-breed dogs on 2 December, encouraging appreciation for them and attention to the shelters helping dogs find suitable homes.","sections":[{"heading":"Mixed breed is not a lesser category","body":"Animal-welfare advocate Colleen Paige promotes National Mutt Day, also called Mixed Breed Dog Day, with observances on 2 December and 31 July. The idea is to recognise dogs without pedigree status and draw attention to adoption. The day is an animal-awareness campaign, rather than a public holiday or an instruction to adopt on impulse."},{"heading":"Help in a way that fits","body":"A dog’s needs, temperament and history matter more than making a quick choice from a photograph. Rehoming organisations can explain their matching process, ongoing costs and support. If adoption is not right for you, ask a rescue about a specific item it needs, share an accurate appeal, or spend a little extra attentive time with a dog you already know."}],"activity":{"text":"Read how a rescue organisation matches dogs with homes, or ask a local shelter what help would be useful.","label":"Explore rescue-dog adoption","url":"https://www.rspca.org.uk/findapet/adopt/dog"},"sources":[{"label":"Colleen Paige: National Mutt Day dates","url":"https://www.colleenpaige.com/","dateEvidence":true},{"label":"RSPCA: adopting a rescue dog","url":"https://www.rspca.org.uk/findapet/adopt/dog","dateEvidence":false}]},"2026-12-03:make-a-gift-day":{"id":"2026-12-03:make-a-gift-day","date":"2026-12-03","verification":"independent-calendar","summary":"A thoughtful present does not need a shopping receipt. 🎁 Make a Gift Day is an informal occasion on 3 December for making something personal, from a tiny handwritten booklet to a homemade edible treat.","sections":[{"heading":"An invitation to make, not a skills test","body":"The date appears in independent calendars as a prompt for handmade gifts ahead of the festive season. Its creator is not securely documented, and there is no official project everyone is expected to copy. The useful idea is to put time and attention into something suited to the person receiving it, rather than aiming for a flawless craft-market finish."},{"heading":"Start with the person, then choose the project","body":"Think about something they would use or enjoy: a bookmark for a reader, a playlist with a note, a recipe card, or a small batch of food they like. Choose a project you can finish with materials you already have. If gifting food, include ingredients and storage information, and check whether the recipient has allergies before choosing the recipe."}],"activity":{"text":"Make a small personalised gift; a batch of rocky road and a handwritten note is one approachable option.","label":"Try an edible gift","url":"https://www.bbcgoodfood.com/recipes/easy-rocky-road"},"sources":[{"label":"Time and Date: Make a Gift Day","url":"https://www.timeanddate.com/holidays/fun/make-a-gift-day","dateEvidence":true},{"label":"Good Food: easy rocky road","url":"https://www.bbcgoodfood.com/recipes/easy-rocky-road","dateEvidence":false}]},"2026-12-05":{"id":"2026-12-05","date":"2026-12-05","verification":"organiser","summary":"For the people who keep showing up. International Volunteer Day, on 5 December, recognises voluntary work and the contribution people make to their communities, from informal neighbourly help to organised local and international projects.","sections":[{"heading":"A United Nations observance","body":"The UN General Assembly established International Volunteer Day for Economic and Social Development in 1985. Governments, volunteer organisations and communities use 5 December to recognise volunteers and encourage participation. It is an opportunity to acknowledge the work already happening, as well as invite new people to contribute skills and time in ways that communities actually want."},{"heading":"Good volunteering begins with a good match","body":"Consider the time, interests and access needs you bring, then ask an organisation what its role involves. Some tasks need training, safeguarding checks or a longer commitment; others can be short and practical. Reliable help is usually more useful than an ambitious promise. You can also recognise a volunteer you know with a specific thank-you that names what their contribution has made possible."}],"activity":{"text":"Choose a realistic volunteering role or thank someone for a particular task they regularly do for others.","label":"Explore volunteer participation","url":"https://www.unv.org/"},"sources":[{"label":"UN Volunteers: founding resolution and date","url":"https://www.unv.org/publications/unga-resolution-40212-adoption-5-december-international-volunteer-day-economic-and","dateEvidence":true},{"label":"United Nations: Volunteer Day background","url":"https://www.un.org/en/observances/volunteer-day/background","dateEvidence":true}]},"2026-12-06:mitten-tree-day":{"id":"2026-12-06:mitten-tree-day","date":"2026-12-06","verification":"independent-calendar","summary":"A winter tree can hold something more useful than decorations. Mitten Tree Day, on 6 December, is an informal occasion associated with collecting mittens and other warm items for people who need them.","sections":[{"heading":"The idea behind a mitten tree","body":"Schools, community groups and places of worship sometimes hang donated mittens or gloves on a tree before distributing them through a local organisation. The visual display makes a collection easy to understand and join. Although the observance is linked with a children’s book in some accounts, references to mitten-tree collections predate that book, so a neat single origin story is uncertain."},{"heading":"Ask before filling the branches","body":"Find out which items, sizes and conditions a receiving organisation requests before collecting anything. New gloves, hats or socks may be more useful than an attractive assortment nobody can distribute. Keep pairs together and avoid making assumptions about the people receiving them. A small, well-matched collection can be more helpful than a large one that leaves someone else with sorting and storage problems."}],"activity":{"text":"Contact a local winter-clothing collection and ask which item or size it needs most before donating.","label":"Explore mitten-tree ideas","url":"https://nationaldaycalendar.com/celebrations/mitten-tree-day-december-6/"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/mitten-tree-day-december-6/","dateEvidence":true}]},"2026-12-08:bodhi-day":{"id":"2026-12-08:bodhi-day","date":"2026-12-08","verification":"organiser","summary":"Bodhi Day commemorates the Buddha’s awakening in some Buddhist traditions. Many Japanese Zen communities observe it on 8 December, while other Buddhist communities follow different calendars or mark enlightenment within other festivals.","sections":[{"heading":"Why you may also hear Rōhatsu","body":"In Japanese Zen contexts, Rōhatsu refers to the eighth day of the twelfth month. The observance remembers Siddhartha Gautama’s awakening, through which he became known as the Buddha. Some communities hold an intensive period of practice leading up to the date. This December entry represents that particular calendar tradition, not a single festival schedule followed by every Buddhist."},{"heading":"Approach the tradition with curiosity","body":"A community’s own explanation is a good starting point for understanding its ceremonies and practice. You might listen to a public talk, learn about the significance of the Bodhi tree, or read a temple’s account of the day. If visiting a service or meditation session, check whether visitors are welcome and follow the hosts’ instructions rather than treating the occasion as a performance."}],"activity":{"text":"Read a Zen community’s account of Bodhi Day and look for an open introductory talk if you are curious.","label":"Read a community’s account","url":"https://www.mnzencenter.org/blog/december-8-bodhi-day"},"sources":[{"label":"Minnesota Zen Meditation Center: Bodhi Day","url":"https://www.mnzencenter.org/blog/december-8-bodhi-day","dateEvidence":true},{"label":"Buddhist Society of Australia: calendars and meaning","url":"https://buddhistsocietiesofaustralia.org/topics/bodhi-day/","dateEvidence":true}],"researchNote":"The 8 December date applies to particular Mahayana/Zen observances; Buddhist calendars and customs vary."},"2026-12-10":{"id":"2026-12-10","date":"2026-12-10","verification":"organiser","summary":"Human rights belong to people because they are human. Human Rights Day, on 10 December, marks the adoption of the Universal Declaration of Human Rights in 1948 and invites attention to dignity in everyday life.","sections":[{"heading":"The document behind the date","body":"The UN General Assembly proclaimed the Universal Declaration of Human Rights in Paris on 10 December 1948. It set out fundamental rights intended for everyone, across differences such as nationality, religion, language and social background. The anniversary is observed annually, connecting the declaration’s principles with work to protect people’s rights in practice."},{"heading":"Read one right slowly","body":"The declaration is more useful when its articles become understandable rather than ceremonial. Choose one and consider an ordinary setting where it matters: education, work, privacy, expression or equal treatment. Notice whose perspective you have not heard. The day can be a prompt to learn from credible human-rights organisations and affected communities, without assuming that one quick conversation resolves a complicated situation."}],"activity":{"text":"Read an article of the Universal Declaration and discuss one concrete example of why it matters.","label":"Explore the declaration","url":"https://www.un.org/en/about-us/universal-declaration-of-human-rights"},"sources":[{"label":"United Nations: Human Rights Day","url":"https://www.un.org/observances/human-rights-day/","dateEvidence":true},{"label":"United Nations: Universal Declaration","url":"https://www.un.org/en/about-us/universal-declaration-of-human-rights","dateEvidence":false}]},"2026-12-11:national-have-a-bagel-day":{"id":"2026-12-11:national-have-a-bagel-day","date":"2026-12-11","verification":"independent-calendar","summary":"A chewy ring of bread and a favourite filling make a solid little celebration. 🥯 National Have a Bagel Day is an informal 11 December food date, separate from January’s better-known National Bagel Day.","sections":[{"heading":"Two similar names, different calendar entries","body":"Independent food calendars record Have a Bagel Day on 11 December. It should not be moved to January simply because National Bagel Day is now widely marked on 15 January. The December observance has no firmly established founder; it is best understood as a light-hearted invitation to appreciate the food rather than an official national holiday."},{"heading":"Why the texture stands out","body":"Traditional bagel-making includes boiling shaped dough before baking, helping create the distinctive crust and chewy interior. There are many styles, seasonings and fillings, with important roots in Jewish food traditions. Enjoy one fresh from a bakery, try a different savoury topping, or make a batch if you fancy a bread project. Breakfast is optional: a bagel is equally capable of being lunch."}],"activity":{"text":"Try a bakery bagel with a new filling, or learn the boiling-and-baking method with a tested recipe.","label":"Make homemade bagels","url":"https://www.bbcgoodfood.com/recipes/edds-bagels"},"sources":[{"label":"Checkiday: Have a Bagel Day, 11 December","url":"https://www.checkiday.com/12527454f5d27ccdf75275fdde5f7d1c/national-have-a-bagel-day","dateEvidence":true},{"label":"Good Food: homemade bagels","url":"https://www.bbcgoodfood.com/recipes/edds-bagels","dateEvidence":false}],"researchNote":"Kept as Have a Bagel Day on 11 December; this is distinct from National Bagel Day on 15 January."},"2026-12-13:saint-lucia-s-day":{"id":"2026-12-13:saint-lucia-s-day","date":"2026-12-13","verification":"organiser","summary":"Candles, songs and a little light in the winter dark. Saint Lucia’s Day is observed on 13 December, with especially familiar Swedish traditions of white-clad processions and saffron buns shared around the celebration.","sections":[{"heading":"A tradition with several layers","body":"Nordiska museet describes Lucia as a tradition shaped by different places, periods and beliefs. The saint’s name and feast day are part of the story, alongside Swedish folk customs and later public celebrations. Today’s familiar candle-crowned figure and singing procession should not be mistaken for a form that has remained unchanged for centuries."},{"heading":"Listen for the occasion","body":"Lucia celebrations appear in settings such as schools, workplaces, churches and homes, with songs and candlelight creating their distinctive atmosphere. Saffron buns called lussekatter are strongly associated with the season. Watching a performance or listening to a Lucia song can be an inviting introduction. If visiting a celebration, let the hosts explain what the occasion means in their particular community."}],"activity":{"text":"Listen to a Lucia song and explore how the modern procession developed through the museum’s illustrated guide.","label":"Explore Lucia traditions","url":"https://www.nordiskamuseet.se/en/traditions-celebrations/lucia/"},"sources":[{"label":"Nordiska museet: Lucia history and traditions","url":"https://www.nordiskamuseet.se/en/traditions-celebrations/lucia/","dateEvidence":true},{"label":"Visit Sweden: Lucia","url":"https://visitsweden.com/what-to-do/culture-history-and-art/swedish-traditions/christmas/lucia/","dateEvidence":true}]},"2026-12-15":{"id":"2026-12-15","date":"2026-12-15","verification":"independent-calendar","summary":"A whole little cake with room for a ridiculous swirl of icing. 🧁 National Cupcake Day appears in US food calendars on 15 December, giving individual cakes their own excuse for a celebration.","sections":[{"heading":"Small cakes, many forms","body":"Cupcakes have a history in individual baking cups and in recipes measured by cups, although the history of the December food day itself is less clear. National Day Calendar records the date while continuing to research the observance’s origins. It is a general cupcake occasion, distinct from November’s specifically vanilla-flavoured celebration."},{"heading":"Make the decorating the activity","body":"A batch of plain cakes can become several different creations with a few toppings. Set out a little icing, fruit, chocolate shavings or sprinkles and let each person decorate one. You can keep the baking simple and spend the effort on playful finishing touches. If sharing, check ingredients and remember that not everyone wants a mountain of buttercream; leaving a few plain is considerate."}],"activity":{"text":"Bake a simple batch and turn decorating into a mini cupcake workshop with a friend.","label":"Try a cupcake recipe","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cupcakes"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-cupcake-day-december-15","dateEvidence":true},{"label":"Good Food: easy vanilla cupcakes","url":"https://www.bbcgoodfood.com/recipes/easy-vanilla-cupcakes","dateEvidence":false}]},"2026-12-16:las-posadas-begins":{"id":"2026-12-16:las-posadas-begins","date":"2026-12-16","verification":"organiser","summary":"Las Posadas begins a nine-night season of processions, songs and hospitality in Mexico and other communities. The traditional period runs from 16 to 24 December, recalling Mary and Joseph’s search for lodging before Jesus’s birth.","sections":[{"heading":"A journey expressed through welcome","body":"The Spanish name refers to inns or lodgings. In many celebrations, participants reenact the search for a place to stay through movement and call-and-response singing, followed by welcome and a gathering. It is a religious tradition with local variations, and events in churches, neighbourhoods and families do not all follow an identical programme."},{"heading":"Music and food carry the occasion","body":"Carols, shared dishes and time together are important parts of many Posadas celebrations. The Smithsonian’s recordings and cultural accounts offer ways to hear the songs and understand their setting. This calendar lists the beginning only, with the full 16–24 December range here. A community may hold a particular public event on a different evening within or near that period."}],"activity":{"text":"Listen to traditional Posadas songs through the Smithsonian collection and learn the meaning of the welcome they enact.","label":"Hear Las Posadas songs","url":"https://www.si.edu/collections/snapshot/las-posadas"},"sources":[{"label":"US Conference of Catholic Bishops: 16 December","url":"https://www.usccb.org/prayer-and-worship/liturgical-year/advent/advent-december-16","dateEvidence":true},{"label":"Smithsonian: music and foodways","url":"https://folklife.si.edu/magazine/foodways-holidays-las-posadas","dateEvidence":true},{"label":"Smithsonian: traditional sounds","url":"https://www.si.edu/collections/snapshot/las-posadas","dateEvidence":false}]},"2026-12-18:arabic-language-day":{"id":"2026-12-18:arabic-language-day","date":"2026-12-18","verification":"organiser","summary":"Arabic carries poetry, conversation, calligraphy and centuries of knowledge across many communities. World Arabic Language Day is observed on 18 December, recognising the language’s cultural richness and its place among the United Nations’ official languages.","sections":[{"heading":"Why 18 December?","body":"The date recalls the UN General Assembly’s decision on 18 December 1973 to include Arabic among its official and working languages. UNESCO has celebrated World Arabic Language Day annually since 2012. The occasion gives institutions and communities a shared moment to explore language, creativity and communication rather than reducing Arabic to a single country or one cultural identity."},{"heading":"One language, a rich variety of expression","body":"Arabic is used in different spoken varieties as well as written and formal settings. Poetry, songs and calligraphic art offer different ways to encounter that range. Start with a short recording, a translated poem or a greeting, and notice how the language is used by the person presenting it. Learning a little context is more rewarding than collecting isolated words without hearing them."}],"activity":{"text":"Explore UNESCO’s Arabic-language resources, then find a short poem or recording to listen to with a translation.","label":"Explore Arabic language and culture","url":"https://www.unesco.org/en/world-arabic-language-day"},"sources":[{"label":"UNESCO: World Arabic Language Day","url":"https://www.unesco.org/en/world-arabic-language-day","dateEvidence":true},{"label":"United Nations: Arabic Language Day","url":"https://www.un.org/en/observances/arabiclanguageday","dateEvidence":true}],"title":"World Arabic Language Day"},"2026-12-20":{"id":"2026-12-20","date":"2026-12-20","verification":"organiser","summary":"Some challenges need people to act together. International Human Solidarity Day, on 20 December, highlights unity in diversity and cooperation in addressing shared problems, including poverty and unequal access to opportunities.","sections":[{"heading":"A shared value, recognised by the UN","body":"The UN General Assembly proclaimed the day in 2005, affirming solidarity as a value that should guide relations between people and communities. It is observed annually on 20 December. The occasion links broad international commitments with the practical idea that people should not be left to face poverty and other major disadvantages entirely on their own."},{"heading":"Find a concrete form of cooperation","body":"Solidarity becomes clearer when attached to an actual task: a community project, mutual support, accessible services or people working towards a shared goal. Begin by listening to the people involved and finding out what is needed. Cooperation is not the same as speaking for everyone; useful participation respects differences, shares responsibility and makes room for those whose lives are most affected."}],"activity":{"text":"Ask a community project what practical support it needs, and choose one contribution you can reliably make.","label":"Explore the day’s purpose","url":"https://www.gov.za/HumanSolidarityDay2026"},"sources":[{"label":"United Nations: Human Solidarity Day","url":"https://www.un.org/en/observances/human-solidarity-day","dateEvidence":true},{"label":"South African Government: 2026 observance","url":"https://www.gov.za/HumanSolidarityDay2026","dateEvidence":true}]},"2026-12-21:national-short-story-day":{"id":"2026-12-21:national-short-story-day","date":"2026-12-21","verification":"independent-calendar","summary":"A short day can hold a whole story. 📖 National Short Story Day is an informal reading occasion associated with the northern winter solstice, falling on 21 December in the UK in 2026.","sections":[{"heading":"Why short stories and the shortest day?","body":"The occasion pairs a compact literary form with the short daylight of the northern winter season. Independent calendars place the 2026 observance on 21 December, and an earlier UK campaign encouraged readings and participation around that date. It is a literary celebration rather than a public holiday, and the shortest-day association depends on hemisphere and calendar year."},{"heading":"Choose one complete reading experience","body":"A short story can let you meet a place, problem or character and reach an ending in one sitting. Pick something that fits the time you actually have, then put your phone aside until you finish. Afterwards, notice what stayed with you: a surprising turn, a particular sentence, or an ending that leaves you thinking. You could also try writing a very short scene of your own."}],"activity":{"text":"Read The Gift of the Magi in O. Henry’s free collection The Four Million, or choose another complete short story.","label":"Read The Gift of the Magi","url":"https://en.wikisource.org/wiki/The_Four_Million/The_Gift_of_the_Magi"},"sources":[{"label":"Checkiday: 2026 winter-date observance","url":"https://www.checkiday.com/b3d533c1a9b028b292ad5529cca78066/national-short-story-day","dateEvidence":true},{"label":"The Short Story: original UK campaign listing","url":"https://www.theshortstory.org.uk/events/","dateEvidence":true},{"label":"Project Gutenberg: The Four Million","url":"https://www.gutenberg.org/ebooks/2776","dateEvidence":false}]},"2026-12-23":{"id":"2026-12-23","date":"2026-12-23","verification":"independent-calendar","summary":"A very low-decoration celebration for anyone enjoying the joke. Festivus is marked on 23 December after being popularised by Seinfeld, with an aluminium pole, exaggerated grievances and a determined rejection of festive fuss.","sections":[{"heading":"From family custom to television","body":"The television version appeared in the Seinfeld episode The Strike, first broadcast in December 1997. Writer Dan O’Keefe drew on an unusual celebration from his own family, then adapted it for the show. December 23 is the date associated with the fictional version, which later became an informal real-world occasion for viewers."},{"heading":"Keep the joke kinder than the sitcom","body":"Fans recognise the undecorated pole, the airing of grievances and feats of strength as part of the comic tradition. You do not need to copy every element literally. A relaxed meal, some deliberately trivial complaints and an affectionate toast can capture the spirit without turning the evening into a real argument or a wrestling contest that nobody wanted."}],"activity":{"text":"Hold a wonderfully unfussy get-together and invite complaints only about harmless things, such as missing socks or tangled cables.","label":"Explore Festivus folklore","url":"https://blogs.loc.gov/folklife/2020/12/festivus-and-family-lore/"},"sources":[{"label":"Library of Congress: Festivus and family lore","url":"https://blogs.loc.gov/folklife/2020/12/festivus-and-family-lore/","dateEvidence":true},{"label":"History: Festivus origins","url":"https://www.history.com/articles/festivus-meaning","dateEvidence":true}]},"2026-12-24:national-eggnog-day":{"id":"2026-12-24:national-eggnog-day","date":"2026-12-24","verification":"independent-calendar","summary":"A creamy drink with a distinctly festive personality. National Eggnog Day appears in US food calendars on 24 December, celebrating the milk-and-egg drink often finished with warming spices and served with or without alcohol.","sections":[{"heading":"What is in the glass?","body":"Traditional eggnog combines dairy, eggs and sweetness, often with spices such as nutmeg or cinnamon. Some versions include spirits, while others are alcohol-free or use plant-based ingredients. The drink has a longer history than the calendar observance; the founder of National Eggnog Day is not firmly documented, so this is best treated as an informal seasonal food celebration."},{"heading":"Choose the version that suits the table","body":"Eggnog recipes differ in their methods as well as flavour, so follow a tested recipe and its ingredient and storage advice. A small batch can be served in short glasses with a finishing spice, or a ready-made version can make the occasion effortless. If you are sharing it, make clear which batch contains alcohol and what ingredients it includes."}],"activity":{"text":"Try a tested eggnog recipe, or choose an alcohol-free version for a festive drink everyone at the table can identify.","label":"Try classic eggnog","url":"https://www.bbcgoodfood.com/recipes/classic-eggnog"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/national-eggnog-day-december-24","dateEvidence":true},{"label":"Good Food: classic eggnog","url":"https://www.bbcgoodfood.com/recipes/classic-eggnog","dateEvidence":false}]},"2026-12-26:boxing-day":{"id":"2026-12-26:boxing-day","date":"2026-12-26","verification":"organiser","summary":"The day after Christmas has its own traditions: visits, walks, sport and inventive uses for leftovers. Boxing Day remains 26 December in 2026; the UK substitute bank holiday falls on Monday 28 December.","sections":[{"heading":"The date and the day off are different","body":"In 2026, 26 December falls on a Saturday. GOV.UK therefore lists Monday 28 December as the substitute Boxing Day bank holiday. That changes the weekday holiday arrangement, not the calendar date of Boxing Day itself. Bank-holiday arrangements and the right to time off are also not identical in every workplace, so local schedules still matter."},{"heading":"Traditions without a compulsory itinerary","body":"Boxing Day is observed in the UK and several other countries, with customs ranging from social visits to sporting fixtures and relaxed food. Its name is commonly linked with historical gifts or boxes for workers and people in need, rather than the sport of boxing. You can make it a quieter day without needing to attend a sale, a match or a large gathering."}],"activity":{"text":"Plan a gentle walk or catch-up, and check the actual 2026 bank-holiday dates before arranging work or travel.","label":"Check the UK holiday dates","url":"https://www.gov.uk/bank-holidays"},"sources":[{"label":"GOV.UK: 2026 substitute bank holiday","url":"https://www.gov.uk/bank-holidays","dateEvidence":true},{"label":"Time and Date: Boxing Day date and customs","url":"https://www.timeanddate.com/holidays/uk/boxing-day","dateEvidence":true}],"researchNote":"Boxing Day itself is 26 December; only the substitute UK bank holiday moves to 28 December in 2026."},"2026-12-27:make-cut-out-snowflakes-day":{"id":"2026-12-27:make-cut-out-snowflakes-day","date":"2026-12-27","verification":"independent-calendar","summary":"Some folded paper and a few careful snips can produce a surprisingly elaborate winter decoration. ❄️ Make Cut-Out Snowflakes Day is an informal creative occasion on 27 December, ideal for using up spare wrapping paper.","sections":[{"heading":"The reveal is half the fun","body":"Folding paper before cutting repeats shapes around the finished design. Change one notch or curve and you can get a completely different result when it opens. Paper snowflakes are a craft, rather than replicas of every detail of a natural ice crystal, so a slightly wonky result has not failed an examination."},{"heading":"Try a design with a twist","body":"The Natural History Museum offers free animal-inspired templates and instructions, making the activity more interesting than repeating one familiar pattern. You can also start with scrap paper and invent a shape. Leave enough connected paper to hold the design together, work on a clear surface and give children appropriate help with scissors. Lay the finished flakes flat before displaying them."}],"activity":{"text":"Choose one of the Natural History Museum’s animal snowflake templates and make a small paper menagerie.","label":"Make an animal snowflake","url":"https://www.nhm.ac.uk/discover/how-to-make-animal-paper-snowflakes.html"},"sources":[{"label":"National Day Calendar","url":"https://nationaldaycalendar.com/celebrations/make-cut-out-snowflakes-day","dateEvidence":true},{"label":"Natural History Museum: free templates and instructions","url":"https://www.nhm.ac.uk/discover/how-to-make-animal-paper-snowflakes.html","dateEvidence":false}]},"2026-12-29:international-cello-day":{"id":"2026-12-29:international-cello-day","date":"2026-12-29","verification":"organiser","summary":"Give the cello the main melody for a moment. 🎻 International Cello Day is observed on 29 December, the birthday of Pau Casals; in 2026, it also marks 150 years since his birth.","sections":[{"heading":"Why Casals is part of the date","body":"Born on 29 December 1876, Pau—or Pablo—Casals was a major cellist, conductor, teacher and advocate for peace. The Pau Casals Foundation is marking his 150th anniversary with activities across 2026 and 2027. International Cello Day uses his birthday as an occasion for players and listeners to celebrate the instrument and its musical possibilities."},{"heading":"Listen beyond the familiar soundtrack","body":"A cello can carry a singing melody, anchor an ensemble or explore a wide range of textures. For a starting point, listen to Casals performing the traditional Catalan song El cant dels ocells, often called The Song of the Birds. He helped make it widely known, but did not compose the folk song. Then compare it with a different performer’s interpretation."}],"activity":{"text":"Listen to The Song of the Birds and compare how two cellists shape the same melody.","label":"Explore the Cello Museum’s recordings","url":"https://cellomuseum.org/celebrate-international-cello-day/"},"sources":[{"label":"Cello Museum: International Cello Day and recordings","url":"https://cellomuseum.org/celebrate-international-cello-day/","dateEvidence":true},{"label":"Pau Casals Foundation: 150th anniversary in 2026","url":"https://www.paucasals.org/en/casals-150-anniversary/","dateEvidence":true}]},"2026-12-31":{"id":"2026-12-31","date":"2026-12-31","verification":"independent-calendar","summary":"The Gregorian year is nearly out of pages. ✨ New Year’s Eve falls on 31 December, whether you spend it with a countdown, a favourite meal, a few friends or a very sensible early night.","sections":[{"heading":"One date, many local midnights","body":"New Year’s Eve is the last day of the Gregorian calendar year, before 1 January. As midnight arrives in different time zones, celebrations unfold around the world rather than at one simultaneous instant. Other cultural and religious calendars have their own new-year occasions, so this December entry is not a claim that everyone’s year begins in the same way."},{"heading":"Give the evening a shape you actually like","body":"Large public celebrations, fireworks, private gatherings and quiet reflection are all familiar options, but none is required. Choose one manageable thing to enjoy or remember: a meal with someone, a song that belongs to the year, or a note about something you want to keep doing. A useful plan can also include how you will get home or who you want to contact."}],"activity":{"text":"Write one thing you want to carry forward, then make a simple plan for an evening that suits you.","label":"Explore New Year’s Eve around the world","url":"https://www.timeanddate.com/holidays/common/new-year-eve"},"sources":[{"label":"Time and Date: New Year’s Eve","url":"https://www.timeanddate.com/holidays/common/new-year-eve","dateEvidence":true}]},"2026-11-02:all-souls-day":{"id":"2026-11-02:all-souls-day","date":"2026-11-02","verification":"organiser","summary":"A quiet day for remembering people who have died. In the Catholic calendar, 2 November is dedicated to prayer for the faithful departed, with remembrance taking different forms in different communities.","sections":[{"heading":"Who is remembered?","body":"All Souls’ Day follows All Saints’ Day. The focus turns to the wider community of people who have died, rather than only those recognised as saints. In Catholic belief, prayer expresses continuing care for the departed and the relationship between the living and the dead. Other Christian traditions also have their own practices of remembrance."},{"heading":"A moment that can be personal","body":"Church services and visits to graves are common ways to mark the date, but customs differ between places and families. A private moment can be simple: say a name, look through a photograph album, or recall a story you do not want to lose. There is no need to make grief neat or turn remembrance into a performance."}],"activity":{"text":"Choose a photograph of someone you miss and share one particular memory of them with a person you trust.","label":"About All Souls’ Day","url":"https://dallascatholic.org/all-souls/"},"sources":[{"label":"Catholic Diocese of Dallas","url":"https://dallascatholic.org/all-souls/","dateEvidence":true}]},"2026-11-03:culture-day":{"id":"2026-11-03:culture-day","date":"2026-11-03","verification":"organiser","summary":"Art, science and a little curiosity get a national holiday in Japan. 🎨 Culture Day on 3 November celebrates cultural life, with awards, exhibitions and events around the country.","sections":[{"heading":"Why 3 November?","body":"Japan’s current constitution was announced on 3 November 1946. Culture Day became a holiday two years later, connecting cultural activities with ideals of peace and freedom. The date is separate from Constitution Memorial Day in May, which marks when that constitution came into effect. In 2026, Culture Day falls on a Tuesday."},{"heading":"Culture is a wide subject","body":"The Order of Culture is presented at the Imperial Palace to people with significant achievements in science, art and culture. Around the date, public and private organisations hold festivals and give awards of their own. You can approach the day through something unfamiliar: a craft technique, a musical instrument, an artist or a story from a different Japanese region."}],"activity":{"text":"Choose one Japanese craft or folk story from Web Japan and spend ten minutes discovering how it is made or told.","label":"Explore Japanese culture","url":"https://web-japan.org/kidsweb/explore/calendar/november/culture.html"},"sources":[{"label":"Ministry of Foreign Affairs of Japan — Web Japan","url":"https://web-japan.org/kidsweb/explore/calendar/november/culture.html","dateEvidence":true}]},"2026-11-04:national-advent-calendar-day":{"id":"2026-11-04:national-advent-calendar-day","date":"2026-11-04","verification":"organiser","summary":"The countdown to the countdown starts here. 🗓️ This US retail observance falls on the first Wednesday of November, when ALDI launches its seasonal Advent-calendar range; in 2026, that is 4 November.","sections":[{"heading":"An Advent calendar, not Advent itself","body":"The date celebrates the arrival of calendars in shops, rather than the beginning of the Christian season of Advent. ALDI introduced the named retail day in 2020. Its assortment now stretches beyond chocolate into toys, stationery, baking and other themes. The commercial launch is a modern event, while counting down to Christmas has a much longer history."},{"heading":"Make the surprise your own","body":"You do not need a shop-bought calendar to join the fun. Number twenty-four envelopes and fill them with small drawings, shared memories or suggestions for things to do together. A calendar made for someone’s interests can be more personal than a box of unrelated gifts. Keep the surprises manageable enough that finishing the project is enjoyable, too."}],"activity":{"text":"Write seven tiny surprises for someone you like, put them in numbered envelopes, and make a week-long countdown.","label":"See the calendar tradition","url":"https://corporate.aldi.us/newsroom/news/the-countdown-is-on-aldi-reveals-2026-advent-calendar-lineup"},"sources":[{"label":"ALDI US — 2026 Advent launch","url":"https://corporate.aldi.us/newsroom/news/the-countdown-is-on-aldi-reveals-2026-advent-calendar-lineup","dateEvidence":true},{"label":"Aldi Reviewer — National Advent Calendar Day","url":"https://www.aldireviewer.com/when-is-national-advent-calendar-day/","dateEvidence":true}]},"2026-11-05:national-chinese-takeout-day":{"id":"2026-11-05:national-chinese-takeout-day","date":"2026-11-05","verification":"independent-calendar","summary":"An informal US food day for the dishes that make a takeaway evening feel like a treat. 🥡 It is observed on 5 November and reflects Chinese American restaurant culture, rather than a Chinese public holiday.","sections":[{"heading":"A cuisine shaped by migration","body":"American Chinese takeaway menus have developed around local ingredients, customers and restaurant traditions. They should not stand in for all the regional cuisines of China. Cornell Dining’s 2026 celebration, for example, features dishes such as chow mein, vegetable potstickers and General Tso tofu. The variety is a useful starting point for looking beyond the same familiar order."},{"heading":"Try one new thing","body":"A good way to use the date is to ask a local restaurant what they enjoy cooking, or choose a vegetable dish you usually overlook. A home-cooked noodle supper works just as well. The Woks of Life’s vegetable lo mein uses a flexible selection of vegetables, so the celebration need not involve a large order or lots of specialist ingredients."}],"activity":{"text":"Try vegetable lo mein at home, using the vegetables you already have and the recipe’s noodle and sauce guidance.","label":"Make vegetable lo mein","url":"https://thewoksoflife.com/vegetable-lo-mein/"},"sources":[{"label":"Cornell Dining — 5 November 2026 event","url":"https://events.cornell.edu/event/copy-of-celebrating-national-chinese-takeout-day","dateEvidence":true},{"label":"The Woks of Life — vegetable lo mein","url":"https://thewoksoflife.com/vegetable-lo-mein/","dateEvidence":false}]},"2026-11-07:national-bison-day":{"id":"2026-11-07:national-bison-day","date":"2026-11-07","verification":"organiser","summary":"Meet the animal with a very large place in North American history. 🦬 National Bison Day is held on November’s first Saturday; a US Senate resolution confirms 7 November for the 2026 observance.","sections":[{"heading":"More than a national symbol","body":"Bison are the United States’ national mammal, but their significance reaches far beyond that designation. Many Tribal nations have deep cultural, spiritual and economic relationships with the animals. The 2026 Senate resolution recognises Tribal restoration work alongside the role of public agencies, conservation organisations, herd managers and private producers in caring for bison today."},{"heading":"Restoration includes the landscape","body":"Bison are closely connected with grassland ecosystems, so conserving them also involves habitat and the relationships between people and land. The InterTribal Buffalo Council supports the return of buffalo to Tribal communities. Learning about that work offers a richer picture than treating the animals only as an image on a coin, flag or sports-team logo."}],"activity":{"text":"Read about an Indigenous-led bison restoration effort and notice whose knowledge and priorities guide the work.","label":"Read the 2026 recognition","url":"https://www.govinfo.gov/content/pkg/BILLS-119sres945ats/xhtml/BILLS-119sres945ats.html"},"sources":[{"label":"US Senate — National Bison Day 2026 resolution","url":"https://www.govinfo.gov/content/pkg/BILLS-119sres945ats/xhtml/BILLS-119sres945ats.html","dateEvidence":true},{"label":"Bureau of Indian Affairs — bison and Tribal heritage","url":"https://www.bia.gov/NNAHM","dateEvidence":true}]},"2026-11-08:remembrance-sunday":{"id":"2026-11-08:remembrance-sunday","date":"2026-11-08","verification":"organiser","summary":"A national moment of remembrance for those who served, died and were affected by conflict. Remembrance Sunday falls on 8 November in 2026, with the UK’s Cenotaph service beginning at 11am.","sections":[{"heading":"The Sunday of remembrance","body":"Remembrance Sunday is held on the second Sunday of November. It is distinct from Armistice Day on 11 November, although both belong to the wider period of remembrance. The National Service at the Cenotaph in London brings together military and civilian representatives, while communities across the country hold local services and acts of remembrance."},{"heading":"Ways of taking part","body":"The national ceremony includes a two-minute silence. People may attend a local service, watch the broadcast, read a personal account or mark the moment privately. Remembrance can include listening to experiences different from your own, and reflecting on the lasting effects of war on families and communities. Participation is personal; a quiet act can carry as much meaning as a public one."}],"activity":{"text":"Find the story of someone remembered in your community, or take a quiet moment to reflect on the impact of conflict.","label":"Explore remembrance","url":"https://www.britishlegion.org.uk/get-involved/events/remembrance-events/remembrance-sunday"},"sources":[{"label":"GOV.UK — National Service, 8 November 2026","url":"https://www.gov.uk/guidance/national-service-of-remembrance-sunday-8-november-2026","dateEvidence":true},{"label":"Royal British Legion — Remembrance Sunday","url":"https://www.britishlegion.org.uk/get-involved/events/remembrance-events/remembrance-sunday","dateEvidence":true}]},"2026-11-09:british-pudding-day":{"id":"2026-11-09:british-pudding-day","date":"2026-11-09","verification":"independent-calendar","summary":"Custard at the ready. 🍮 British Pudding Day is an informal 9 November celebration of comforting puddings, from steamed classics to sticky toffee favourites. A proper excuse to give dessert a little attention.","sections":[{"heading":"What counts as pudding?","body":"In British usage, pudding can mean the sweet course at the end of a meal, as well as particular dishes that are steamed, baked or boiled. The date is a contemporary food celebration, not a public holiday. Its appeal is in the range of textures: a crisp pastry edge, a soft sponge, or a warm sauce meeting something cold."},{"heading":"Try a different favourite","body":"You could compare family choices, ask someone which pudding reminds them of home, or make a smaller version of a classic. Falcon Foodservice marks 9 November with a sticky toffee coffee pudding and vanilla toffee sauce recipe. The full method is linked below, so you can follow the timings rather than guessing your way through a steaming basin."}],"activity":{"text":"Choose a pudding you have not made before, or try the linked sticky toffee coffee pudding and share the result.","label":"Try a pudding recipe","url":"https://www.falconfoodservice.com/info-centre/chefs-corner/recipes/pudding-day"},"sources":[{"label":"Falcon Foodservice — British Pudding Day recipe","url":"https://www.falconfoodservice.com/info-centre/chefs-corner/recipes/pudding-day","dateEvidence":true}]},"2026-11-10:international-accounting-day":{"id":"2026-11-10:international-accounting-day","date":"2026-11-10","verification":"organiser","summary":"For the people who turn bewildering figures into something understandable. International Accounting Day on 10 November recognises the accounting profession, including work that helps organisations explain decisions and remain accountable to others.","sections":[{"heading":"Accounting beyond the spreadsheet","body":"Accountants help organisations record transactions, prepare reports and understand their resources. The profession also contributes to broader questions about transparency and the effects of business activity. IFAC has used International Accounting Day to bring accountants together for a discussion of climate action, showing that the work can extend well beyond balancing a familiar set of books."},{"heading":"A little appreciation for invisible work","body":"Much of careful record-keeping goes unnoticed when it is working well. Today can be a chance to ask a colleague about the question behind a report, or thank the person who makes confusing information clearer. If you keep your own records, choose one small sorting task that will make a future conversation easier, without turning the day into a financial overhaul."}],"activity":{"text":"Thank someone who keeps the figures understandable, and ask what piece of their work people most often misunderstand.","label":"Explore the profession’s role","url":"https://www.ifac.org/node/27456"},"sources":[{"label":"IFAC — International Accounting Day discussion","url":"https://www.ifac.org/node/27456","dateEvidence":true},{"label":"ICMAB — annual 10 November observance","url":"https://archive.icmab.gov.bd/international-accounting-day/","dateEvidence":true}]},"2026-11-12:world-usability-day":{"id":"2026-11-12:world-usability-day","date":"2026-11-12","verification":"organiser","summary":"Ever battled an app that seemed determined to confuse you? World Usability Day asks how products and systems can work better for people. In 2026, the main date is Thursday 12 November.","sections":[{"heading":"Making everyday tasks easier","body":"World Usability Day has brought people together on the second Thursday of November since 2005. Designers, researchers and communities explore how technology, services and environments fit the people using them. Usability is about completing a task effectively and comfortably, not simply making a screen attractive or adding more features to it."},{"heading":"Look for the friction","body":"The organiser’s 2026 invitation focuses on a sustainable future with ethical AI. You can start much closer to home: notice where a label is unclear, a button is hard to find, or a form asks for information without explaining why. Describe the actual task and what happened. That makes feedback far more useful than simply saying something feels difficult."}],"activity":{"text":"Pick one confusing app screen and write down the task, the stumbling point and one change that would help.","label":"Explore usability events","url":"https://worldusabilityday.org/"},"sources":[{"label":"World Usability Day — organiser","url":"https://worldusabilityday.org/","dateEvidence":true}]},"2026-11-13:children-in-need":{"id":"2026-11-13:children-in-need","date":"2026-11-13","verification":"organiser","summary":"Pudsey’s annual appeal supports children and young people across the UK. BBC Children in Need Day falls on Friday 13 November in 2026, bringing fundraising activities together with the televised appeal show.","sections":[{"heading":"Where the appeal fits","body":"The charity’s annual appeal invites schools, workplaces and communities to raise funds in ways that suit them. The 2026 live show is broadcast from Salford on BBC One and iPlayer. The day is an opportunity to learn about the projects behind the familiar yellow bear, including the people providing support alongside children and young people."},{"heading":"Take part in a manageable way","body":"The official schools pages provide free ideas and resources for different ages. A fundraiser can be a small shared challenge or a themed activity, rather than a complicated event. Learning about a funded project is also a worthwhile way to understand the appeal. If you join a group activity, make space for people to participate without feeling pressured to give money."}],"activity":{"text":"Choose one official activity idea with your school or colleagues, or read about a project supported by the charity.","label":"See official ideas and resources","url":"https://www.bbcchildreninneed.co.uk/schools/faq/"},"sources":[{"label":"BBC Children in Need — 2026 date and resources","url":"https://www.bbcchildreninneed.co.uk/schools/faq/","dateEvidence":true},{"label":"BBC Children in Need — appeal announcement","url":"https://www.bbcchildreninneed.co.uk/2026/09/bbc-children-in-need-returns/","dateEvidence":true}]},"2026-11-14:national-seat-belt-day":{"id":"2026-11-14:national-seat-belt-day","date":"2026-11-14","verification":"organiser","summary":"A simple habit deserves its own reminder: buckle up on every car journey. National Seat Belt Day is observed on 14 November, following a campaign launched by Volvo Car USA, Uber and GHSA in 2019.","sections":[{"heading":"Every seat, every trip","body":"The campaign was created to address the tendency to skip a seat belt on short journeys or while riding in the back of a taxi or rideshare vehicle. Its message applies to passengers as well as drivers. A journey being familiar, brief or driven by someone else does not make the seat belt an optional part of getting into the car."},{"heading":"Make the pause automatic","body":"Use the date to notice your own routine before the vehicle moves: sit, buckle and check that everyone is ready. It can also prompt a calm conversation with people you regularly travel with. For children or anyone needing a different restraint arrangement, use the vehicle and restraint manufacturer’s guidance rather than improvising. The campaign makes a familiar action worth noticing again, especially on trips where people tend to forget it."}],"activity":{"text":"Make fastening your seat belt the first step of your next car journey, including if you sit in the back.","label":"Read the founding campaign","url":"https://www.volvocars.com/us/media/press-releases/96EB870D60DBFA0C/"},"sources":[{"label":"Volvo Car USA — founding campaign","url":"https://www.volvocars.com/us/media/press-releases/96EB870D60DBFA0C/","dateEvidence":true}]},"2026-11-15:national-philanthropy-day":{"id":"2026-11-15:national-philanthropy-day","date":"2026-11-15","verification":"organiser","summary":"Giving is not only about the size of a donation. National Philanthropy Day on 15 November recognises volunteering, generosity and the people who help community organisations do their work throughout the year.","sections":[{"heading":"Where the day comes from","body":"The movement was developed by Douglas Freeman in the 1980s, with US recognition in 1986. Canada later recognised the day permanently in 2012. The Association of Fundraising Professionals supports the observance, and local chapters often hold events across November. The central idea is to notice the many different contributions that allow charitable work to happen."},{"heading":"Notice the less visible contributions","body":"A dependable volunteer, someone lending professional skills, or a neighbour organising transport may be as important to a project as a headline gift. A thoughtful thank-you can name the practical difference that person makes. If you want to get involved yourself, ask a local organisation what it actually needs rather than assuming that the most obvious activity will be the most useful."}],"activity":{"text":"Thank a volunteer or community organiser for one specific contribution, or ask a local project which practical task needs help.","label":"Explore National Philanthropy Day","url":"https://afpglobal.org/NPDLove"},"sources":[{"label":"Association of Fundraising Professionals — history","url":"https://afpglobal.org/about-national-philanthropy-day","dateEvidence":true},{"label":"AFP — ways to recognise giving","url":"https://afpglobal.org/NPDLove","dateEvidence":true}]},"2026-11-17:international-students-day":{"id":"2026-11-17:international-students-day","date":"2026-11-17","verification":"organiser","summary":"Student life carries a history of resistance as well as discovery. International Students’ Day on 17 November remembers attacks on Czech universities in 1939 and affirms education, freedom and solidarity across borders.","sections":[{"heading":"A date with a serious history","body":"The observance recalls Nazi action against Czech universities following anti-Nazi demonstrations in 1939. Universities were closed and students were imprisoned or killed. Since 1941, the date has been associated with student resistance and democratic freedoms. A student commemoration in 1989 also became a catalyst for the events of Czechoslovakia’s Velvet Revolution."},{"heading":"Education and belonging now","body":"Contemporary organisations mark the day through student rights, accessible education and international cooperation. Students crossing borders can bring languages, experiences and friendships into a community, while also encountering practical barriers. A useful way to participate is to listen to those experiences directly: ask what makes a course, campus or student group more welcoming, and what still makes participation harder."}],"activity":{"text":"Find a student-led project or society and learn about one issue its members are working to change.","label":"Learn the day’s history","url":"https://speech-repository.webcloud.ec.europa.eu/news/17th-november-international-students%E2%80%99-day"},"sources":[{"label":"European Commission — history of 17 November","url":"https://speech-repository.webcloud.ec.europa.eu/news/17th-november-international-students%E2%80%99-day","dateEvidence":true},{"label":"EUSA — 2026 observance","url":"https://www.eusa.eu/international-students-day-2026","dateEvidence":true}]},"2026-11-18:gis-day":{"id":"2026-11-18:gis-day","date":"2026-11-18","verification":"organiser","summary":"Maps can tell much more than where to turn left. 🗺️ GIS Day on 18 November 2026 celebrates geographic information systems: the tools connecting information with place to help people understand patterns and make decisions.","sections":[{"heading":"Layers tell a story","body":"A geographic information system combines location with other information. Different layers can show features such as roads, habitats or services, making relationships easier to explore. GIS Day invites professionals and curious newcomers to share how that work is used. The first formal celebration was held in 1999, with sharing and teaching at the centre of the idea."},{"heading":"Ask a question of a map","body":"Try starting with something local: where are green spaces, which areas have transport links, or what has changed over time? Look at the map’s source and date before treating its picture as complete. The organiser’s resources and map gallery offer examples of how people turn spatial data into stories. The interesting part is often the question being asked, rather than the software."}],"activity":{"text":"Explore one map in the GIS Day gallery and identify the question it helps answer about a place.","label":"Explore GIS Day resources","url":"https://www.gisday.com/en-us/overview"},"sources":[{"label":"Esri — GIS Day 2026","url":"https://www.gisday.com/en-us/overview","dateEvidence":true}]},"2026-11-19:guinness-world-records-day":{"id":"2026-11-19:guinness-world-records-day","date":"2026-11-19","verification":"organiser","summary":"There is a record for that, apparently. 🏆 Guinness World Records Day brings together people testing remarkably specific skills and limits. The organiser confirms Thursday 19 November as the date for the 2026 celebration.","sections":[{"heading":"A day for record-breaking","body":"The annual event began in 2004, marking the Guinness World Records book becoming the best-selling copyright book. Since then, attempts around the world have formed a shared celebration. A record title needs a defined measurement and evidence, so the distinction is between an impressive claim and an achievement that can be checked against the organisation’s rules."},{"heading":"Wonder without the dangerous stunt","body":"You do not have to attempt an official record to enjoy the date. Browse an unusual achievement, compare the different talents involved, or set a harmless household challenge with a rule everyone understands. Balance, memory, collecting and precision can be as fascinating as spectacular physical feats. The best discoveries are often the records you never imagined anybody would think to measure."}],"activity":{"text":"Browse the day’s official record stories and pick the achievement you would most like to ask its holder about.","label":"Explore record-breaking stories","url":"https://www.guinnessworldrecords.com/gwrday/index"},"sources":[{"label":"Guinness World Records — GWR Day 2026","url":"https://www.guinnessworldrecords.com/gwrday/index","dateEvidence":true}]},"2026-11-20:international-hug-a-runner-day":{"id":"2026-11-20:international-hug-a-runner-day","date":"2026-11-20","verification":"organiser","summary":"A little encouragement for the people putting one foot in front of the other. 👟 Hug a Runner Day on 20 November is a Run The Edge community campaign for kindness among runners and walkers.","sections":[{"heading":"A community idea","body":"Run The Edge founders Tim Catalano and Adam Goucher developed Globally Organized Hug A Runner Day after seeing the positivity of an earlier cross-country running group. The organiser uses the abbreviation G.O.H.A.R.D. and identifies 20 November as the annual date. The emphasis is on connection and good humour, rather than an official sporting competition or public holiday."},{"heading":"Encouragement counts","body":"A hug is only one possible way to join in, and the campaign specifically says to ask permission. A supportive message, a friendly walk or recognising someone’s progress can carry the same spirit. There is no requirement to be fast, run a particular distance or buy entry to a challenge. Choose a gesture that the other person would actually enjoy."}],"activity":{"text":"Send a runner or walker you know a specific message of encouragement; offer a hug only if they would welcome one.","label":"Meet the campaign","url":"https://runtheedge.com/blogs/beyond-the-miles/everything-you-need-to-know-about-globally-organized-hug-a-runner-day"},"sources":[{"label":"Run The Edge — campaign history","url":"https://runtheedge.com/blogs/beyond-the-miles/everything-you-need-to-know-about-globally-organized-hug-a-runner-day","dateEvidence":true}],"researchNote":"The organiser mentions both a 2010 origin and a first virtual event in 2011; the exact first edition is therefore not simplified in the app."},"2026-11-22:stir-up-sunday":{"id":"2026-11-22:stir-up-sunday","date":"2026-11-22","verification":"independent-calendar","summary":"Get the mixing bowl out: it is pudding-preparation day. 🥣 Stir-Up Sunday falls on 22 November in 2026, the last Sunday before Advent, when Christmas puddings can be made ahead and left to mature.","sections":[{"heading":"Why “stir-up”?","body":"The name comes from words in an Anglican prayer traditionally read on the Sunday before Advent. Over time, the phrase became associated with the practical job of mixing a Christmas pudding. Some households pass the bowl around so everyone can stir and make a wish. Customs differ, but the shared kitchen ritual is part of the pleasure."},{"heading":"Give the pudding a head start","body":"A traditional Christmas pudding is usually steamed and prepared ahead of the day it will be served. The linked Nigella Lawson recipe includes the full preparation, steaming and reheating guidance. Read it before starting so you know the time and equipment involved. If a whole pudding is too much of a project, choose a smaller festive bake or compare family pudding recipes instead."}],"activity":{"text":"Try Nigella’s Christmas pudding recipe, or invite someone to stir the mixture and make a wish with you.","label":"Make a Christmas pudding","url":"https://www.nigella.com/recipes/ultimate-christmas-pudding"},"sources":[{"label":"Good Food — Stir-Up Sunday 2026","url":"https://www.bbcgoodfood.com/howto/guide/stir-up-sunday","dateEvidence":true},{"label":"Nigella Lawson — Christmas pudding recipe","url":"https://www.nigella.com/recipes/ultimate-christmas-pudding","dateEvidence":false}]},"2026-11-23:national-espresso-day":{"id":"2026-11-23:national-espresso-day","date":"2026-11-23","verification":"independent-calendar","summary":"Small cup, big personality. ☕ National Espresso Day is an informal US observance on 23 November, celebrating the concentrated coffee that also forms the base of familiar drinks such as cappuccinos and lattes.","sections":[{"heading":"It is a brewing method","body":"Espresso is made by passing hot water under pressure through finely ground coffee. It describes the preparation rather than a particular variety of coffee bean. A short serving makes changes in grind, extraction and flavour especially noticeable. The annual calendar date is a modern food-and-drink celebration, rather than an Italian public holiday."},{"heading":"Taste before adding anything","body":"If you already enjoy coffee, ask a barista about the beans they are using and try noticing the aroma and finish of a small serving. If straight espresso is not your thing, a milk-based drink still begins with the same brewing method. You could even compare the words different people use to describe the same cup: bitter, fruity, nutty or chocolatey."}],"activity":{"text":"Ask a local barista about their espresso, and taste your usual coffee a little more slowly before adding anything.","label":"Explore Espresso Day","url":"https://nationaldaycalendar.com/celebrations/national-espresso-day-november-23"},"sources":[{"label":"National Day Calendar — Espresso Day","url":"https://nationaldaycalendar.com/celebrations/national-espresso-day-november-23","dateEvidence":true}]},"2026-11-24:celebrate-your-unique-talent-day":{"id":"2026-11-24:celebrate-your-unique-talent-day","date":"2026-11-24","verification":"independent-calendar","summary":"Your oddly specific skill is invited. ✨ Celebrate Your Unique Talent Day on 24 November is an informal occasion for the abilities that make people interesting, whether impressive, useful or delightfully unnecessary.","sections":[{"heading":"What counts as a talent?","body":"Independent calendars list the date as a celebration of personal skills and individual creativity. It is not a competition and does not require professional recognition. A talent might involve music, making things, remembering details, telling stories or solving a very particular problem. Something that seems ordinary to you can be surprising or valuable to someone else."},{"heading":"Show and tell, without the pressure","body":"Try asking a friend what they enjoy doing that rarely comes up in conversation. You might learn how they mend a favourite item, arrange flowers or make a convincing sound effect. Sharing a tiny demonstration is enough. If showing a skill feels awkward, spend a few minutes practising it privately or ask another person to teach you theirs."}],"activity":{"text":"Arrange a two-minute skill swap: show a friend one small thing you can do, then let them teach you something.","label":"Get talent-day ideas","url":"https://www.timeanddate.com/holidays/fun/celebrate-your-unique-talent-day"},"sources":[{"label":"timeanddate — informal observance","url":"https://www.timeanddate.com/holidays/fun/celebrate-your-unique-talent-day","dateEvidence":true}]},"2026-11-25:national-parfait-day":{"id":"2026-11-25:national-parfait-day","date":"2026-11-25","verification":"independent-calendar","summary":"Dessert with a little architecture. 🍨 National Parfait Day falls on 25 November in informal US food calendars, celebrating layered glasses of fruit, cream, yogurt, crunch and whatever else makes the spoonful interesting.","sections":[{"heading":"One name, different desserts","body":"Parfait is a French word meaning perfect. French-style parfait is traditionally a frozen dessert, while the American version often refers to ingredients layered in a tall glass. Yogurt and fruit versions sit happily alongside richer dessert combinations. The calendar observance is a casual food celebration, not a claim that there is only one correct way to assemble the dish."},{"heading":"Build a good spoonful","body":"Think about contrast rather than making a very large serving: something creamy, something juicy and something with a little crunch. A clear glass lets you see the layers, but any small bowl works. Add a crisp topping just before eating if you want it to stay crisp. The linked raspberry and mango recipe is a useful place to start."}],"activity":{"text":"Layer yogurt and fruit in a small glass, then finish with a little crunch just before you eat it.","label":"Make a fruit parfait","url":"https://www.bbcgoodfood.com/recipes/raspberry-mango-yogurt-parfait"},"sources":[{"label":"National Day Calendar — Parfait Day","url":"https://nationaldaycalendar.com/celebrations/national-parfait-day-november-25","dateEvidence":true},{"label":"Good Food — raspberry and mango parfait","url":"https://www.bbcgoodfood.com/recipes/raspberry-mango-yogurt-parfait","dateEvidence":false}]},"2026-11-27:black-friday":{"id":"2026-11-27:black-friday","date":"2026-11-27","verification":"independent-calendar","summary":"The sales day after US Thanksgiving has travelled far beyond the United States. 🛍️ Black Friday falls on 27 November in 2026; shops may run promotions before or after it, and buying is entirely optional.","sections":[{"heading":"A date set by custom","body":"Black Friday is the Friday after the fourth Thursday of November, rather than a date set by one organiser. In 2026, Thanksgiving is 26 November, placing Black Friday on the 27th. Retailers in other countries often use the same date. There is no universal start time, official theme or guarantee that every advertised deal runs only that day."},{"heading":"Keep the list in charge","body":"If you planned to buy something anyway, compare the actual product and total cost rather than responding only to a countdown or discount percentage. A short list can make the day less distracting. Doing nothing is also a perfectly valid response: the event is a retail convention, not an obligation to shop or find a bargain before time runs out."}],"activity":{"text":"Write down anything you genuinely need before opening sale pages, and leave the list empty if nothing comes to mind.","label":"Check the date and context","url":"https://www.awarenessdays.com/awareness-days-calendar/black-friday/"},"sources":[{"label":"Awareness Days — Black Friday 2026","url":"https://www.awarenessdays.com/awareness-days-calendar/black-friday/","dateEvidence":true}]},"2026-11-28:national-french-toast-day":{"id":"2026-11-28:national-french-toast-day","date":"2026-11-28","verification":"independent-calendar","summary":"Yesterday’s bread gets a very good second act. 🍞 National French Toast Day on 28 November is an informal US food celebration for golden egg-soaked bread, whether your toppings lean sweet or savoury.","sections":[{"heading":"A familiar dish with many names","body":"Eggy bread, pain perdu and French toast belong to a broad family of dishes made by soaking bread and then cooking it. A typical sweet version combines eggs and milk, sometimes with vanilla or cinnamon. Slightly stale bread can hold its shape well. The named food day has no firmly documented founder, so its appeal is more breakfast-table tradition than official history."},{"heading":"Choose your finishing touch","body":"You can keep the plate simple with fruit, or go savoury if that suits your breakfast better. The linked Good Food recipe gives quantities and a short cooking method, with thick brioche as its starting point. Read the recipe’s soaking instructions first: the aim is bread that absorbs the mixture while still holding together in the pan."}],"activity":{"text":"Try the linked French toast recipe, then choose one topping that makes it your version rather than a café copy.","label":"Make French toast","url":"https://www.bbcgoodfood.com/recipes/french-toast"},"sources":[{"label":"National Day Calendar — French Toast Day","url":"https://nationaldaycalendar.com/celebrations/national-french-toast-day-november-28/","dateEvidence":true},{"label":"Good Food — French toast recipe","url":"https://www.bbcgoodfood.com/recipes/french-toast","dateEvidence":false}]},"2026-11-29:national-chocolates-day":{"id":"2026-11-29:national-chocolates-day","date":"2026-11-29","verification":"independent-calendar","summary":"The assorted box gets its own informal celebration on 29 November. 🍫 National Chocolates Day is a chance to enjoy filled chocolates, compare favourite centres or make a small batch to share with someone.","sections":[{"heading":"A box full of choices","body":"This date appears in independent US food calendars and is separate from other chocolate-themed dates during the year. The plural suits the assorted box: truffles, creams, caramels and different chocolate coatings can all sit alongside one another. The day’s origins are not firmly documented, so it is best treated as a playful food occasion rather than an official anniversary."},{"heading":"Make a small tasting","body":"Choose a few contrasting pieces and describe what you notice: texture, sweetness, aroma and filling. You can also make your own truffles using chocolate and cream, then finish them in different coatings. The linked Good Food recipe includes chilling time, which is worth planning before you begin. A tiny homemade box can be a thoughtful gift without turning the kitchen into a factory."}],"activity":{"text":"Try the linked chocolate truffle recipe and give a few finished pieces to someone who would enjoy a homemade treat.","label":"Make chocolate truffles","url":"https://www.bbcgoodfood.com/recipes/easy-chocolate-truffles"},"sources":[{"label":"Checkiday — National Chocolates Day","url":"https://www.checkiday.com/b2220a1d7110b382b098d4b2bf0b6c02/national-chocolates-day","dateEvidence":true},{"label":"Good Food — easy chocolate truffles","url":"https://www.bbcgoodfood.com/recipes/easy-chocolate-truffles","dateEvidence":false}]},"2026-11-30:national-personal-space-day":{"id":"2026-11-30:national-personal-space-day","date":"2026-11-30","verification":"organiser","summary":"Kindness sometimes means giving someone more room. National Personal Space Day on 30 November encourages respect for boundaries, including the right to choose whether, when and how another person touches you.","sections":[{"heading":"The idea behind the peach","body":"The Give Space campaign uses a peach symbol to communicate a need for extra personal space. Its founder drew on caring experiences in which well-meant physical contact could be uncomfortable or unwelcome. National Day Calendar registered the annual day in 2019. The broader message is useful even when nobody is wearing a symbol: a warm intention does not replace another person’s choice."},{"heading":"Care can take another form","body":"Instead of assuming a hug or handshake is welcome, ask. Accepting the answer without demanding an explanation is part of the gesture. Giving a little more room, offering a wave, helping with a practical task or simply listening can express care as well. People’s preferences may change from one day to another, so familiarity does not remove the need to pay attention."}],"activity":{"text":"Before greeting someone physically today, ask what they would prefer and make the answer easy to give.","label":"Explore the campaign","url":"https://nationaldaycalendar.com/celebrations/national-personal-space-day-november-30/"},"sources":[{"label":"National Day Calendar — registered campaign and date","url":"https://nationaldaycalendar.com/celebrations/national-personal-space-day-november-30/","dateEvidence":true}]},"2026-12-02:international-day-for-the-abolition-of-slavery":{"id":"2026-12-02:international-day-for-the-abolition-of-slavery","date":"2026-12-02","verification":"organiser","summary":"A day to recognise that slavery is not only a historical subject. The UN’s International Day for the Abolition of Slavery on 2 December calls attention to exploitation and the work needed to protect freedom today.","sections":[{"heading":"Why this date?","body":"The observance marks the UN General Assembly’s adoption of a convention on trafficking and exploitation on 2 December 1949. Its present-day focus includes forced labour, trafficking and other forms of slavery. The common thread is control and exploitation that take away a person’s freedom, rather than simply work that is unpleasant or poorly paid."},{"heading":"Understand the issue beyond a headline","body":"Anti-Slavery International explains how coercion, threats and debt can trap people in situations they cannot leave. Exploitation can occur in homes, agriculture, factories and supply chains. Listening to people with lived experience and reading specialist organisations’ explanations can help replace assumptions with understanding. Practical change also involves protection, support and accountability, rather than expecting individuals at risk to solve the problem alone."}],"activity":{"text":"Read Anti-Slavery International’s guide and learn one form of exploitation that you previously knew little about.","label":"Understand modern slavery","url":"https://www.antislavery.org/slavery-today/modern-slavery/"},"sources":[{"label":"United Nations — observance and date","url":"https://www.un.org/en/observances/slavery-abolition-day","dateEvidence":true},{"label":"Anti-Slavery International — modern slavery","url":"https://www.antislavery.org/slavery-today/modern-slavery/","dateEvidence":false}]},"2026-12-04":{"id":"2026-12-04","date":"2026-12-04","verification":"independent-calendar","summary":"Crumbs are a perfectly acceptable plan. 🍪 National Cookie Day on 4 December is an informal US celebration of biscuits in all their forms: soft, crisp, filled, iced or unapologetically covered in chocolate chips.","sections":[{"heading":"A modern food-calendar favourite","body":"National Day Calendar links the December date to a celebration created by Matt Nader of the Blue Chip Cookie Company in 1987. It is a commercial food tradition, not a public holiday. The broad category includes drop cookies, rolled shapes, sandwich biscuits and no-bake versions, leaving plenty of room to choose the texture you actually enjoy."},{"heading":"Bake, compare or share","body":"A simple batch can be more fun than a complicated decorating project. The linked chocolate chip recipe makes soft-centred cookies with familiar baking ingredients and includes preparation and oven timings. You could split the finished batch between friends, compare two favourite bakery biscuits, or ask someone which kind reminds them of childhood. There is no requirement to make everything from scratch."}],"activity":{"text":"Try the linked chocolate chip cookies, or choose a favourite biscuit and share a few with someone nearby.","label":"Bake chocolate chip cookies","url":"https://www.bbcgoodfood.com/recipes/vintage-chocolate-chip-cookies"},"sources":[{"label":"National Day Calendar — Cookie Day","url":"https://nationaldaycalendar.com/celebrations/national-cookie-day-december-4/","dateEvidence":true},{"label":"Good Food — chocolate chip cookies","url":"https://www.bbcgoodfood.com/recipes/vintage-chocolate-chip-cookies","dateEvidence":false}]},"2026-12-05:world-soil-day":{"id":"2026-12-05:world-soil-day","date":"2026-12-05","verification":"organiser","summary":"There is a whole living world beneath your shoes. 🌱 World Soil Day on 5 December highlights the soils that support food production, biodiversity and the functioning of ecosystems, with FAO coordinating the international observance.","sections":[{"heading":"Soil is more than dirt","body":"Soil contains minerals, organic material, air, water and living organisms. Its structure affects how plants establish roots and how water moves through the ground. Those functions connect the condition of soil with farming, habitats and the places people live. The UN-recognised day has been observed internationally since 2014, with Thailand playing a leading role in its establishment."},{"heading":"Look closely at a small sample","body":"You do not need a laboratory to begin noticing soil. Compare a little garden soil with a patch beneath a tree: look for leaf fragments, roots and differences in texture. FAO’s learning resources offer simple supervised experiments for children, including exploring what soil contains. Treat the living things you encounter gently and return a sample to where you found it after looking."}],"activity":{"text":"Try one of FAO’s simple soil activities, or look closely at a small soil sample and sketch what you can see.","label":"Explore soil activities","url":"https://www.fao.org/family-farming/detail/en/c/1726256/"},"sources":[{"label":"FAO — World Soil Day","url":"https://www.fao.org/world-soil-day/en","dateEvidence":true},{"label":"FAO — soil experiments for children","url":"https://www.fao.org/family-farming/detail/en/c/1726256/","dateEvidence":false}]},"2026-12-07":{"id":"2026-12-07","date":"2026-12-07","verification":"organiser","summary":"A flight depends on much more than an aeroplane. ✈️ International Civil Aviation Day on 7 December recognises the cooperation that connects people and places, while drawing attention to safe and sustainable international air transport.","sections":[{"heading":"The agreement behind the network","body":"In December 1944, representatives of 54 nations met in Chicago and signed the Convention on International Civil Aviation. That agreement helped establish the framework for international cooperation in civil aviation. ICAO created the day during its fiftieth-anniversary activities in 1994, and the UN General Assembly recognised 7 December in 1996."},{"heading":"Look beyond the departure board","body":"International aviation involves common standards, navigation, airports and many different professions working across borders. Its benefits also sit alongside questions about accessibility and environmental impact. Today can be an opportunity to explore how a familiar route operates or learn about a less visible aviation role. ICAO’s information explains the shared systems behind an industry that can otherwise seem like a simple ticket purchase."}],"activity":{"text":"Explore ICAO’s overview and choose one behind-the-scenes aviation job or system to learn about.","label":"Discover civil aviation","url":"https://www.icao.int/international-civil-aviation-day-7-december"},"sources":[{"label":"ICAO — International Civil Aviation Day","url":"https://www.icao.int/international-civil-aviation-day-7-december","dateEvidence":true},{"label":"United Nations — historical background","url":"https://www.un.org/en/observances/civil-aviation-day/background","dateEvidence":true}]},"2026-12-08:pretend-to-be-a-time-traveler-day":{"id":"2026-12-08:pretend-to-be-a-time-traveler-day","date":"2026-12-08","verification":"independent-calendar","summary":"The year is 2026. Act suitably surprised. 🕰️ Pretend to Be a Time Traveler Day is an informal 8 December excuse for imaginative costumes, future postcards and looking at everyday technology as if it were completely new.","sections":[{"heading":"A small piece of internet play","body":"Independent calendars connect the observance with the webcomic community around Dresden Codak and list 8 December as the annual date. It is a creative game, not a scientific event or a claim that a time machine exists. The premise can point in either direction: visit the present from an imagined future, or arrive from a period in the past."},{"heading":"Invent a visitor","body":"Choose a year, give your character one thing they find baffling, and imagine what they would misunderstand about today. A postcard, short voice note or conversation with a willing friend is enough. You could also choose a time-travel story and discuss the rules its fictional world uses. Keep other people in on the joke if you take the activity beyond your own notebook."}],"activity":{"text":"Write a postcard from a visitor arriving in 2026 and describe three ordinary things that astonish them.","label":"Explore time-traveller ideas","url":"https://www.checkiday.com/8a3e2a2d1b3141ba8d08c6df8970abfb/pretend-to-be-a-time-traveler-day"},"sources":[{"label":"Checkiday — date and creative background","url":"https://www.checkiday.com/8a3e2a2d1b3141ba8d08c6df8970abfb/pretend-to-be-a-time-traveler-day","dateEvidence":true},{"label":"timeanddate — informal observance","url":"https://www.timeanddate.com/holidays/fun/pretend-to-be-a-time-traveler-day","dateEvidence":true}]},"2026-12-10:christmas-jumper-day":{"id":"2026-12-10:christmas-jumper-day","date":"2026-12-10","verification":"organiser","summary":"The louder the knitwear, the better the conversation starter. 🎄 Save the Children’s Christmas Jumper Day falls on Thursday 10 December in 2026, turning festive outfits into a chance to support children and young people.","sections":[{"heading":"A campaign with a clear purpose","body":"Save the Children has run the fundraiser since 2012. Schools, workplaces and groups of friends take part, with the charity using support for its work with children in the UK and internationally. The official 2026 date is 10 December, although the organiser says groups can choose a different day if that works better for them."},{"heading":"No new jumper required","body":"The charity encourages people to decorate something they already own, swap with a friend or choose a second-hand jumper. Its official resources include activities and fundraising materials for groups. A suggested donation is not a requirement to belong to the fun, so keep participation welcoming. A few temporary decorations can turn an ordinary pullover into the day’s most memorable outfit."}],"activity":{"text":"Give an old jumper a temporary festive makeover and explore the charity’s official ideas with friends or colleagues.","label":"Get official jumper-day ideas","url":"https://www.savethechildren.org.uk/christmas-jumper-day/about/faq"},"sources":[{"label":"Save the Children — 2026 date and participation","url":"https://www.savethechildren.org.uk/christmas-jumper-day/about/faq","dateEvidence":true}]},"2026-12-12":{"id":"2026-12-12","date":"2026-12-12","verification":"organiser","summary":"Those vivid red “petals” are actually coloured leaves. 🌺 National Poinsettia Day on 12 December celebrates the seasonal plant and its history, with colours ranging from familiar scarlet to pink, cream and salmon.","sections":[{"heading":"Look past the red bracts","body":"The showy parts of a poinsettia are leaf bracts surrounding the flowers. The December observance in the United States falls on the anniversary of Joel Roberts Poinsett’s death; the plant’s English name also refers to him. Its cultural history is closely connected with Mexico, rather than beginning with its later popularity as a Christmas houseplant elsewhere."},{"heading":"Keep the colour going","body":"The RHS describes poinsettias as tender houseplants that prefer a bright, warm position away from direct sun and cold draughts. They can be kept beyond the festive season instead of automatically being thrown away. Encouraging fresh colour in another year takes attention to day length and darkness, so the growing guide is useful if you fancy a small horticultural project."}],"activity":{"text":"Look closely at a poinsettia’s bracts, then use the RHS guide to find a comfortable place for the plant indoors.","label":"Read the poinsettia care guide","url":"https://www.rhs.org.uk/plants/euphorbia/poinsettia/growing-guide"},"sources":[{"label":"Smithsonian Libraries — National Poinsettia Day","url":"https://blog.library.si.edu/blog/2015/12/16/tired-of-poinsettias-bah-humbug/","dateEvidence":true},{"label":"Royal Horticultural Society — growing guide","url":"https://www.rhs.org.uk/plants/euphorbia/poinsettia/growing-guide","dateEvidence":false}]},"2026-12-13:world-choral-day":{"id":"2026-12-13:world-choral-day","date":"2026-12-13","verification":"organiser","summary":"Voices together begin with listening. 🎶 World Choral Day falls on 13 December in 2026, with the International Federation for Choral Music inviting singers and listeners to explore its theme, The Courage to Listen.","sections":[{"heading":"You do not have to be in a choir","body":"The organiser welcomes people across the choral community, from conductors and composers to teachers, organisers and those who simply enjoy listening. The 2026 invitation is to make room for voices and experiences beyond your usual circle. An event could be a concert, rehearsal, shared reflection or a small musical gathering rather than a polished performance."},{"heading":"Listen for the other parts","body":"Choose a choral piece and pay attention to how individual lines support one another. On another listen, follow a different voice or notice the silence between phrases. If you sing with others, make a little space to hear them before trying to project your own part. The point is connection through music, not judging whether somebody has the most impressive voice."}],"activity":{"text":"Listen twice to a choir recording: follow a different voice on the second listen and notice how the music changes.","label":"Explore World Choral Day","url":"https://www.ifcm.net/projects/world-choral-day"},"sources":[{"label":"International Federation for Choral Music — 2026 programme","url":"https://www.ifcm.net/projects/world-choral-day","dateEvidence":true}]},"2026-12-15:bill-of-rights-day":{"id":"2026-12-15:bill-of-rights-day","date":"2026-12-15","verification":"organiser","summary":"Ten amendments with an enduring place in US history. Bill of Rights Day on 15 December marks the ratification of the Constitution’s first ten amendments in 1791 and invites a closer look at the text.","sections":[{"heading":"What the document covers","body":"The Bill of Rights addresses freedoms including speech, religion and the press, alongside protections concerning criminal proceedings and government power. It was added after debate over how rights should be protected under the new Constitution. The National Archives preserves the original document and provides a transcription, historical explanations and educational material for people exploring it."},{"heading":"Read with a question in mind","body":"Rather than trying to memorise all ten amendments, choose one and ask what issue its wording addresses. Compare the original language with the Archives’ explanation and notice which words need historical context. The document’s history also opens questions about whose rights were protected in practice and how that changed over time. An original document becomes much more interesting when you bring a concrete question to its wording."}],"activity":{"text":"Choose one amendment, read its actual wording and use the National Archives materials to understand the issue behind it.","label":"Explore the Bill of Rights","url":"https://www.archives.gov/news/topics/bill-of-rights"},"sources":[{"label":"US National Archives — Bill of Rights Day","url":"https://www.archives.gov/news/topics/bill-of-rights","dateEvidence":true},{"label":"US National Archives — ratification history","url":"https://www.archives.gov/publications/prologue/2016/winter/archivist-bill-of-rights","dateEvidence":true}]},"2026-12-17":{"id":"2026-12-17","date":"2026-12-17","verification":"independent-calendar","summary":"A little amber drizzle has a surprisingly long journey behind it. 🍁 National Maple Syrup Day is an informal US food observance on 17 December, celebrating syrup made by concentrating the sap of maple trees.","sections":[{"heading":"From sap to syrup","body":"Maple sap is collected during the appropriate seasonal conditions and heated to remove much of its water. That concentration produces the syrup used at the table and in cooking. Indigenous peoples of North America developed maple-sugaring knowledge before European settlers adopted it. The December food-calendar date is a celebration of the finished ingredient, rather than the main spring tapping season."},{"heading":"Try it beyond the obvious","body":"Pancakes and French toast are familiar partners, but maple syrup can also bring sweetness to porridge or a dressing. If you have a bottle already, notice its colour, aroma and flavour before adding more. A small tasting can be enough to appreciate it. The linked French toast recipe gives a breakfast starting point without requiring a full pancake-stack production."}],"activity":{"text":"Add a small drizzle to your breakfast, or make French toast and compare the syrup’s flavour before and after adding it.","label":"Make French toast to match","url":"https://www.bbcgoodfood.com/recipes/french-toast"},"sources":[{"label":"National Day Calendar — Maple Syrup Day","url":"https://nationaldaycalendar.com/celebrations/national-maple-syrup-day-december-17","dateEvidence":true},{"label":"Good Food — French toast recipe","url":"https://www.bbcgoodfood.com/recipes/french-toast","dateEvidence":false}]},"2026-12-18:national-ugly-christmas-sweater-day":{"id":"2026-12-18:national-ugly-christmas-sweater-day","date":"2026-12-18","verification":"independent-calendar","summary":"Maximum festive knitwear, minimum embarrassment. 🧶 National Ugly Christmas Sweater Day is an informal observance on the third Friday of December, which falls on 18 December in 2026. Cheerfully over-the-top outfits are the whole idea.","sections":[{"heading":"A different jumper date","body":"This US-style calendar observance is separate from Save the Children’s UK Christmas Jumper Day, whose 2026 campaign date is 10 December. The sweater day celebrates the deliberately excessive jumper: clashing colours, seasonal motifs and decorations that refuse to be subtle. Some groups connect their celebrations with a charity, but there is no single required way to take part."},{"heading":"Reuse what you have","body":"A swap with a friend or a temporary decoration on an old jumper can be more entertaining than buying a new one. If a group wants a competition, choose playful categories such as most inventive reuse rather than making the joke about somebody’s taste or body. The aim is a shared laugh and an excuse to be creative with something familiar."}],"activity":{"text":"Give an old jumper a ridiculous temporary upgrade, or swap festive knitwear with a friend for the day.","label":"See the sweater-day date","url":"https://www.checkiday.com/124edab4668d790bad8178d15998db67/national-ugly-christmas-sweater-day"},"sources":[{"label":"Checkiday — 2026 date and date rule","url":"https://www.checkiday.com/124edab4668d790bad8178d15998db67/national-ugly-christmas-sweater-day","dateEvidence":true},{"label":"timeanddate — Ugly Sweater Day","url":"https://www.timeanddate.com/holidays/fun/ugly-sweater-day","dateEvidence":true}]},"2026-12-20:go-caroling-day":{"id":"2026-12-20:go-caroling-day","date":"2026-12-20","verification":"independent-calendar","summary":"Warm up the singing voice, however rusty it is. 🎶 Go Caroling Day is an informal 20 December invitation to enjoy seasonal songs with other people, whether outdoors, at a community event or in your own living room.","sections":[{"heading":"A shared seasonal tradition","body":"Caroling often means groups singing Christmas songs for neighbours or at community gatherings. The tradition is much older than the named calendar day, and the songs people choose vary between places and families. Familiar choices can make it easy to join in even when nobody has rehearsed. The contemporary observance is not an official public holiday."},{"heading":"Keep the singalong welcoming","body":"Pick a few songs people know and decide together where and when singing would be welcome. A local organised event can offer an easy starting point. If you prefer staying in, take turns choosing a carol or listen to a choir recording instead. Nobody needs to perform a solo, remember every verse or have a formally trained voice for the music to feel shared."}],"activity":{"text":"Choose three familiar seasonal songs with a friend and have a short singalong, or join an advertised community event.","label":"Get caroling ideas","url":"https://nationaldaycalendar.com/celebrations/go-caroling-day-december-20"},"sources":[{"label":"National Day Calendar — Go Caroling Day","url":"https://nationaldaycalendar.com/celebrations/go-caroling-day-december-20","dateEvidence":true}]},"2026-12-21:world-basketball-day":{"id":"2026-12-21:world-basketball-day","date":"2026-12-21","verification":"organiser","summary":"A ball, a hoop and a game that has travelled around the world. 🏀 World Basketball Day on 21 December is a UN observance recognising basketball’s potential for participation, cooperation and connection between communities.","sections":[{"heading":"Why 21 December?","body":"The date recalls the first basketball game, played in 1891 after James Naismith developed the sport at a YMCA training school. The UN General Assembly proclaimed World Basketball Day in 2023. The observance invites people to consider the game not only as elite competition, but also as a shared activity that can bring people together across different backgrounds."},{"heading":"You can start small","body":"You do not need a full team or an official match to engage with the sport. Watch a local game, learn how scoring works, or practise a few passes and shots with someone. If you organise an activity, think about what will allow everyone present to participate. Adjusting the format can matter more than following every competition rule perfectly."}],"activity":{"text":"Watch a basketball game with someone who can explain it, or spend a few minutes practising friendly passes and shots together.","label":"Discover World Basketball Day","url":"https://www.ymca.int/world-basketball-day/"},"sources":[{"label":"United Nations — World Basketball Day","url":"https://www.un.org/en/observances/world-basketball-day","dateEvidence":true},{"label":"World YMCA — history and observance","url":"https://www.ymca.int/world-basketball-day/","dateEvidence":true}]},"2026-12-23:christmas-movie-marathon-day":{"id":"2026-12-23:christmas-movie-marathon-day","date":"2026-12-23","verification":"independent-calendar","summary":"Blanket, snacks, remote: ready. 🍿 Christmas Movie Marathon Day is an informal 23 December occasion to settle into familiar festive stories, or try something a little different from your usual annual rewatch.","sections":[{"heading":"Festive films have a long history","body":"Christmas was a cinema subject long before streaming menus existed. The BFI highlights G. A. Smith’s Santa Claus from 1898, an early British short using visual effects to show Father Christmas at work. Later seasonal favourites range from animation to comedy and family drama. The named marathon day is a modern calendar invitation, not a milestone in the history of filmmaking."},{"heading":"Curate a small double bill","body":"You can make an evening feel special without watching films all day. Pair one familiar choice with a short film you have never seen, and let everyone joining suggest something. The BFI’s collection of Christmas shorts offers an alternative when a long feature is too much of a commitment. Add an interval for snacks and a pleasantly unnecessary debate about the best festive scene."}],"activity":{"text":"Pair one favourite Christmas film with an unfamiliar short from the BFI’s selection and make your own small double bill.","label":"Find a Christmas short film","url":"https://www.bfi.org.uk/lists/10-great-christmas-short-films"},"sources":[{"label":"National Day Calendar — 23 December observance","url":"https://nationaldaycalendar.com/celebrations/christmas-movie-marathon-day","dateEvidence":true},{"label":"BFI — Christmas short films and early cinema","url":"https://www.bfi.org.uk/lists/10-great-christmas-short-films","dateEvidence":false}]},"2026-12-25":{"id":"2026-12-25","date":"2026-12-25","verification":"organiser","summary":"A day with many ways of belonging. 🎄 Christmas on 25 December is a Christian celebration of Jesus’s birth, and also a cultural occasion for many people who mark it through food, company, generosity or their own traditions.","sections":[{"heading":"A religious festival and a cultural day","body":"Many Western Christian churches celebrate the Nativity on 25 December, with services and readings telling the Christmas story. Other Christian communities follow different calendar traditions. Outside religious observance, the date can involve family customs, chosen-family gatherings and practices that vary from household to household. There is no single meal, decoration or timetable shared by everyone who celebrates."},{"heading":"Make space for the day you have","body":"Some people welcome a busy table; others are working, resting or spending the day alone. A thoughtful message, an invitation with no pressure attached, or sharing a small tradition can be meaningful. If you are gathering, ask people which part of the day they value most. That can reveal a favourite song, a remembered recipe or a very particular family joke."}],"activity":{"text":"Send one personal message to someone who might appreciate company, or ask someone to tell you about a tradition they love.","label":"Explore the Christmas story","url":"https://www.churchofengland.org/liturgy/book-of-common-prayer/collects-epistles-and-gospels/christmas-day"},"sources":[{"label":"Church of England — Christmas Day, 25 December","url":"https://www.churchofengland.org/liturgy/book-of-common-prayer/collects-epistles-and-gospels/christmas-day","dateEvidence":true}]},"2026-12-26:national-thank-you-note-day":{"id":"2026-12-26:national-thank-you-note-day","date":"2026-12-26","verification":"independent-calendar","summary":"A proper thank-you can be wonderfully small. ✍️ National Thank You Note Day on 26 December is an informal reminder to put appreciation into words, especially after a gift, a kind gesture or someone’s hospitality.","sections":[{"heading":"Be specific, rather than elaborate","body":"The date follows Christmas, but the idea is not limited to presents. A note can recognise someone’s time, care or help as well. Mention what the person did and the difference it made to you. A few sincere lines are often more personal than a formal card filled with phrases that could have been written to anybody."},{"heading":"A note you can finish today","body":"Start with the thing you are grateful for, add a particular detail, and close warmly. For a gift sent from a distance, it is helpful to say that it arrived. For a visit, recall a moment you enjoyed. Handwriting can make the message feel tangible, but a thoughtful message in another form is better than waiting indefinitely for perfect stationery."}],"activity":{"text":"Write a three-sentence thank-you that names one specific thing the other person did and why it mattered to you.","label":"Get thank-you-note guidance","url":"https://emilypost.com/advice/thank-you-notes-to-send-or-not-to-send"},"sources":[{"label":"National Day Calendar — Thank You Note Day","url":"https://nationaldaycalendar.com/celebrations/national-thank-you-note-day-december-26","dateEvidence":true},{"label":"Emily Post Institute — thank-you-note guidance","url":"https://emilypost.com/advice/thank-you-notes-to-send-or-not-to-send","dateEvidence":false}]},"2026-12-28":{"id":"2026-12-28","date":"2026-12-28","verification":"independent-calendar","summary":"Shuffle the deck and settle the house rules first. 🃏 National Card Playing Day on 28 December is an informal US occasion for a game with friends, family or a comfortably competitive version of yourself.","sections":[{"heading":"One deck, many possibilities","body":"A standard deck can support games built around matching, memory, collecting sets or taking tricks. Card traditions vary between regions and households, which explains why two people can confidently remember different rules for the same game. The calendar day is an invitation to play rather than an official tournament, so you can choose something quick and familiar or learn a new format."},{"heading":"Try basic rummy","body":"Rummy revolves around drawing and discarding while forming groups and sequences. Pagat’s detailed rules explain one basic version and identify optional house rules separately. Before starting, agree which version you are using and how long you want to play. A practice hand with cards visible can help new players learn without spending the first round feeling lost."}],"activity":{"text":"Try a practice hand of basic rummy, or teach someone a card game you remember well using agreed rules.","label":"Learn basic rummy","url":"https://www.pagat.com/rummy/rummy.html"},"sources":[{"label":"National Day Calendar — Card Playing Day","url":"https://nationaldaycalendar.com/celebrations/national-card-playing-day-december-28","dateEvidence":true},{"label":"Pagat — basic rummy rules","url":"https://www.pagat.com/rummy/rummy.html","dateEvidence":false}]},"2026-12-29:national-pepper-pot-day":{"id":"2026-12-29:national-pepper-pot-day","date":"2026-12-29","verification":"independent-calendar","summary":"A warming soup with a history worth stirring through. 🥣 National Pepper Pot Day on 29 December is an informal US food observance associated with the spicy dish known as Philadelphia pepper pot.","sections":[{"heading":"Follow the people behind the pot","body":"Philadelphia pepper pot is connected with Caribbean food traditions and the enslaved Africans and free Black communities who brought and sold the dish in the city. It often included tripe, other inexpensive meat, vegetables and generous seasoning. Black women selling bowls in streets and markets were central to its place in Philadelphia food culture, not merely a footnote to a famous recipe."},{"heading":"History, rather than a convenient legend","body":"A popular story credits a Valley Forge army cook with inventing pepper pot during the Revolutionary War. That neat origin is not established history and can obscure the dish’s wider roots. A better starting point is the researched account of its ingredients, migration and street vendors. Notice how a familiar food can carry stories of work, trade and community as well as flavour."}],"activity":{"text":"Read the illustrated history of Philadelphia pepper pot and look closely at the depictions of its street vendors.","label":"Explore pepper pot’s history","url":"https://philadelphiaencyclopedia.org/essays/philadelphia-pepper-pot/"},"sources":[{"label":"National Day Calendar — Pepper Pot Day","url":"https://nationaldaycalendar.com/celebrations/national-pepper-pot-day-december-29/","dateEvidence":true},{"label":"Encyclopedia of Greater Philadelphia — researched history","url":"https://philadelphiaencyclopedia.org/essays/philadelphia-pepper-pot/","dateEvidence":false}],"researchNote":"The popular 29 December 1777 army-cook origin is treated as an unproven legend, not a historical fact."},"2026-12-31:hogmanay":{"id":"2026-12-31:hogmanay","date":"2026-12-31","verification":"organiser","summary":"Scotland knows how to send a year off. 🎉 Hogmanay is New Year’s Eve on 31 December, with traditions of music, visiting, symbolic gifts and looking back before stepping into whatever comes next.","sections":[{"heading":"First-footing and fresh starts","body":"First-footing means visiting someone after midnight as the first person to enter their home in the new year. Traditional gifts can include shortbread, coal or whisky, symbolising hopes for good fortune. Household cleaning and preparations also form part of Hogmanay customs. The details vary between communities and families, rather than following one fixed national script."},{"heading":"Auld Lang Syne and shared memories","body":"The song associated with Robert Burns has carried the New Year ritual far beyond Scotland. Its reflection on old acquaintances fits a celebration that looks backwards as well as forwards. You can borrow that spirit without staging a large party: choose a song, share something worth remembering from the year, and think about someone you would like to reconnect with."}],"activity":{"text":"Choose a favourite memory from the year and share it with someone you want to keep close in the next one.","label":"Discover Hogmanay traditions","url":"https://www.scotland.org/events/hogmanay"},"sources":[{"label":"Scotland.org — Hogmanay and its traditions","url":"https://www.scotland.org/events/hogmanay","dateEvidence":true}]}};
